#[cfg(target_arch = "wasm32")]
fn parse_get_link_flag(search: &str) -> bool {
    let trimmed = search.strip_prefix('?').unwrap_or(search);
    trimmed.split('&').any(|kv| kv == "getLink=on")
}

/// A4-Q4: the `?getLink=` gate, parsed once. Non-wasm builds (native
