/// Bulk SoA fetch — same source JSONL + cache as
/// [`fetch_landblock_spawns`], packed for one-shot typed-array
/// boundary crossing. See module-level SoA docs above.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_landblock_spawns_soa(
    cell_ids: Vec<u32>,
) -> Result<LandblockSpawnsSoa, JsValue> {
    let base_url = spawn_fetch::base_url().ok_or_else(|| {
        JsValue::from_str(
            "init_spawns_base_url must be called before fetch_landblock_spawns_soa",
        )
    })?;

    spawn_fetch::maybe_log_sha256(&base_url).await;

    let mut wcids: Vec<u32> = Vec::new();
    let mut weenie_types: Vec<u32> = Vec::new();
    let mut landblock_ids: Vec<u32> = Vec::new();
    let mut cells: Vec<u32> = Vec::new();
    let mut positions: Vec<f32> = Vec::new();
    let mut quaternions: Vec<f32> = Vec::new();
    let mut is_server_managed: Vec<u8> = Vec::new();
    let mut names: Vec<String> = Vec::new();

    // Fire all per-LB shard fetches concurrently. The previous serial
    // `for &cell_id in &cell_ids { fetch_one_lb.await }` paid 169
    // round-trips back-to-back on the 13x13 validator ring (~38 min
    // cold-cache). join_all collects the futures and polls them in
    // parallel; the result Vec preserves the input order so the
    // post-fetch SoA append below stays byte-identical to the
    // previous output. fetch_one_lb's CACHE is thread-local and the
    // wasm runtime is single-threaded, so concurrent .with borrows
    // can't race. Gameplay still fetches one LB at a time via the
    // non-SOA fetch_landblock_spawns path; only bulk SOA callers
    // (validator, capture scripts) see the win.
    let lb_keys: Vec<u32> = cell_ids.iter().map(|id| id & 0xFFFF_0000).collect();
    let fetches = lb_keys
        .iter()
        .map(|&lb_key| spawn_fetch::fetch_one_lb(&base_url, lb_key));
    let results = futures::future::join_all(fetches).await;

    for (lb_key, res) in lb_keys.iter().zip(results) {
        let recs = res.map_err(|e| JsValue::from_str(&e))?;
        for r in &recs {
            wcids.push(r.wcid);
            weenie_types.push(r.weenie_type);
            landblock_ids.push(*lb_key);
            cells.push(r.cell);
            positions.extend_from_slice(&[r.x, r.y, r.z]);
            quaternions.extend_from_slice(&[r.qw, r.qx, r.qy, r.qz]);
            is_server_managed.push(if r.is_server_managed { 1 } else { 0 });
            names.push(r.name.clone());
        }
    }
    Ok(LandblockSpawnsSoa {
        wcids,
        weenie_types,
        landblock_ids,
        cells,
        positions,
        quaternions,
        is_server_managed,
        names,
    })
}

/// Phase 1.4 diagnostic page support. Walks `LandblockInfo.objects` +
/// `.buildings` + every EnvCell in the landblock's cell-id range,
/// collects each model's referenced Surface DIDs (via the GfxObj
/// `surfaces` array, or — for SetupModel — every part's GfxObj
/// `surfaces`), and returns the sorted unique set. EnvCell `surfaces`
/// (u16 wire indices) are OR'd with the 0x08000000 namespace prefix
/// before emission.
///
/// `lb_cell_id` is the `0xXXYYFFFE` LandblockInfo cell key (Holtburg
/// = 0xA9B4FFFE). For LBs with no LandblockInfo (ocean / sparse) we
/// still scan the EnvCell range — most outdoor LBs will return an
/// empty list in that case.
///
/// One HTTP fetch (the LB's shard); per-id walks are in-memory after
/// the prefetch.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchLandblockSurfaceDids)]
pub async fn fetch_landblock_surface_dids(lb_cell_id: u32) -> Result<Vec<u32>, JsValue> {
    use holtburger_dat::file_type::env_cell::surface_did_for_envcell_index;
    use holtburger_dat::file_type::{EnvCell, GfxObj, SetupModel};
    use holtburger_dat::landblock::LandblockInfo;
    use holtburger_dat::{ResourceKey, ResourceSource};

    let source = global_source::global_source();
    // Prefetch the landblock's cell shard so subsequent cell reads are
    // in-memory. Portal reads (GfxObj / SetupModel) come from the
    // portal shard which is already warm from index init.
    let landblock_word = (lb_cell_id >> 16) & 0xFFFF;
    let info_id = (landblock_word << 16) | 0xFFFE;
    let initial = [ResourceKey::new("eor/cell", info_id)];
    source
        .prefetch(&initial)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch: {e}")))?;

    // Helper: resolve a (Setup or Gfx) model_id to its surface DIDs.
    fn surfaces_for_model<S: holtburger_dat::ResourceSource + ?Sized>(
        source: &S,
        model_id: u32,
    ) -> Vec<u32> {
        let top = (model_id >> 24) & 0xFF;
        match top {
            0x01 => {
                let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", model_id))
                else {
                    return Vec::new();
                };
                let mut cursor = std::io::Cursor::new(&bytes);
                let Ok(gfx) = GfxObj::unpack(&mut cursor) else {
                    return Vec::new();
                };
                gfx.surfaces
            }
            0x02 => {
                let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", model_id))
                else {
                    return Vec::new();
                };
                let Ok(setup) = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)) else {
                    return Vec::new();
                };
                let mut out = Vec::new();
                for part in setup.parts {
                    let Ok(pb) = source.get_file_by_key(ResourceKey::new("eor/portal", part))
                    else {
                        continue;
                    };
                    let mut pc = std::io::Cursor::new(&pb);
                    if let Ok(g) = GfxObj::unpack(&mut pc) {
                        out.extend(g.surfaces);
                    }
                }
                out
            }
            _ => Vec::new(),
        }
    }

    use std::collections::BTreeSet;
    let mut surfaces: BTreeSet<u32> = BTreeSet::new();

    // LandblockInfo placements.
    if let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/cell", info_id)) {
        if let Ok(info) = LandblockInfo::unpack(&bytes) {
            for stab in &info.objects {
                for s in surfaces_for_model(source.as_ref(), stab.id) {
                    surfaces.insert(s);
                }
            }
            for b in &info.buildings {
                for s in surfaces_for_model(source.as_ref(), b.model_id) {
                    surfaces.insert(s);
                }
            }
        }
    }

    // EnvCells. There's no enumerator on `ResourceSource` so the JS
    // page must enumerate envcell ids it cares about. For the
    // diagnostic page we just probe IDs 0xXXXX0001..0xXXXX01FF —
    // any retail interior has < 512 cells (Holtburg has ~16).
    let env_base = landblock_word << 16;
    for envcell_idx in 0x0001u32..=0x01FFu32 {
        let env_id = env_base | envcell_idx;
        let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/cell", env_id)) else {
            continue;
        };
        let mut cursor = std::io::Cursor::new(&bytes);
        let Ok(envcell) = EnvCell::unpack(&mut cursor) else {
            continue;
        };
        for wire_surf in &envcell.surfaces {
            surfaces.insert(surface_did_for_envcell_index(*wire_surf));
        }
        for stab in &envcell.static_objects {
            for s in surfaces_for_model(source.as_ref(), stab.stab_id) {
                surfaces.insert(s);
            }
        }
    }

    surfaces.remove(&0);
    Ok(surfaces.into_iter().collect())
}

/// Fetch all 33 retail terrain textures from `asset_url`, decoded to
/// RGBA8. Returns one [`TerrainTexture`] per `TerrainTextureType`
/// entry, in enum order (index = terrain code).
///
/// Pipeline per terrain type:
/// 1. Look up the canonical SurfaceTexture ID from
///    [`RETAIL_TERRAIN_SURFACE_TEXTURES`].
/// 2. Fetch + parse `eor/portal:<surface_texture_id>` into a
///    [`SurfaceTexture`].
/// 3. Take the highest-resolution mip-level
///    (`surface_texture.highest_res()`).
/// 4. Fetch + parse that `eor/portal:<texture_id>` into a [`Texture`].
/// 5. Decode pixels via [`Texture::to_rgba8`], lazily fetching a
///    [`Palette`] only if the format is palettized (P8 / Index16).
///
/// On any per-id failure the whole batch fails with a tagged error.
/// One HTTP fetch resolves the entire bundle; per-asset lookups are
/// in-memory after that.
///
/// Cost: AC's terrain mip-stacks top out around 256×256, so the
/// decompressed RGBA8 payload returned is roughly
/// `33 × 256 × 256 × 4 = ~8.6 MB` worst case. JS atlas-packs into a
/// single GPU texture and we drop the originals.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_terrain_textures() -> Result<Vec<TerrainTexture>, JsValue> {
    use holtburger_dat::file_type::{Palette, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::{ResourceKey, ResourceSource};

    let source = global_source::global_source();

    // Phase 5.0b — explicit per-level prefetch. The dependency
    // graph here is well-known: 33 SurfaceTextures → 33
    // Textures → up to 33 Palettes. Hand-rolled rather than
    // RecordingSource-driven because the levels are predictable.
    let surf_keys: Vec<ResourceKey<'_>> = RETAIL_TERRAIN_SURFACE_TEXTURES
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    source
        .prefetch(&surf_keys)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch SurfaceTextures: {e}")))?;

    let mut tex_ids: Vec<u32> = Vec::with_capacity(RETAIL_TERRAIN_SURFACE_TEXTURES.len());
    for &surf_id in RETAIL_TERRAIN_SURFACE_TEXTURES.iter() {
        if let Ok(b) = source.get_file_by_key(ResourceKey::new("eor/portal", surf_id))
            && let Ok(s) = SurfaceTexture::unpack(&b)
            && let Some(t) = s.highest_res()
        {
            tex_ids.push(t);
        }
    }
    let tex_keys: Vec<ResourceKey<'_>> = tex_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    source
        .prefetch(&tex_keys)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch Textures: {e}")))?;

    let mut pal_ids: Vec<u32> = Vec::new();
    for &tex_id in &tex_ids {
        if let Ok(b) = source.get_file_by_key(ResourceKey::new("eor/portal", tex_id))
            && let Ok(t) = Texture::unpack(&b)
            && let Some(pid) = t.default_palette_id
        {
            pal_ids.push(pid);
        }
    }
    if !pal_ids.is_empty() {
        let pal_keys: Vec<ResourceKey<'_>> = pal_ids
            .iter()
            .map(|id| ResourceKey::new("eor/portal", *id))
            .collect();
        source
            .prefetch(&pal_keys)
            .await
            .map_err(|e| JsValue::from_str(&format!("prefetch Palettes: {e}")))?;
    }

    let mut out = Vec::with_capacity(RETAIL_TERRAIN_SURFACE_TEXTURES.len());
    for (terrain_type, surf_id) in RETAIL_TERRAIN_SURFACE_TEXTURES.iter().copied().enumerate() {
        // SurfaceTexture (mip stack).
        let surf_bytes = source
            .get_file_by_key(ResourceKey::new("eor/portal", surf_id))
            .map_err(|e| JsValue::from_str(&format!("SurfaceTexture {surf_id:#010X}: {e}")))?;
        let surf = SurfaceTexture::unpack(&surf_bytes).map_err(|e| {
            JsValue::from_str(&format!("SurfaceTexture::unpack {surf_id:#010X}: {e}"))
        })?;
        let tex_id = surf.highest_res().ok_or_else(|| {
            JsValue::from_str(&format!("SurfaceTexture {surf_id:#010X}: empty mip list"))
        })?;

        // Texture (top mip-level).
        let tex_bytes = source
            .get_file_by_key(ResourceKey::new("eor/portal", tex_id))
            .map_err(|e| JsValue::from_str(&format!("Texture {tex_id:#010X}: {e}")))?;
        let tex = Texture::unpack(&tex_bytes)
            .map_err(|e| JsValue::from_str(&format!("Texture::unpack {tex_id:#010X}: {e}")))?;

        // Decode to RGBA8, lazily fetching a palette if needed.
        let rgba = tex
            .to_rgba8(|pal_id| {
                let pal_bytes = source
                    .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
                    .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
                Palette::unpack(&pal_bytes).map_err(|e| {
                    TextureDecodeError::PaletteFetch(format!("Palette::unpack {pal_id:#010X}: {e}"))
                })
            })
            .map_err(|e| JsValue::from_str(&format!("Texture::to_rgba8 {tex_id:#010X}: {e}")))?;

        out.push(TerrainTexture {
            terrain_type: terrain_type as u32,
            width: tex.width as u32,
            height: tex.height as u32,
            pixels: rgba,
        });
    }
    Ok(out)
}

/// Fetch the per-terrain-type vertex modulation ranges from the retail
/// Region (0x13000000) record. Returns a flat `Uint32Array` of
/// `33 × 6 = 198` u32s in row-major order: row `i` (terrain type `i`)
/// is `[min_bright, max_bright, min_sat, max_sat, min_hue, max_hue]`.
///
/// **Context (2026-05-28 audit).** Retail's `TerrainTex` carries six
/// u32 fields per terrain type (`(max|min)_vert_(bright|saturate|hue)`)
/// — see `holtburger_dat::file_type::region::TerrainTex:537-567` for
/// the parser. acclient.c only Pack/UnPacks the values; the rendering
/// path that would APPLY them was apparently cut before retail
/// shipped. However the values are deliberately authored (Ice = type
/// 2 and RoadType = 32 have `bright=30..60` vs `90..100` for natural
/// terrain), so wiring them as a per-vertex HSL nudge restores the
/// authors' intent.
///
/// Best-guess unit interpretation (no retail code to verify against):
/// `bright`/`saturate` as percentage in 0-100, `hue` as either degrees
/// or AC's internal 0-256. JS-side `terrain.js::buildVertexModulation`
/// owns the application.
///
/// Returns a `Vec<u32>` (one allocation) rather than a `Vec<struct>`
/// so the wasm-bindgen ABI doesn't need a new exported type. The
/// shape `Uint32Array(198)` is documented at the call site.
///
/// `0` for every channel when no Region is loaded (degenerate test
/// builds with empty DAT) — JS reads that as "no modulation, pass
/// through".
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_terrain_modulation_ranges() -> Result<Vec<u32>, JsValue> {
    use holtburger_dat::file_type::Region;
    use holtburger_dat::{ResourceKey, ResourceSource};
    let source = global_source::global_source();
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", 0x1300_0000))
        .map_err(|e| JsValue::from_str(&format!("Region 0x13000000: {e}")))?;
    let mut cursor = std::io::Cursor::new(&bytes[..]);
    let region = Region::unpack(&mut cursor)
        .map_err(|e| JsValue::from_str(&format!("Region::unpack: {e}")))?;
    // 33 terrain types × 6 channels = 198 u32s. Zero-fill for any
    // missing slot (Region writers don't always emit all 33; retail
    // ships 33).
    let mut out = vec![0u32; 33 * 6];
    for td in &region.terrain_info.land_surfaces.tex_merge.terrain_desc {
        let idx = td.terrain_type as usize;
        if idx >= 33 {
            continue;
        }
        let t = &td.terrain_tex;
        let base = idx * 6;
        out[base] = t.min_vert_bright;
        out[base + 1] = t.max_vert_bright;
        out[base + 2] = t.min_vert_saturate;
        out[base + 3] = t.max_vert_saturate;
        out[base + 4] = t.min_vert_hue;
        out[base + 5] = t.max_vert_hue;
    }
    Ok(out)
}

/// T1 (2026-05-29) — fetch the per-terrain-type **base** texture tiling
/// (`TerrainTex.tex_tiling`) as a 33-entry `Uint32Array` (terrain code →
/// tiling). Retail `tex_tiling == 2` for all 33 types; consumed by
/// `TexMerge::CopyAndTile`/`MergeTexture` (`acclient.c:304685,304854`) →
/// `TileCSI` (`acclient.c:365513`), a spatial N×N replication of the source
/// texture into the merged tile. The terrain shader mirrors that by sampling
/// the ClampToEdge atlas layer at `fract(cellUv * tiling)` (a raw `*tiling`
/// would clamp and cut the tile off — see `terrain.js::atlasUvFor`).
///
/// Mirrors [`fetch_terrain_modulation_ranges`] (same Region read, flat
/// `Vec<u32>` so the wasm-bindgen ABI needs no new type). Default `1` for any
/// slot the Region omits (degenerate/empty-DAT builds) so JS reads it as the
/// current 1× behaviour — the fail-soft fallback the default-on path requires.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_terrain_base_tex_tiling() -> Result<Vec<u32>, JsValue> {
    use holtburger_dat::file_type::Region;
    use holtburger_dat::{ResourceKey, ResourceSource};
    let source = global_source::global_source();
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", 0x1300_0000))
        .map_err(|e| JsValue::from_str(&format!("Region 0x13000000: {e}")))?;
    let mut cursor = std::io::Cursor::new(&bytes[..]);
    let region = Region::unpack(&mut cursor)
        .map_err(|e| JsValue::from_str(&format!("Region::unpack: {e}")))?;
    // 33 terrain codes. Default 1 (no tiling) for any slot the Region
    // doesn't emit so a partial/empty Region is fail-soft to the prior
    // 1× render rather than scaling by 0.
    let mut out = vec![1u32; 33];
    for td in &region.terrain_info.land_surfaces.tex_merge.terrain_desc {
        let idx = td.terrain_type as usize;
        if idx >= 33 {
            continue;
        }
        out[idx] = td.terrain_tex.tex_tiling;
    }
    Ok(out)
}

/// T7 — build the per-code detail-texture LUTs from `(terrain_type,
/// detail_texture_id, detail_tex_tiling)` triples (one per `TMTerrainDesc`).
///
/// Returns `(code_to_slice, code_tiling, unique_dids)`:
/// - `code_to_slice[c]` (33 entries) = index into `unique_dids` for terrain
///   code `c`, or `255` when the code has no detail texture (`did == 0`) or
///   isn't present in the input.
/// - `code_tiling[c]` (33 entries) = the code's `detail_tex_tiling`
///   (default 1 for absent codes).
/// - `unique_dids` = distinct detail texture DIDs in first-seen order; the
///   shader binds one `sampler2DArray` layer per entry.
///
/// Pure (no DAT / no wasm) so it's host-unit-testable. Mirrors acclient
/// `TexMerge::GetDetailTex`/`GetDetailTiling` (per-`terrain_number` lookup,
/// `acclient.c:304939,304957`) but deduplicates because retail authors only
/// ~3 distinct detail textures across the 33 types.
fn build_detail_texture_luts(entries: &[(u32, u32, u32)]) -> (Vec<u32>, Vec<u32>, Vec<u32>) {
    let mut code_to_slice = vec![255u32; 33];
    let mut code_tiling = vec![1u32; 33];
    let mut unique: Vec<u32> = Vec::new();
    for &(code, did, tiling) in entries {
        let c = code as usize;
        if c >= 33 {
            continue;
        }
        code_tiling[c] = tiling;
        if did == 0 {
            continue;
        }
        let slice = match unique.iter().position(|&u| u == did) {
            Some(i) => i,
            None => {
                unique.push(did);
                unique.len() - 1
            }
        };
        code_to_slice[c] = slice as u32;
    }
    (code_to_slice, code_tiling, unique)
}

/// T7 — fetch the retail per-terrain-type **detail textures** (the
/// near-camera high-frequency diffuse layer retail modulates the merged
/// base tile by) and the LUTs the terrain shader uses to apply them.
///
/// Pipeline:
/// 1. Read Region `0x13000000` → `terrain_desc` (per-type `detail_tex_gid`
///    + `detail_tex_tiling`).
/// 2. [`build_detail_texture_luts`] dedups the detail DIDs (retail ships ~3
///    distinct across 33 codes) and builds the `code → slice` + `code →
///    tiling` LUTs.
/// 3. Decode each unique detail SurfaceTexture → RGBA8 via the same
///    SurfaceTexture → highest-res Texture → palette pipeline as
///    [`fetch_terrain_textures`].
///
/// Returns a [`TerrainDetailTextures`]. Caller (`terrain.js`) builds a
/// `sampler2DArray` from `slices` and binds the LUTs as `int[33]` uniforms.
/// Opt-in (`?terrainDetailTex=on`) — `terrain.js` only calls this when the
/// flag is set, so default boot pays nothing.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_terrain_detail_textures() -> Result<TerrainDetailTextures, JsValue> {
    use holtburger_dat::file_type::{
        Palette, Region, SurfaceTexture, Texture, TextureDecodeError,
    };
    use holtburger_dat::{ResourceKey, ResourceSource};

    let source = global_source::global_source();

    // 1. Region → per-type detail DID + tiling.
    let region_bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", 0x1300_0000))
        .map_err(|e| JsValue::from_str(&format!("Region 0x13000000: {e}")))?;
    let region = Region::unpack(&mut std::io::Cursor::new(&region_bytes[..]))
        .map_err(|e| JsValue::from_str(&format!("Region::unpack: {e}")))?;

    let entries: Vec<(u32, u32, u32)> = region
        .terrain_info
        .land_surfaces
        .tex_merge
        .terrain_desc
        .iter()
        .map(|td| {
            (
                td.terrain_type,
                td.terrain_tex.detail_texture_id,
                td.terrain_tex.detail_tex_tiling,
            )
        })
        .collect();
    let (code_to_slice, code_tiling, unique_ids) = build_detail_texture_luts(&entries);

    // 2. Prefetch the unique detail SurfaceTextures, then their highest-res
    //    Textures, then palettes (mirrors fetch_terrain_textures levels).
    let surf_keys: Vec<ResourceKey<'_>> = unique_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    source
        .prefetch(&surf_keys)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch detail SurfaceTextures: {e}")))?;

    let mut tex_ids: Vec<u32> = Vec::with_capacity(unique_ids.len());
    for &surf_id in &unique_ids {
        if let Ok(b) = source.get_file_by_key(ResourceKey::new("eor/portal", surf_id))
            && let Ok(s) = SurfaceTexture::unpack(&b)
            && let Some(t) = s.highest_res()
        {
            tex_ids.push(t);
        }
    }
    let tex_keys: Vec<ResourceKey<'_>> = tex_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    source
        .prefetch(&tex_keys)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch detail Textures: {e}")))?;

    let mut pal_ids: Vec<u32> = Vec::new();
    for &tex_id in &tex_ids {
        if let Ok(b) = source.get_file_by_key(ResourceKey::new("eor/portal", tex_id))
            && let Ok(t) = Texture::unpack(&b)
            && let Some(pid) = t.default_palette_id
        {
            pal_ids.push(pid);
        }
    }
    if !pal_ids.is_empty() {
        let pal_keys: Vec<ResourceKey<'_>> = pal_ids
            .iter()
            .map(|id| ResourceKey::new("eor/portal", *id))
            .collect();
        source
            .prefetch(&pal_keys)
            .await
            .map_err(|e| JsValue::from_str(&format!("prefetch detail Palettes: {e}")))?;
    }

    // 3. Decode each unique detail texture to RGBA8. slice index = position
    //    in `unique_ids` (matches `code_to_slice`).
    let mut slices = Vec::with_capacity(unique_ids.len());
    for (slice_idx, surf_id) in unique_ids.iter().copied().enumerate() {
        let surf_bytes = source
            .get_file_by_key(ResourceKey::new("eor/portal", surf_id))
            .map_err(|e| JsValue::from_str(&format!("detail SurfaceTexture {surf_id:#010X}: {e}")))?;
        let surf = SurfaceTexture::unpack(&surf_bytes).map_err(|e| {
            JsValue::from_str(&format!("detail SurfaceTexture::unpack {surf_id:#010X}: {e}"))
        })?;
        let tex_id = surf.highest_res().ok_or_else(|| {
            JsValue::from_str(&format!("detail SurfaceTexture {surf_id:#010X}: empty mip list"))
        })?;
        let tex_bytes = source
            .get_file_by_key(ResourceKey::new("eor/portal", tex_id))
            .map_err(|e| JsValue::from_str(&format!("detail Texture {tex_id:#010X}: {e}")))?;
        let tex = Texture::unpack(&tex_bytes)
            .map_err(|e| JsValue::from_str(&format!("detail Texture::unpack {tex_id:#010X}: {e}")))?;
        let rgba = tex
            .to_rgba8(|pal_id| {
                let pal_bytes = source
                    .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
                    .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
                Palette::unpack(&pal_bytes).map_err(|e| {
                    TextureDecodeError::PaletteFetch(format!("Palette::unpack {pal_id:#010X}: {e}"))
                })
            })
            .map_err(|e| JsValue::from_str(&format!("detail Texture::to_rgba8 {tex_id:#010X}: {e}")))?;

        slices.push(TerrainTexture {
            terrain_type: slice_idx as u32,
            width: tex.width as u32,
            height: tex.height as u32,
            pixels: rgba,
        });
    }

    Ok(TerrainDetailTextures {
        slices,
        code_to_slice,
        code_tiling,
    })
}

/// Phase 3 step 3.6 — fetch the retail TexMerge alpha masks (corner,
/// side, road) and decode each to RGBA8. Mirrors
/// [`fetch_terrain_textures`] but for the PFID_A8 mask textures the
/// authentic AC terrain renderer composites overlays through.
///
/// **Why a separate export.** Splitting alpha masks out of
/// `fetch_terrain_textures` keeps the original 33-texture path
/// unchanged for callers that don't need the authentic blend (the
/// pre-3.6 shader continues to work). New callers can `await
/// fetch_terrain_alpha_masks()` once at boot, build an atlas, and
/// drop the originals.
///
/// **Round-trip cost.** Each mask is at most 1024×1024 PFID_A8
/// (1 MB compressed pre-bake; ~4 MB after decode-to-RGBA8 in
/// the existing `Texture::to_rgba8` greyscale-replicate path). 8
/// masks worst-case ≈ 32 MB; in practice the masks decode at
/// 256×256 or 512×512 → 4 MB total. Single fetch + decode round
/// at boot, kept resident for the lifetime of the renderer.
///
/// **R channel = mask weight.** The decoder fills R=G=B=alpha and
/// A=255; JS reads `r / 255` for the blend factor.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_terrain_alpha_masks() -> Result<TerrainAlphaMasks, JsValue> {
    use holtburger_dat::file_type::{Palette, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::{ResourceKey, ResourceSource};

    let source = global_source::global_source();

    // Collect all 8 alpha-mask SurfaceTexture IDs in one pass so
    // the prefetch goes through the network once. PRNG selection
    // is JS-side; the wasm path just decodes everything.
    let all_ids: Vec<u32> = RETAIL_CORNER_TERRAIN_MASKS
        .iter()
        .chain(RETAIL_SIDE_TERRAIN_MASKS.iter())
        .chain(RETAIL_ROAD_MASKS.iter())
        .map(|(_code, gid)| *gid)
        .collect();

    let surf_keys: Vec<ResourceKey<'_>> = all_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    source
        .prefetch(&surf_keys)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch alpha SurfaceTextures: {e}")))?;

    // SurfaceTexture → top-mip Texture id. PFID_A8 masks aren't
    // palettized, so we skip the Palette prefetch the terrain path
    // does. They might still chain through a Texture's default
    // palette in theory; we lazy-fetch in `to_rgba8` if so.
    let mut tex_ids: Vec<u32> = Vec::with_capacity(all_ids.len());
    for &surf_id in &all_ids {
        if let Ok(b) = source.get_file_by_key(ResourceKey::new("eor/portal", surf_id))
            && let Ok(s) = SurfaceTexture::unpack(&b)
            && let Some(t) = s.highest_res()
        {
            tex_ids.push(t);
        } else {
            tex_ids.push(0);
        }
    }
    let tex_keys: Vec<ResourceKey<'_>> = tex_ids
        .iter()
        .filter(|t| **t != 0)
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    source
        .prefetch(&tex_keys)
        .await
        .map_err(|e| JsValue::from_str(&format!("prefetch alpha Textures: {e}")))?;

    // Decode helper — same logic three times for corner / side /
    // road, factored out to keep the constants list close to the
    // RETAIL_* tables above.
    let decode_one = |idx: usize, code: u32, surf_id: u32| -> Result<TerrainAlphaMask, JsValue> {
        let surf_bytes = source
            .get_file_by_key(ResourceKey::new("eor/portal", surf_id))
            .map_err(|e| JsValue::from_str(&format!("alpha SurfaceTexture {surf_id:#010X}: {e}")))?;
        let surf = SurfaceTexture::unpack(&surf_bytes)
            .map_err(|e| JsValue::from_str(&format!("SurfaceTexture::unpack {surf_id:#010X}: {e}")))?;
        let tex_id = surf
            .highest_res()
            .ok_or_else(|| JsValue::from_str(&format!("alpha {surf_id:#010X}: empty mip list")))?;
        let tex_bytes = source
            .get_file_by_key(ResourceKey::new("eor/portal", tex_id))
            .map_err(|e| JsValue::from_str(&format!("alpha Texture {tex_id:#010X}: {e}")))?;
        let tex = Texture::unpack(&tex_bytes)
            .map_err(|e| JsValue::from_str(&format!("Texture::unpack {tex_id:#010X}: {e}")))?;
        let rgba = tex
            .to_rgba8(|pal_id| {
                let pal_bytes = source
                    .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
                    .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
                Palette::unpack(&pal_bytes).map_err(|e| {
                    TextureDecodeError::PaletteFetch(format!("Palette::unpack {pal_id:#010X}: {e}"))
                })
            })
            .map_err(|e| JsValue::from_str(&format!("Texture::to_rgba8 {tex_id:#010X}: {e}")))?;
        Ok(TerrainAlphaMask {
            index: idx as u32,
            code,
            width: tex.width as u32,
            height: tex.height as u32,
            pixels: rgba,
        })
    };

    let mut corner = Vec::with_capacity(RETAIL_CORNER_TERRAIN_MASKS.len());
    for (i, (code, gid)) in RETAIL_CORNER_TERRAIN_MASKS.iter().copied().enumerate() {
        corner.push(decode_one(i, code, gid)?);
    }
    let mut side = Vec::with_capacity(RETAIL_SIDE_TERRAIN_MASKS.len());
    for (i, (code, gid)) in RETAIL_SIDE_TERRAIN_MASKS.iter().copied().enumerate() {
        side.push(decode_one(i, code, gid)?);
    }
    let mut road = Vec::with_capacity(RETAIL_ROAD_MASKS.len());
    for (i, (code, gid)) in RETAIL_ROAD_MASKS.iter().copied().enumerate() {
        road.push(decode_one(i, code, gid)?);
    }

    Ok(TerrainAlphaMasks { corner, side, road })
}

/// Phase 3 step 4.5: walk one model's GfxObj/SetupModel surface chain
/// and return the first resolvable ARGB. `0` means "no colour
/// resolved" — the JS caller falls back to the existing 2-bucket
/// category tint for that model.
///
/// Walk shape:
/// - `0x01XXXXXX` (Model / GfxObj) → read GfxObj's `surfaces` list,
///   iterate, return the first surface that resolves to ARGB.
/// - `0x02XXXXXX` (SetupModel) → read SetupModel, iterate `parts`
///   (each part is a GfxObj id), recurse via the GfxObj path.
/// - Any other top byte → `None` (unhandled type).
///
/// **Surface resolution** tries two paths in order:
/// 1. Solid path: if the surface stored a `color_value`, return it.
/// 2. Textured path: fetch the referenced Texture (and Palette if
///    palettized), decode to RGBA8, return the **mean ARGB** over
///    every pixel. This is what gives Holtburg's brown-house cluster
///    real colour variety — almost every surface in retail is
///    textured (97% in our sweep), so a solid-only walk would
///    resolve <3% of models.
///
/// **Why the minimal GfxObj reader.** The full `GfxObj::unpack` parser
/// in `holtburger-dat` parses vertex / polygon / BSP data after the
/// surface list, and currently fails on roughly half of retail's
/// GfxObj records (`failed to fill whole buffer` on internal subfields).
/// Step 4.5 only needs the surface IDs, so we read a minimal header
/// (`id`, `flags`, `read_smart_vec(u32)` of surfaces) and stop. This
/// raises the surface-list extraction success rate from ~50% to
/// ~100% on the same bundle without depending on fixes to the full
/// parser. If/when the GfxObj parser regression is resolved upstream,
/// `walk_gfx_obj` can switch back to it without changing the public
/// API.
#[cfg(target_arch = "wasm32")]
fn resolve_model_color<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    model_id: u32,
) -> Option<u32> {
    match (model_id >> 24) as u8 {
        0x01 => walk_gfx_obj(source, model_id),
        0x02 => walk_setup_model(source, model_id, 0),
        _ => None,
    }
}

/// Read just the `surfaces: Vec<u32>` list from a GfxObj record.
/// Header layout: `[u32 id][u32 flags][smart_vec u32 surfaces]`. Stops
/// after the surface list — the rest of the record (vertex array,
/// polygons, BSP) is irrelevant to step 4.5 and is the source of
/// failures in the full parser. See `resolve_model_color` doc.
///
/// Manual byte parsing (rather than calling through to `holtburger_dat::utils`)
/// keeps `binrw` out of `holtburger-web`'s dep graph — the format is
/// fixed, the surface-count varint is well-defined, and the parser
/// shape is small enough that the dep would be pure overhead.
#[cfg(target_arch = "wasm32")]
fn read_gfx_obj_surfaces(bytes: &[u8]) -> Option<Vec<u32>> {
    if bytes.len() < 9 {
        return None;
    }
    // Skip [u32 id][u32 flags] = 8 bytes.
    let mut pos = 8usize;
    let (count, n) = read_compressed_u32(&bytes[pos..])?;
    pos += n;
    let count = count as usize;
    if bytes.len() < pos.checked_add(count * 4)? {
        return None;
    }
    let mut surfaces = Vec::with_capacity(count);
    for i in 0..count {
        let off = pos + i * 4;
        let id = u32::from_le_bytes([
            bytes[off],
            bytes[off + 1],
            bytes[off + 2],
            bytes[off + 3],
        ]);
        surfaces.push(id);
    }
    Some(surfaces)
}

/// Mirrors `holtburger_dat::utils::read_compressed_u32`. Variable-width
/// 1/2/4-byte little-endian count used by AC's `read_smart_vec`.
/// Returns `(value, bytes_consumed)`.
#[cfg(target_arch = "wasm32")]
fn read_compressed_u32(bytes: &[u8]) -> Option<(u32, usize)> {
    let b0 = *bytes.first()? as u32;
    if (b0 & 0x80) == 0 {
        Some((b0, 1))
    } else if (b0 & 0x40) == 0 {
        let b1 = *bytes.get(1)? as u32;
        Some((((b0 & 0x7F) << 8) | b1, 2))
    } else {
        let b1 = *bytes.get(1)? as u32;
        let s = u16::from_le_bytes([*bytes.get(2)?, *bytes.get(3)?]) as u32;
        Some(((((b0 & 0x3F) << 8) | b1) << 16 | s, 4))
    }
}

#[cfg(target_arch = "wasm32")]
fn lookup_surface_color<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    surface_id: u32,
) -> Option<u32> {
    use holtburger_dat::file_type::{Palette, Surface, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::ResourceKey;
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", surface_id))
        .ok()?;
    let surface = Surface::unpack(&bytes).ok()?;
    if let Some(argb) = surface.solid_color() {
        return Some(argb);
    }
    // Textured path: Surface → SurfaceTexture → Texture (RenderSurface)
    // → RGBA8 → mean every pixel. Field-naming footgun: the field is
    // called `OrigTextureId` upstream and our `textured()` returns it
    // as the first tuple element, but it's actually a **SurfaceTexture
    // (0x05) ID** — not a Texture/RenderSurface (0x06) ID. Confirmed
    // by `WorldBuilder.Shared/Lib/Texture/RenderSurfaceImporter.cs`'s
    // `CreateSurface(gid, surfaceTextureGid)` builder, and by sampling
    // real Holtburg surfaces (`OrigTextureId = 0x0500…`). The walk
    // mirrors `fetch_terrain_textures` from step 3.5 (which already
    // got this chain right): SurfaceTexture.highest_res() is the
    // top-mip RenderSurface ID we feed to `Texture::unpack`.
    let (surf_tex_id, _pal_id_in_surface) = surface.textured()?;
    let surf_tex_bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", surf_tex_id))
        .ok()?;
    let surf_tex = SurfaceTexture::unpack(&surf_tex_bytes).ok()?;
    let render_surface_id = surf_tex.highest_res()?;
    let tex_bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", render_surface_id))
        .ok()?;
    let tex = Texture::unpack(&tex_bytes).ok()?;
    // Use the texture's `default_palette_id` for the palette fetch,
    // not the Surface's `orig_palette_id` — most retail textures embed
    // the right palette ref in the Texture record itself, while the
    // Surface's `orig_palette_id` is often 0.
    let rgba = tex
        .to_rgba8(|pal_id| {
            let pal_bytes = source
                .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
                .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
            Palette::unpack(&pal_bytes).map_err(|e| {
                TextureDecodeError::PaletteFetch(format!("Palette::unpack {pal_id:#010X}: {e}"))
            })
        })
        .ok()?;
    Some(rgba_pixel_mean(&rgba))
}

/// Mean of every pixel in an RGBA8 buffer, returned as a 0xAARRGGBB
/// ARGB. Saturated alpha (`0xFF`) so the renderer doesn't accidentally
/// transparent-tint a sprite.
#[cfg(target_arch = "wasm32")]
fn rgba_pixel_mean(rgba: &[u8]) -> u32 {
    if rgba.len() < 4 {
        return 0;
    }
    let pixels = rgba.len() / 4;
    let mut r_sum: u64 = 0;
    let mut g_sum: u64 = 0;
    let mut b_sum: u64 = 0;
    let mut weighted: u64 = 0;
    for i in 0..pixels {
        let r = rgba[i * 4] as u64;
        let g = rgba[i * 4 + 1] as u64;
        let b = rgba[i * 4 + 2] as u64;
        let a = rgba[i * 4 + 3] as u64;
        // Premultiplied-by-alpha average so transparent pixels don't
        // bleach the result toward black.
        r_sum += r * a;
        g_sum += g * a;
        b_sum += b * a;
        weighted += a;
    }
    if weighted == 0 {
        return 0;
    }
    let r = (r_sum / weighted) as u32;
    let g = (g_sum / weighted) as u32;
    let b = (b_sum / weighted) as u32;
    0xFF000000 | (r << 16) | (g << 8) | b
}

#[cfg(target_arch = "wasm32")]
fn walk_gfx_obj<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    gfx_obj_id: u32,
) -> Option<u32> {
    use holtburger_dat::ResourceKey;
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", gfx_obj_id))
        .ok()?;
    let surfaces = read_gfx_obj_surfaces(&bytes)?;
    for surface_id in surfaces {
        if let Some(c) = lookup_surface_color(source, surface_id) {
            return Some(c);
        }
    }
    None
}

#[cfg(target_arch = "wasm32")]
fn walk_setup_model<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
    depth: usize,
) -> Option<u32> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    // Recursion guard: AC SetupModel parts are GfxObj ids
    // (`0x01XXXXXX`), not SetupModels, so depth never exceeds 1 in
    // practice. The bound here is a defensive cap against a malformed
    // record that points back at a SetupModel id.
    if depth > 4 {
        return None;
    }
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        .ok()?;
    let setup = SetupModel::unpack(&mut std::io::Cursor::new(bytes)).ok()?;
    for part_id in setup.parts {
        let candidate = match (part_id >> 24) as u8 {
            0x01 => walk_gfx_obj(source, part_id),
            0x02 => walk_setup_model(source, part_id, depth + 1),
            _ => None,
        };
        if let Some(c) = candidate {
            return Some(c);
        }
    }
    None
}

/// Phase 3 step 4.5: resolve a per-model ARGB colour for each `model_id`
/// in the input list. Output length matches input length. `0` means the
/// walk did not resolve a colour for that model — the JS caller treats
/// `0` as a miss and falls back to the existing 2-bucket category tint.
///
/// One `HttpResourceSource::connect` open per call; per-id walks are
/// in-memory after that. Cost is bounded by the number of UNIQUE model
/// IDs in the visible neighbourhood (67 for Holtburg's 3×3); JS dedupes
/// the input list before calling.
///
/// Failure modes: a connect error rejects the whole Promise. Per-id
/// walk failures (missing GfxObj, malformed Surface bytes) are silent
/// — the walk just returns `None` for that id. This matches the
/// graceful-degradation shape from step 4: a partially-resolved batch
/// still renders, just with category-tint fallbacks for the unresolved
/// ids.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_object_colours(model_ids: Vec<u32>) -> Result<Vec<u32>, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();

    // Iterative discovery: walk against a RecordingSource, prefetch
    // recorded misses, repeat until cache hot. The walk depth here
    // is unbounded (SetupModel → parts → GfxObj → surfaces → ...).
    let initial: Vec<ResourceKey<'_>> = model_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    let model_ids_for_walk = model_ids.clone();
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        for &id in &model_ids_for_walk {
            let _ = resolve_model_color(s, id);
        }
    })
    .await?;

    let mut out = Vec::with_capacity(model_ids.len());
    for &id in &model_ids {
        out.push(resolve_model_color(source.as_ref(), id).unwrap_or(0));
    }
    Ok(out)
}

// ────────────────────────────────────────────────────────────────────
//  Phase 3 step 6 — model triangulation for runtime per-poly rendering
// ────────────────────────────────────────────────────────────────────
//
// Ports `WorldBuilder.Terminal/ObjectSpriteGenerator.cs::TriangulateModel`
// + `AppendGfxTris` to Rust. Returns a flat triangle list per model so
// JS can render each (model, surface) sub-mesh via PIXI.Mesh + a
// custom GLSL fragment shader, then RenderTexture-cache the result.
//
// Format choice: per-triangle vertex duplication (no index buffer).
// Mirrors the C# reference and lets PIXI.Geometry consume the buffers
// directly without a pre-pass to dedupe vertices. Memory is bounded
// (one tile per visible model, dropped on cache eviction) so the
// extra bytes don't matter; the simplicity at the JS boundary does.
//
// SetupModel (multi-part) walks `parts` and applies each part's idle
// or default-placement frame transform — matching the static-site
// emitter's pose resolution. For step 6 v1 we only apply the default
// placement frame (no animation lookup); idle-pose support is
// step 6 follow-on.

/// Per-triangle output of [`triangulate_model`]. Three vertex tuples
/// per triangle (no shared indexing), each carrying position, UV, and
/// the surface index.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct ModelMesh {
    /// 9 floats per triangle (3 vertices × xyz). Length = `tri_count * 9`.
    positions: Vec<f32>,
    /// 6 floats per triangle (3 vertices × uv). Length = `tri_count * 6`.
    uvs: Vec<f32>,
    /// T6: 9 floats per triangle (PER-VERTEX normals — authored
    /// `SWVertex.normal`, fallback face normal). Length = `tri_count * 9`.
    normals: Vec<f32>,
    /// One byte per triangle, indexing into `surfaces`. Length = `tri_count`.
    /// `0xFF` means "no surface" (caller paints flat fallback).
    surface_indices: Vec<u8>,
    /// T2: one byte per triangle = the polygon `sides_type` (the per-poly
    /// cull bit). `1` = two-sided (DoubleSide); else single-sided (FrontSide
    /// under `?perPolyCull`). Length = `tri_count`.
    sides_types: Vec<u8>,
    /// Unique surface DIDs referenced by the model's polygons, in
    /// first-seen order. JS resolves each to RGBA8 via the existing
    /// surface chain (Surface → SurfaceTexture → Texture → to_rgba8).
    surfaces: Vec<u32>,
    /// World-space bbox over all vertices. JS uses (max - min) to size
    /// the destination RenderTexture.
    bbox_min: [f32; 3],
    bbox_max: [f32; 3],
    /// Follow-on #5 (LOD) — the model's `did_degrade` chain entry, or
    /// 0 if the GfxObj has no `HAS_DID_DEGRADE` flag set. For 0x01 raw
    /// GfxObjs this is the model's own degrade DID; for 0x02 SetupModels
    /// it's the first part GfxObj's degrade DID (sufficient for Holtburg,
    /// which has mostly single-part SetupModels). 0 = no degraded
    /// variant available; JS-side LOD wrappers fall back to a plain
    /// `THREE.Mesh` instead of `THREE.LOD`.
    did_degrade: u32,
    /// E8 (2026-06-08): one source polygon id per emitted triangle.
    /// Length = `tri_count`. ADDITIVE + OPTIONAL — existing consumers that
    /// only read positions/uvs/indices are unaffected. Pairs with
    /// `side_kinds` for round-trip validation and ML training data.
    ///
    /// UNIQUENESS CAVEAT: a `polygon_id` is the source `gfx.polygons` /
    /// `cell.polygons` key, which is unique only WITHIN a single source
    /// GfxObj / EnvCell. The aggregated single-mesh export paths
    /// (`triangulate_setup_model_at_frame` flattens every SetupModel part's
    /// tris, and `append_environment_tris` flattens the SELECTED cell's tris
    /// into one `ModelMesh`) reset their polygon-id namespace per part / per
    /// cell, so two different source polygons in different parts/cells can
    /// share the same `polygon_id`. For globally-unique per-tri provenance
    /// across a multi-part model, use the per-part export
    /// (`triangulate_setup_model_per_part`) where each part is packed into
    /// its own `ModelMesh` and the `(polygon_id, side_kind)` pair is unique.
    polygon_ids: Vec<u16>,
    /// E8 (2026-06-08): one [`SideKind`] (as `u8`) per emitted triangle —
    /// `0` Positive, `1` PositiveReversed, `2` Negative. Length =
    /// `tri_count`. Crosses the wasm boundary as a `Uint8Array` (mirrors
    /// `sides_types`). Pairs with `polygon_ids`.
    side_kinds: Vec<u8>,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl ModelMesh {
    #[wasm_bindgen(getter)]
    pub fn positions(&self) -> Vec<f32> { self.positions.clone() }
    #[wasm_bindgen(getter)]
    pub fn uvs(&self) -> Vec<f32> { self.uvs.clone() }
    #[wasm_bindgen(getter)]
    pub fn normals(&self) -> Vec<f32> { self.normals.clone() }
    #[wasm_bindgen(getter, js_name = surfaceIndices)]
    pub fn surface_indices(&self) -> Vec<u8> { self.surface_indices.clone() }
    /// T2: per-triangle `sides_type` (cull bit). Length = `tri_count`.
    #[wasm_bindgen(getter, js_name = sidesTypes)]
    pub fn sides_types(&self) -> Vec<u8> { self.sides_types.clone() }
    #[wasm_bindgen(getter)]
    pub fn surfaces(&self) -> Vec<u32> { self.surfaces.clone() }
    #[wasm_bindgen(getter, js_name = triCount)]
    pub fn tri_count(&self) -> u32 {
        (self.positions.len() / 9) as u32
    }
    /// `[minX, minY, minZ, maxX, maxY, maxZ]` — flat for typed-array
    /// transit. JS reads pairs (idx 0..3 = min, 3..6 = max).
    #[wasm_bindgen(getter)]
    pub fn bbox(&self) -> Vec<f32> {
        let mut v = Vec::with_capacity(6);
        v.extend_from_slice(&self.bbox_min);
        v.extend_from_slice(&self.bbox_max);
        v
    }
    /// World metres on (X, Y) — what JS uses as the sprite footprint
    /// when blitting the rendered tile back into the scene.
    #[wasm_bindgen(getter, js_name = worldBounds)]
    pub fn world_bounds(&self) -> Vec<f32> {
        vec![
            self.bbox_max[0] - self.bbox_min[0],
            self.bbox_max[1] - self.bbox_min[1],
        ]
    }
    /// Follow-on #5 (LOD) — the model's `did_degrade` chain entry
    /// (0 = no degraded variant). JS-side `statics.js` / `buildings.js`
    /// wrap the full + degraded variants in a `THREE.LOD` node when this
    /// is non-zero; the JS-side `fetch_model_meshes([didDegrade])` round-
    /// trip fetches the degraded geometry for the LOD's distance-100m
    /// slot. The full variant remains at distance 0.
    #[wasm_bindgen(getter, js_name = didDegrade)]
    pub fn did_degrade(&self) -> u32 {
        self.did_degrade
    }
    /// E8 — per-triangle source polygon id (`Uint16Array`). Length =
    /// `tri_count`. ADDITIVE: consumers that ignore it are unaffected.
    #[wasm_bindgen(getter, js_name = polygonIds)]
    pub fn polygon_ids(&self) -> Vec<u16> { self.polygon_ids.clone() }
    /// E8 — per-triangle polygon SIDE (`Uint8Array` of [`SideKind`] u8s:
    /// `0` Positive, `1` PositiveReversed, `2` Negative). Length =
    /// `tri_count`. Pairs with `polygonIds` for full (polygon, side)
    /// provenance.
    #[wasm_bindgen(getter, js_name = sideKinds)]
    pub fn side_kinds(&self) -> Vec<u8> { self.side_kinds.clone() }
}

/// E8 (2026-06-08): per-polygon-side material traceability tag. Mirrors
/// upstream `PreparedPolygonRenderSideKind` so each exported triangle
/// records which SIDE of its source polygon it represents (round-trip
/// validation / ML training data). Paired with `polygon_id`, this gives
/// `(polygon, side)` provenance — globally unique on the per-part export
/// path; per-source-part only on the aggregated single-mesh path (see the
/// uniqueness caveat on [`ModelMesh::polygon_ids`]). Discriminants are
/// explicit + `#[repr(u8)]` so the value survives the typed-array boundary
/// unchanged (`ModelMesh.sideKinds` is a `Uint8Array` of these values, one
/// per emitted tri).
///
/// - `Positive` — the polygon's positive (front) face, original winding,
///   `pos_surface` material. This is the only kind a single-sided poly emits.
/// - `PositiveReversed` — the positive face emitted with REVERSED winding.
///   Reserved for parity with the upstream enum; the current triangulator
///   does not emit it (back faces use the negative surface → `Negative`),
///   but it is part of the round-trip contract so downstream consumers can
///   distinguish a flipped-positive draw from a true negative-side draw.
/// - `Negative` — the polygon's negative (back) face: reversed winding +
///   negated normals + `neg_surface` material. Emitted only for two-sided
///   polys (`sides_type == CullMode::Clockwise`) with a DISTINCT back
///   surface (see `append_gfx_tris_with_tex_swaps`).
#[cfg(any(target_arch = "wasm32", test))]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum SideKind {
    Positive = 0,
    PositiveReversed = 1,
    Negative = 2,
}

/// Internal triangle accumulator. Mirrors `ObjectSpriteGenerator.Tri`
/// in the C# reference, minus the centroid-Z (we sort painter-style
/// in JS instead of in Rust — simpler boundary).
#[cfg(any(target_arch = "wasm32", test))]
struct Tri {
    pos: [[f32; 3]; 3],
    uv: [[f32; 2]; 3],
    /// T6 (2026-05-28): PER-VERTEX normals (one per triangle vertex), not a
    /// single broadcast face normal. Sourced from the authored `SWVertex.normal`
    /// (rotated by the part frame) so curved geometry smooth-shades like retail;
    /// falls back to the computed face normal per-vertex when the authored
    /// normal is degenerate (zero-length).
    normals: [[f32; 3]; 3],
    surface_did: u32,
    /// T2 (2026-05-28): the polygon's `sides_type` — the per-poly CULL bit.
    /// `1` = CullMode.None (two-sided); anything else (`0` Landblock, `2`
    /// Clockwise, `3`) = single-sided (acclient `D3DPolyRender` @455346:
    /// `sides_type == 1 ? CULLMODE_NONE : CULLMODE_CW`). The JS adapter uses
    /// this to pick FrontSide vs DoubleSide per polygon (behind `?perPolyCull`).
    sides_type: u8,
    /// E8 (2026-06-08): the source polygon id (`gfx.polygons` /
    /// `cell.polygons` key) this tri was fan-triangulated from. ADDITIVE +
    /// OPTIONAL — lets a round-trip validator / ML pipeline trace each tri
    /// back to its source polygon. Multiple tris share a `polygon_id` when a
    /// poly has >3 verts. NOTE: the id is unique only within ONE source
    /// GfxObj / EnvCell; the aggregated single-mesh paths flatten multiple
    /// parts/cells (each with its own namespace) into one `ModelMesh`, so
    /// global per-tri uniqueness holds only on the per-part export path —
    /// see [`ModelMesh::polygon_ids`].
    polygon_id: u16,
    /// E8 (2026-06-08): which SIDE of the source polygon this tri represents
    /// (front/positive vs back/negative). Pairs with `polygon_id` for the
    /// full (polygon, side) provenance of every emitted triangle.
    side_kind: SideKind,
}

/// Walk a [`GfxObj`]'s polygons, fan-triangulate each, transform by
/// `(part_rot, part_offset)`, and append to `tris`. Mirrors the C#
/// `AppendGfxTris` line-for-line. Equivalent to the
/// `_with_tex_swaps` variant called with an empty swap table — kept
/// as a thin wrapper so existing callers (static placements,
/// non-substituted entities) don't change.
#[cfg(any(target_arch = "wasm32", test))]
fn append_gfx_tris(
    tris: &mut Vec<Tri>,
    gfx: &holtburger_dat::file_type::GfxObj,
    part_offset: holtburger_common::Vector3,
    part_rot: holtburger_common::Quaternion,
) {
    append_gfx_tris_with_tex_swaps(tris, gfx, part_offset, part_rot, &[]);
}

/// Phase 4 step 6 Phase A: like [`append_gfx_tris`], but rewrites
/// `surface_did` per-polygon when the polygon's resolved surface_did
/// matches one of the `(old, new)` swap entries. Implements
/// `CloTextureEffect` substitution from ACE's `CalculateObjDesc`
/// (mirrors `Creature_Networking.cs:185`'s
/// `objDesc.AddTextureChange(new PropertiesTextureMap { PartIndex,
/// OldTexture, NewTexture })` at the consumer end). Empty
/// `tex_swaps` is the cheap path used for static placements.
///
/// `surface_did = 0` for any polygon whose `pos_surface` is out of
/// range — caller falls back to a flat colour.
#[cfg(any(target_arch = "wasm32", test))]
fn append_gfx_tris_with_tex_swaps(
    tris: &mut Vec<Tri>,
    gfx: &holtburger_dat::file_type::GfxObj,
    part_offset: holtburger_common::Vector3,
    part_rot: holtburger_common::Quaternion,
    tex_swaps: &[(u32, u32)],
) {
    use holtburger_dat::graphics::Polygon;
    if gfx.vertex_array.vertices.is_empty() || gfx.polygons.is_empty() {
        return;
    }

    // Phase 7 follow-on #7: AC two-sided polygons. The Polygon.sides_type
    // field encodes a CullMode: 0x0=Landblock, 0x1=None, 0x2=Clockwise,
    // 0x3=CounterClockwise. CullMode::Clockwise (0x2) signals "draw the
    // back face too" — `neg_uv_indices` is populated on read iff
    // `sides_type == 0x2 && (stippling & NoNeg=0x8) == 0`. The back face
    // potentially uses a DIFFERENT surface (`neg_surface != pos_surface`):
    // think a stained-glass window with one texture on the interior side
    // and a different one outside, or a stage-curtain banner. When the
    // surfaces differ we must emit BOTH faces as oriented tris with
    // opposite winding so the JS-side MaterialCache can paint each side
    // with its own MeshStandardMaterial. When they match, one tri with
    // `side: DoubleSide` is sufficient (cheaper draw call); this is the
    // common case — most cloth banners use one texture both sides.
    const NO_POS: u8 = 0x04;
    const NO_NEG: u8 = 0x08;
    const CULL_CLOCKWISE: i32 = 0x2;

    // Sort polygon ids for deterministic output (HashMap iteration is
    // not stable; PIXI.Mesh draw order matches whatever order we feed
    // in).
    let mut poly_ids: Vec<u16> = gfx.polygons.keys().copied().collect();
    poly_ids.sort_unstable();
    for pid in poly_ids {
        let poly: &Polygon = &gfx.polygons[&pid];
        if poly.vertex_ids.len() < 3 { continue; }
        // Skip "no positive surface" polygons — same as C# `NoPos` skip.
        if (poly.stippling & NO_POS) != 0 { continue; }

        let raw_pos_surface_did = if poly.pos_surface >= 0
            && (poly.pos_surface as usize) < gfx.surfaces.len()
        {
            gfx.surfaces[poly.pos_surface as usize]
        } else {
            0
        };
        // Phase 4 step 6 Phase A: apply per-part texture swaps. An
        // empty `tex_swaps` (the static-placement path) skips the
        // search entirely. NPC parts typically have ≤4 swaps each so
        // a linear find is fine.
        let pos_surface_did = tex_swaps
            .iter()
            .find(|(old, _)| *old == raw_pos_surface_did)
            .map(|(_, new)| *new)
            .unwrap_or(raw_pos_surface_did);

        // Two-sided detection. The parser populates `neg_uv_indices`
        // only when `sides_type == 0x2 && (stippling & NoNeg) == 0`.
        // We additionally require `neg_surface >= 0 && in-range` to
        // emit a back-face tri; otherwise the back face would have no
        // surface DID and would resolve to the same texture as the
        // front, defeating the point of the second draw.
        let has_back_face =
            poly.sides_type == CULL_CLOCKWISE
                && (poly.stippling & NO_NEG) == 0
                && !poly.neg_uv_indices.is_empty();
        let raw_neg_surface_did = if has_back_face
            && poly.neg_surface >= 0
            && (poly.neg_surface as usize) < gfx.surfaces.len()
        {
            gfx.surfaces[poly.neg_surface as usize]
        } else {
            0
        };
        let neg_surface_did = if raw_neg_surface_did != 0 {
            tex_swaps
                .iter()
                .find(|(old, _)| *old == raw_neg_surface_did)
                .map(|(_, new)| *new)
                .unwrap_or(raw_neg_surface_did)
        } else {
            0
        };
        // Only emit a distinct back-face tri when the surface actually
        // differs from the front. When `neg_surface_did == pos_surface_did`,
        // a single DoubleSide draw is cheaper; the materials.js decoder
        // applies DoubleSide as the default for the front-face tri.
        let emit_back_face = has_back_face
            && neg_surface_did != 0
            && neg_surface_did != pos_surface_did;

        // Resolve ring of (position, pos_uv, neg_uv, normal) per vertex.
        let mut ring_pos: Vec<[f32; 3]> = Vec::with_capacity(poly.vertex_ids.len());
        let mut ring_uv_pos: Vec<[f32; 2]> = Vec::with_capacity(poly.vertex_ids.len());
        let mut ring_uv_neg: Vec<[f32; 2]> = Vec::with_capacity(poly.vertex_ids.len());
        // T6: authored per-vertex normal, rotated by the part frame (direction
        // only — no translation), normalised. `None` when the authored normal
        // is degenerate (zero) → the fan loop falls back to the face normal.
        let mut ring_normal: Vec<Option<[f32; 3]>> = Vec::with_capacity(poly.vertex_ids.len());
        let mut ok = true;
        for (i, &raw) in poly.vertex_ids.iter().enumerate() {
            if raw < 0 { ok = false; break; }
            let Some(vert) = gfx.vertex_array.vertices.get(&(raw as u16)) else { ok = false; break; };
            let mut uv_pos_idx: usize = 0;
            if i < poly.pos_uv_indices.len() {
                uv_pos_idx = poly.pos_uv_indices[i] as usize;
            }
            if uv_pos_idx >= vert.uvs.len() {
                uv_pos_idx = 0;
            }
            let uv_pos = if vert.uvs.is_empty() {
                [0.0, 0.0]
            } else {
                [vert.uvs[uv_pos_idx].u, vert.uvs[uv_pos_idx].v]
            };
            let uv_neg = if emit_back_face && i < poly.neg_uv_indices.len() {
                let mut uv_neg_idx = poly.neg_uv_indices[i] as usize;
                if uv_neg_idx >= vert.uvs.len() {
                    uv_neg_idx = 0;
                }
                if vert.uvs.is_empty() {
                    [0.0, 0.0]
                } else {
                    [vert.uvs[uv_neg_idx].u, vert.uvs[uv_neg_idx].v]
                }
            } else {
                [0.0, 0.0]
            };
            // Apply the per-part transform: `part_rot * vert.origin + part_offset`.
            let p = quat_rotate(part_rot, vert.origin);
            ring_pos.push([p.x + part_offset.x, p.y + part_offset.y, p.z + part_offset.z]);
            ring_uv_pos.push(uv_pos);
            ring_uv_neg.push(uv_neg);
            // T6: rotate the authored normal by the part frame (direction only).
            let rn = quat_rotate(part_rot, vert.normal);
            let rn_len2 = rn.x * rn.x + rn.y * rn.y + rn.z * rn.z;
            if rn_len2 > 1e-12 {
                let inv = 1.0 / rn_len2.sqrt();
                ring_normal.push(Some([rn.x * inv, rn.y * inv, rn.z * inv]));
            } else {
                ring_normal.push(None);
            }
        }
        if !ok || ring_pos.len() < 3 { continue; }

        // Fan-triangulate around vertex 0. Emit front-face tri first
        // (pos_surface_did, ABC winding) and, when applicable, the
        // back-face tri (neg_surface_did, ACB winding, negated normal).
        for i in 2..ring_pos.len() {
            let a = ring_pos[0]; let b = ring_pos[i - 1]; let c = ring_pos[i];
            let n = tri_normal(a, b, c);
            let len2 = n[0] * n[0] + n[1] * n[1] + n[2] * n[2];
            if len2 < 1e-12 { continue; }
            let inv_len = 1.0 / len2.sqrt();
            // Computed face normal — the per-vertex fallback when a vertex has
            // no authored normal.
            let face = [n[0] * inv_len, n[1] * inv_len, n[2] * inv_len];
            // T6: prefer authored per-vertex normals; fall back to `face`.
            let n0 = ring_normal[0].unwrap_or(face);
            let n1 = ring_normal[i - 1].unwrap_or(face);
            let n2 = ring_normal[i].unwrap_or(face);
            tris.push(Tri {
                pos: [a, b, c],
                uv: [ring_uv_pos[0], ring_uv_pos[i - 1], ring_uv_pos[i]],
                normals: [n0, n1, n2],
                surface_did: pos_surface_did,
                sides_type: poly.sides_type as u8,
                // E8: front face → positive side of polygon `pid`.
                polygon_id: pid,
                side_kind: SideKind::Positive,
            });
            if emit_back_face {
                // Reversed winding (A, C, B) + flipped normals so the back
                // face's normals point the opposite way. UV ring follows the
                // same reversal so neg_uv_indices line up with the back
                // vertices; normals reverse to [n0, n2, n1] then negate.
                let neg = |v: [f32; 3]| [-v[0], -v[1], -v[2]];
                tris.push(Tri {
                    pos: [a, c, b],
                    uv: [ring_uv_neg[0], ring_uv_neg[i], ring_uv_neg[i - 1]],
                    normals: [neg(n0), neg(n2), neg(n1)],
                    surface_did: neg_surface_did,
                    // Explicit opposite face of a 2-sided-distinct poly →
                    // single-sided (its own winding is the front for `neg`).
                    sides_type: poly.sides_type as u8,
                    // E8: back face → negative side of the SAME polygon `pid`.
                    polygon_id: pid,
                    side_kind: SideKind::Negative,
                });
            }
        }
    }
}

#[cfg(any(target_arch = "wasm32", test))]
fn quat_rotate(q: holtburger_common::Quaternion, v: holtburger_common::Vector3) -> holtburger_common::Vector3 {
    // Standard quaternion vector rotation: v' = q * v * q^-1, expanded
    // to 16 mults / 12 adds. Same math as System.Numerics.Vector3.Transform.
    let xx = q.x * q.x;
    let yy = q.y * q.y;
    let zz = q.z * q.z;
    let xy = q.x * q.y;
    let xz = q.x * q.z;
    let yz = q.y * q.z;
    let wx = q.w * q.x;
    let wy = q.w * q.y;
    let wz = q.w * q.z;
    holtburger_common::Vector3 {
        x: v.x * (1.0 - 2.0 * (yy + zz)) + v.y * (2.0 * (xy - wz)) + v.z * (2.0 * (xz + wy)),
        y: v.x * (2.0 * (xy + wz)) + v.y * (1.0 - 2.0 * (xx + zz)) + v.z * (2.0 * (yz - wx)),
        z: v.x * (2.0 * (xz - wy)) + v.y * (2.0 * (yz + wx)) + v.z * (1.0 - 2.0 * (xx + yy)),
    }
}

#[cfg(any(target_arch = "wasm32", test))]
fn tri_normal(a: [f32; 3], b: [f32; 3], c: [f32; 3]) -> [f32; 3] {
    let ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let ac = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    [
        ab[1] * ac[2] - ab[2] * ac[1],
        ab[2] * ac[0] - ab[0] * ac[2],
        ab[0] * ac[1] - ab[1] * ac[0],
    ]
}

/// Phase 4 step 6 Phase A: substitution-aware setup walker. ACE's
/// `Creature.CalculateObjDesc()` (in
/// `~/ace-server/Source/ACE.Server/WorldObjects/Creature_Networking.cs:35-243`)
/// walks an NPC's equipped inventory server-side, reads each equipped
/// item's `ClothingTable` from the DAT, and ships the resulting
/// `ObjDesc` (`AnimPartChanges` + `TextureChanges` + `SubPalettes`) on
/// the wire as `ModelData` on `ObjectCreate`. The browser doesn't need
/// to walk inventory or parse `ClothingTable` — it just applies what
/// ACE already computed.
///
/// `model_changes` is `&[(part_index, gfx_obj_did)]`: when a part
/// index appears here, the substituted GfxObj DID is loaded instead of
/// the SetupModel's default `parts[part_index]`. Mirrors
/// `CloObjectEffect` application at `Creature_Networking.cs:182`.
///
/// `texture_changes` is `&[(part_index, old_surface_did, new_surface_did)]`:
/// while triangulating part `part_index`, any polygon whose
/// `surface_did == old_surface_did` is rewritten to `new_surface_did`.
/// Mirrors `CloTextureEffect` application at
/// `Creature_Networking.cs:185`.
///
/// **Pose priority (Phase C, 2026-05-07):** idle MotionTable cycle
/// frame → static placement frame → identity. NPCs/creatures with a
/// `default_motion_table` get their idle stance (knees flexed, arms
/// at hip, weapons at side) instead of the T-pose hidden in many
/// setups' identity placement frames. Mirrors C# `TryResolveIdleAnimFrame`
/// at `WorldBuilder.Terminal/ObjectSpriteGenerator.cs:921-950`.
#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_setup_model_with_substitutions<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
    tris: &mut Vec<Tri>,
) -> Option<()> {
    triangulate_setup_model_at_frame(source, setup_id, model_changes, texture_changes, None, None, tris)
}

/// Phase 4 step 6 Tier 2: triangulate a SetupModel with substitutions
/// AND an optional explicit per-part pose. When `pose_override` is
/// `Some(&AnimationFrame)`, that frame's per-part transforms replace
/// both the idle-anim frame AND the placement-frame fallback.
/// Used by the walk/run-cycle bake path: caller resolves the
/// cycle's frames once via `try_resolve_cycle_frames` (with the
/// command parameter for walk vs. run), then calls this once per
/// frame to emit one pose-specific mesh per cycle frame.
///
/// `pose_override = None` is the original `with_substitutions`
/// behaviour (Phase C idle → placement → identity fallback chain).
#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_setup_model_at_frame<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
    mtable_override: Option<u32>,
    pose_override: Option<&holtburger_dat::file_type::setup_model::AnimationFrame>,
    tris: &mut Vec<Tri>,
) -> Option<()> {
    walk_setup_parts(
        source,
        setup_id,
        model_changes,
        texture_changes,
        mtable_override,
        pose_override,
        None,
        |_pi, gfx, offset, rot, swaps| {
            append_gfx_tris_with_tex_swaps(tris, gfx, offset, rot, swaps);
        },
    )
}

/// Phase 6 step A: per-part variant of [`triangulate_setup_model_at_frame`].
/// Returns one `Vec<Tri>` per `setup.parts[i]` so JS can address each
/// part independently for door-rotation (Phase E) and AABB collision
/// (Phase B). Parts whose GfxObj fails to load yield empty vecs at
/// their index — the slot is preserved so `part_index` stays stable
/// across boundary calls.
#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_setup_model_per_part<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
) -> Option<Vec<Vec<Tri>>> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        .ok()?;
    let setup = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)).ok()?;
    let part_count = setup.parts.len();
    let mut buckets: Vec<Vec<Tri>> = (0..part_count).map(|_| Vec::new()).collect();
    walk_setup_parts(
        source,
        setup_id,
        model_changes,
        texture_changes,
        None,
        None,
        None,
        |pi, gfx, offset, rot, swaps| {
            if let Some(slot) = buckets.get_mut(pi) {
                append_gfx_tris_with_tex_swaps(slot, gfx, offset, rot, swaps);
            }
        },
    )?;
    Some(buckets)
}

/// Cohere-B (2026-05-12): per-part variant that returns part-LOCAL
/// vertices (no rest-pose frame baked in) AND the resolved rest-pose
/// `(origin, orientation)` per part as a side channel. Used by the
/// entity-animation path (`fetch_entity_animation_keyframes`) so JS
/// can set `partGroup.position` + `.quaternion` to the rest pose at
/// spawn and let the AnimationMixer overwrite with model-space cycle
/// keyframes during motion. Mirrors PhatSDK's `CPartArray::UpdateParts`
/// where `Frame::combine(entity_world, anim_frame[i])` produces each
/// part's world transform from raw part-local GfxObj vertices.
///
/// Distinct from [`triangulate_setup_model_per_part`] which BAKES the
/// rest-pose into vertex positions — that's correct for static
/// rendering (buildings, signs, AABB collision) where no AnimationMixer
/// will apply additional per-part transforms. For an animated entity
/// rig, baked-in placement double-composes against the mixer's
/// keyframe values and the rig falls apart in motion (the
/// user-reported symptom).
///
/// Returns `(per_part_tris, rest_poses)` where `rest_poses[pi]` is the
/// `(offset, rot)` that `walk_setup_parts`'s pose-priority chain
/// resolved (idle anim → placement → identity). When no rest pose
/// exists (raw GfxObj, naked setup without MotionTable), the slot
/// holds identity — caller can still apply it harmlessly.
#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_setup_model_per_part_with_rest_pose<
    S: holtburger_dat::ResourceSource + ?Sized,
>(
    source: &S,
    setup_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
    // A9-Stage1: the wire-commanded placement id
    // (PhysicsDesc.animation_frame), consumed by the static placement
    // chain under ?placementId=on. None = no wire placement.
    wire_placement: Option<u32>,
) -> Option<(
    Vec<Vec<Tri>>,
    Vec<(holtburger_common::Vector3, holtburger_common::Quaternion)>,
)> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        .ok()?;
    let setup = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)).ok()?;
    let part_count = setup.parts.len();
    let mut buckets: Vec<Vec<Tri>> = (0..part_count).map(|_| Vec::new()).collect();
    let mut rest_poses: Vec<(holtburger_common::Vector3, holtburger_common::Quaternion)> =
        (0..part_count)
            .map(|_| {
                (
                    holtburger_common::Vector3::zero(),
                    holtburger_common::Quaternion::identity(),
                )
            })
            .collect();
    walk_setup_parts(
        source,
        setup_id,
        model_changes,
        texture_changes,
        None,
        None,
        wire_placement,
        |pi, gfx, offset, rot, swaps| {
            if let Some(slot) = buckets.get_mut(pi) {
                // Capture the pose-priority-resolved rest frame for this
                // part as a side channel. Caller threads it into
                // EntityAnimationData so JS can set partGroup transforms
                // at spawn — matching PhatSDK's per-frame model-space
                // composition semantics.
                if let Some(rest_slot) = rest_poses.get_mut(pi) {
                    *rest_slot = (offset, rot);
                }
                // Append with identity so vertices stay part-local; the
                // rest pose travels separately above.
                append_gfx_tris_with_tex_swaps(
                    slot,
                    gfx,
                    holtburger_common::Vector3::zero(),
                    holtburger_common::Quaternion::identity(),
                    swaps,
                );
            }
        },
    )?;
    Some((buckets, rest_poses))
}

/// Shared inner loop for the SetupModel part walk. Loads the setup,
/// resolves pose priority (`pose_override` → idle → placement →
/// identity), and invokes `on_part(part_index, &gfx, offset, rot, &tex_swaps)`
/// for each `0x01` (GfxObj) part — including substituted parts via
/// `model_changes`. Used by both the fused-output path
/// ([`triangulate_setup_model_at_frame`]) and the per-part path
/// ([`triangulate_setup_model_per_part`]).
#[cfg(any(target_arch = "wasm32", test))]
/// A9-Stage1 (2026-06-12, survey A9 §3 row 1): the static
/// placement-frame resolution chain. `retail_order` ON follows retail —
/// the wire-commanded placement id (`PhysicsDesc.animation_frame` →
/// `CPhysicsObj::SetPlacementFrame`, acclient.c:318540-318562) → `0x65`
/// Resting (the `InitObjectEnd` init default, acclient.c:317303) → `0`
/// (the `CPartArray::SetPlacementFrame` miss fallback searching for
/// `id == 0`, acclient.c:326845-326860) → first available. OFF keeps
/// the legacy `0 → 1 → first` chain byte-identically.
fn resolve_static_placement_frame<'a>(
    setup: &'a holtburger_dat::file_type::SetupModel,
    wire_placement: Option<u32>,
    retail_order: bool,
) -> Option<&'a holtburger_dat::file_type::setup_model::PlacementType> {
    if retail_order {
        wire_placement
            .and_then(|id| i32::try_from(id).ok())
            .and_then(|id| setup.placement_frames.get(&id))
            .or_else(|| setup.placement_frames.get(&0x65))
            .or_else(|| setup.placement_frames.get(&0))
            .or_else(|| setup.placement_frames.values().next())
    } else {
        setup
            .placement_frames
            .get(&0)
            .or_else(|| setup.placement_frames.get(&1))
            .or_else(|| setup.placement_frames.values().next())
    }
}

#[cfg(any(target_arch = "wasm32", test))]
fn walk_setup_parts<S: holtburger_dat::ResourceSource + ?Sized, F>(
    source: &S,
    setup_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
    mtable_override: Option<u32>,
    pose_override: Option<&holtburger_dat::file_type::setup_model::AnimationFrame>,
    wire_placement: Option<u32>,
    mut on_part: F,
) -> Option<()>
where
    F: FnMut(
        usize,
        &holtburger_dat::file_type::GfxObj,
        holtburger_common::Vector3,
        holtburger_common::Quaternion,
        &[(u32, u32)],
    ),
{
    use holtburger_dat::file_type::{GfxObj, SetupModel};
    use holtburger_dat::ResourceKey;

    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        .ok()?;
    let setup = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)).ok()?;

    // Phase C + Tier 2: pose_override (walk-cycle frame) wins over
    // idle frame. Phase C still resolves idle for setups with no
    // pose_override. Static placement (Resting → Default → first)
    // is the per-part fallback for setups without a MotionTable.
    let idle_frame = if pose_override.is_none() {
        try_resolve_idle_anim_frame_with_override(source, &setup, mtable_override)
    } else {
        None
    };
    // A9-Stage1: retail order (wire → 0x65 → 0 → first) under
    // ?placementId=on; legacy 0 → 1 → first otherwise. The idle-anim
    // frame above stays preferred over placement either way (retail's
    // sequence also prefers a live anim).
    let placement = resolve_static_placement_frame(&setup, wire_placement, placement_id_flag());

    for (pi, &default_part_id) in setup.parts.iter().enumerate() {
        // Resolve the actual GfxObj DID for this part: substitution wins
        // over the setup's default. ACE's `CalculateObjDesc` produces
        // exactly one AnimPartChange per substituted slot, so a linear
        // search is fine (NPCs have at most ~25 substitutions).
        let part_id = model_changes
            .iter()
            .find(|(idx, _)| *idx as usize == pi)
            .map(|(_, gfx)| *gfx)
            .unwrap_or(default_part_id);
        if (part_id >> 24) as u8 != 0x01 { continue; }
        let Ok(part_bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", part_id))
            else { continue };
        let Ok(gfx) = GfxObj::unpack(&mut std::io::Cursor::new(&part_bytes))
            else { continue };

        // Pose priority: explicit Tier-2 pose override (walk-cycle
        // frame) → Phase C idle anim frame → static placement frame
        // → identity. Mirrors ObjectSpriteGenerator.cs:842-852 with
        // an extra preceding override for the multi-frame bake path.
        let frame_lookup = pose_override
            .filter(|f| pi < f.frames.len())
            .map(|f| (f.frames[pi].origin, f.frames[pi].orientation))
            .or_else(|| {
                idle_frame.as_ref().filter(|f| pi < f.frames.len())
                    .map(|f| (f.frames[pi].origin, f.frames[pi].orientation))
            })
            .or_else(|| {
                placement.filter(|p| pi < p.anim_frame.frames.len())
                    .map(|p| (p.anim_frame.frames[pi].origin, p.anim_frame.frames[pi].orientation))
            });
        let (offset, rot) = frame_lookup.unwrap_or((
            holtburger_common::Vector3::zero(),
            holtburger_common::Quaternion::identity(),
        ));

        // Per-part texture remap table for append_gfx_tris_with_tex_swaps.
        // Empty for parts without texture changes — the swap is a no-op
        // path inside the appender, so passing empty stays cheap.
        let part_tex_swaps_buf: Vec<(u32, u32)> = texture_changes
            .iter()
            .filter(|(p, _, _)| *p as usize == pi)
            .map(|(_, old, new)| (*old, *new))
            .collect();

        // SetupModel per-part default scale (flag 0x02). ACE applies
        // `GfxObjScale = DefaultScale[i]` to the part geometry (PartArray.cs:349,
        // :538) — a per-part scale distinct from the object-level ObjectDesc
        // scale, combined in the part frame (AFrame.Combine: scale the vertex in
        // part-local space, THEN rotate, THEN translate). The appender does
        // `quat_rotate(part_rot, vert.origin) + part_offset`, so scaling
        // `vert.origin` here (pre-rotation) matches that ordering. Face normals
        // are recomputed post-transform, so scaled positions suffice. Only ~5%
        // of setups carry non-unit scale; skip the clone otherwise.
        let part_scale = setup.default_scale.get(pi).copied();
        let non_unit = part_scale.map_or(false, |s| s.x != 1.0 || s.y != 1.0 || s.z != 1.0);
        if non_unit {
            let s = part_scale.unwrap();
            let mut scaled = gfx.clone();
            for v in scaled.vertex_array.vertices.values_mut() {
                v.origin.x *= s.x;
                v.origin.y *= s.y;
                v.origin.z *= s.z;
                // T6: normals transform by the inverse-transpose; for a
                // diagonal scale that's the component-wise reciprocal
                // (re-normalised later in the appender). Guard zero components.
                if s.x != 0.0 { v.normal.x /= s.x; }
                if s.y != 0.0 { v.normal.y /= s.y; }
                if s.z != 0.0 { v.normal.z /= s.z; }
            }
            on_part(pi, &scaled, offset, rot, &part_tex_swaps_buf);
        } else {
            on_part(pi, &gfx, offset, rot, &part_tex_swaps_buf);
        }
    }
    Some(())
}

/// Phase 6 step B: per-part AABB walker. Sister to `walk_setup_parts`,
/// but accumulates each part's GfxObj vertex positions into a
/// part-local axis-aligned bounding box (post per-part frame
/// transform, pre placement frame). Returns one `Aabb` per
/// `setup.parts[i]` so the caller can bucket each AABB independently
/// into the per-cell collision index. Coarser cyl_sphere bounds
/// would over-block (Holtburg roof overhangs would block ground-
/// level walking past the wall plane); per-vertex bounds match what
/// the renderer actually draws.
///
/// Empty parts (substituted GfxObj missing, raw `0x01` instead of
/// SetupModel, or all polygons skipped) yield an `Aabb::empty()`
/// at their slot — caller filters those before bucketing.
#[cfg(any(target_arch = "wasm32", test))]
fn walk_setup_parts_with_geom<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
) -> Option<Vec<holtburger_common::Aabb>> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        .ok()?;
    let setup = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)).ok()?;
    let part_count = setup.parts.len();
    let mut aabbs: Vec<holtburger_common::Aabb> =
        (0..part_count).map(|_| holtburger_common::Aabb::empty()).collect();
    walk_setup_parts(
        source,
        setup_id,
        &[],
        &[],
        None,
        None,
        None,
        |pi, gfx, offset, rot, _swaps| {
            let Some(slot) = aabbs.get_mut(pi) else { return };
            for vert in gfx.vertex_array.vertices.values() {
                let p = quat_rotate(rot, vert.origin);
                let world = holtburger_common::Vector3 {
                    x: p.x + offset.x,
                    y: p.y + offset.y,
                    z: p.z + offset.z,
                };
                slot.expand_to_include_point(world);
            }
        },
    )?;
    Some(aabbs)
}

/// Workstream C (3D camera collision, 2026-05-11): sister to
/// [`walk_setup_parts_with_geom`] that returns **both** per-part
/// AABBs AND per-part fan-triangulated physics triangles in the
/// setup's local frame (post per-part frame composition, pre
/// placement-frame transform). Used by
/// `populate_building_aabbs_for_landblock_impl` to populate the
/// camera-collision building-physics index alongside the existing
/// AABB index.
///
/// Returned `Vec<(Aabb, Vec<Triangle>)>` has one tuple per
/// `setup.parts[i]`. Empty triangle vecs for parts whose GfxObj has
/// no `physics_polygons` — most retail Holtburg building parts ship
/// physics polys, but a few props (decorative items, sign posts) have
/// only drawing geometry. AABB is built from the GfxObj's vertex
/// array (post part-frame transform); triangles are fan-triangulated
/// from `physics_polygons` against the same vertex array, with the
/// SAME part-frame transform applied so the AABB conservatively
/// bounds the triangles.
///
/// Mirrors the cell-physics path in `populate_env_cells_for_landblock`
/// step G: fan-triangulate `num_pts > 3`, drop polygons with
/// `num_pts < 3`, silently skip vertices that don't resolve (rare
/// dat corruption). Triangles are returned in part-local-post-part-
/// frame coords; caller applies the placement transform.
#[cfg(target_arch = "wasm32")]
fn walk_setup_parts_with_geom_and_physics<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
) -> Option<Vec<(holtburger_common::Aabb, Vec<holtburger_common::Triangle>)>> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        .ok()?;
    let setup = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)).ok()?;
    let part_count = setup.parts.len();
    let mut out: Vec<(holtburger_common::Aabb, Vec<holtburger_common::Triangle>)> =
        (0..part_count)
            .map(|_| (holtburger_common::Aabb::empty(), Vec::new()))
            .collect();
    walk_setup_parts(
        source,
        setup_id,
        &[],
        &[],
        None,
        None,
        None,
        |pi, gfx, offset, rot, _swaps| {
            let Some(slot) = out.get_mut(pi) else { return };
            // AABB from vertex array (post part frame).
            for vert in gfx.vertex_array.vertices.values() {
                let p = quat_rotate(rot, vert.origin);
                let world = holtburger_common::Vector3 {
                    x: p.x + offset.x,
                    y: p.y + offset.y,
                    z: p.z + offset.z,
                };
                slot.0.expand_to_include_point(world);
            }
            // Physics triangles from `physics_polygons` (post part
            // frame). Fan-triangulate `num_pts > 3`; skip polygons
            // with `num_pts < 3` (degenerate). Skip polygons whose
            // vertex_ids don't all resolve — defensive against dat
            // corruption (the polygon list and vertex array are
            // separately read).
            for poly in gfx.physics_polygons.values() {
                if poly.num_pts < 3 {
                    continue;
                }
                let mut part_local_verts: Vec<holtburger_common::Vector3> =
                    Vec::with_capacity(poly.num_pts as usize);
                let mut all_ok = true;
                for &vid in &poly.vertex_ids {
                    if vid < 0 {
                        all_ok = false;
                        break;
                    }
                    let key = vid as u16;
                    let Some(sw) = gfx.vertex_array.vertices.get(&key) else {
                        all_ok = false;
                        break;
                    };
                    // Apply part-frame transform (same as AABB above).
                    let local = holtburger_common::Vector3::new(
                        sw.origin.x,
                        sw.origin.y,
                        sw.origin.z,
                    );
                    let rotated = quat_rotate(rot, local);
                    part_local_verts.push(holtburger_common::Vector3::new(
                        rotated.x + offset.x,
                        rotated.y + offset.y,
                        rotated.z + offset.z,
                    ));
                }
                if !all_ok || part_local_verts.len() < 3 {
                    continue;
                }
                // Fan triangulation: (v0, v1, v2), (v0, v2, v3), …
                // AC physics polygons are convex (BSP-emitted), so fan
                // is correct.
                for i in 1..(part_local_verts.len() - 1) {
                    slot.1.push(holtburger_common::Triangle::new(
                        part_local_verts[0],
                        part_local_verts[i],
                        part_local_verts[i + 1],
                    ));
                }
            }
        },
    )?;
    Some(out)
}

/// Phase 4 step 6 Tier 2: resolve the *walk-forward* animation
/// frames. Same MotionTable walk as `try_resolve_idle_anim_frame`
/// (path 1 only — there's no `default_animation` fallback for walk),
/// but uses `MotionTable::WALK_FORWARD_COMMAND` (`0x4500_0005`)
/// instead of the style-defaults idle substate, and returns the
/// **range** `[low_frame, high_frame)` from the resolved
/// `AnimData` rather than just `part_frames[0]`. The returned
/// `Vec<AnimationFrame>` is the walk cycle's per-frame poses;
/// caller iterates them in order to bake one sprite per cycle frame.
///
/// Returns `None` for setups without a walk cycle (most static props
/// + creatures whose MotionTable doesn't have a WalkForward entry —
/// e.g. an Orange — fall through to whatever the caller's idle
/// fallback is). Caller should treat None as "no walk anim
/// available; render idle pose only" and skip the walk-frame bake.
///
/// Stance choice: NonCombat (`mtable.default_style`) is the only
/// stance baked here. Combat-stance walks render with the same
/// frames — visually approximate, but avoids 3-5× storage. A
/// future tier could bake per-stance walks if anyone asks.
#[cfg(any(target_arch = "wasm32", test))]
fn try_resolve_cycle_frames<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup: &holtburger_dat::file_type::SetupModel,
    mtable_override: Option<u32>,
    stance_override: u32,
    command: u32,
) -> Option<(ConcatenatedMotionBake, u32)> {
    use holtburger_dat::file_type::MotionTable;
    use holtburger_dat::ResourceKey;

    // Humanoid setups (0x02000001 etc.) ship `default_motion_table
    // = None`; their MotionTable lives on the weenie record and ACE
    // ships it on the wire as `ObjectDescriptionData.mtable_id`.
    // EntityUpdate.mtableId carries it through, and the wasm export
    // hands it down here as `mtable_override`. For setups with a
    // baked-in default (props, doors), override is None and we use
    // setup.default_motion_table.
    let mt_id = mtable_override
        .filter(|&id| id != 0)
        .or(setup.default_motion_table)?;
    if (mt_id >> 24) != 0x09 { return None; }
    let bytes = source.get_file_by_key(ResourceKey::new("eor/portal", mt_id)).ok()?;
    let mtable = MotionTable::read(&mut std::io::Cursor::new(&bytes)).ok()?;

    // Stance dispatch. `stance_override == 0` is "use this MotionTable's
    // default_style" (the pre-stance-aware behaviour: NonCombat for
    // most creatures, HandCombat for the rare creature that spawns
    // weapon-drawn). Nonzero stance overrides come from
    // EntityUpdate.motionStance carrying the live UpdateMotion
    // current_style — typically the same default for at-rest creatures
    // and a combat stance once they engage.
    //
    // The cycle_key helper masks `stance & 0xFFFF`, so the u16
    // interpreted form (`MotionStance.interpreted()` — what the wire
    // carries) and the full u32 form (0x8000_xxxx — what `default_style`
    // stores) produce the same key. Both work.
    let resolved_stance = if stance_override == 0 {
        mtable.default_style
    } else {
        stance_override
    };

    // Use MotionTable::motion_data_for_cycle which builds the key
    // via the canonical `cycle_key(stance, command)` helper —
    // (stance & 0xFFFF) << 16 | (command & MOTION_KEY_MASK).
    // MOTION_KEY_MASK = 0x00FF_FFFF (24-bit; motion_table.rs:16, asserted
    // at :542), so the 0x__ classifier high byte of e.g.
    // WALK_FORWARD_COMMAND (0x4500_0000) is stripped before the lookup,
    // leaving the command substate. Phase C's idle path also works because
    // style_defaults stores the pre-masked substate, not the full command.
    let motion_data = mtable.motion_data_for_cycle(resolved_stance, command)?;
    // T4 (2026-05-28): concatenate ALL AnimData segments (was `anims.first()`
    // only) with per-segment timing + reverse playback. See
    // `build_concatenated_motion_frames`.
    let bake = build_concatenated_motion_frames(source, motion_data)?;
    Some((bake, resolved_stance))
}

/// T11 (2026-05-28) — authored ground speed of a locomotion cycle:
/// `|MotionData.velocity|` (m/s) for `(stance, command)`. This is the
/// `baseSpeed` the JS `cycleTimeScale(actualSpeed, baseSpeed)` divides by to
/// scale walk/run cycle playback so foot-speed tracks ground travel (retail
/// `AnimData.Framerate = base * speed`). Returns `0.0` when the cycle has no
/// velocity (`flags` lacks `HAS_VELOCITY`) or doesn't resolve — JS treats 0 as
/// "no scaling". `stance == 0` → the MotionTable's `default_style`. Pure given
/// a parsed table, so it's host-unit-testable.
#[cfg(any(target_arch = "wasm32", test))]
fn motion_cycle_base_speed(
    mtable: &holtburger_dat::file_type::MotionTable,
    stance: u32,
    command: u32,
) -> f32 {
    let resolved_stance = if stance == 0 {
        mtable.default_style
    } else {
        stance
    };
    match mtable.motion_data_for_cycle(resolved_stance, command) {
        Some(md) => md
            .velocity
            .map(|v| (v.x * v.x + v.y * v.y + v.z * v.z).sqrt())
            .unwrap_or(0.0),
        None => 0.0,
    }
}

/// C1 (2026-06-03) — animation-gate hint: which forward locomotion cycle a
/// `MoveToObject`/`MoveToPosition` envelope should play, derived from the
/// `MoveToParameters.movement_parameters` (MovementParams) bitfield.
///
/// Retail `MovementParameters::get_command` (acclient.c:346175) sets the base
/// `*command = WalkForward (0x45000005)` and then a HoldKey promotes it to
/// RunForward when:
///   `can_charge | (can_run & (!can_walk | curr_distance - distance_to_object
///    > walk_run_threshold))`
/// (`apply_run_to_command`/`adjust_motion`). The MovementParams bits are
/// (acclient.h:31425): bit0 `can_walk`, bit1 `can_run`, bit4 `can_charge`.
///
/// The live `curr_distance` lives in the per-tick mover, NOT on the
/// UpdateMotion wire packet, so we cannot evaluate the distance branch here.
/// We collapse to the static decision: **Run** when the creature can run or
/// charge, else **Walk**. (Previously this was an unconditional RunForward,
/// which played the run cycle for walk-only creatures.) The walk-when-close
/// refinement is deferred to a runtime gate that knows `curr_distance`.
#[cfg(any(target_arch = "wasm32", test))]
fn moveto_locomotion_hint(movement_parameters: u32) -> u16 {
    use holtburger_protocol::messages::movement::InterpretedMotionCommand;
    const CAN_RUN: u32 = 0x2;
    const CAN_CHARGE: u32 = 0x10;
    if movement_parameters & (CAN_RUN | CAN_CHARGE) != 0 {
        InterpretedMotionCommand::RUN_FORWARD.raw()
    } else {
        InterpretedMotionCommand::WALK_FORWARD.raw()
    }
}

/// F3-4 (bughunt 2026-06-09) — the MovementParams `sticky` bit (bit 7 =
/// `0x80`, verified against retail `acclient.h` `can_walk..disable_jump`
/// bitfield order, ACE `MovementParameters.Sticky`). ACE sets it on every
/// monster chase (`Creature_Navigation.cs:307`) and then withholds the
/// monster's position broadcasts while it's true (`Monster_Tick`
/// `UpdatePosition(false)`), relying on the client to keep the mob glued to
/// its target. A `MoveToObject` carrying this bit therefore names the sticky
/// target (`MoveToObject.target`); the recv loop surfaces it on the
/// KIND_MOTION `model_id` so the JS tick can track the target.
#[cfg(any(target_arch = "wasm32", test))]
fn moveto_is_sticky(movement_parameters: u32) -> bool {
    const STICKY: u32 = 0x80;
    movement_parameters & STICKY != 0
}

#[cfg(test)]
mod moveto_hint_tests {
    use super::{moveto_is_sticky, moveto_locomotion_hint};
    use holtburger_protocol::messages::movement::InterpretedMotionCommand;

    #[test]
    fn moveto_hint_runs_when_can_run_or_charge_else_walks() {
        let run = InterpretedMotionCommand::RUN_FORWARD.raw();
        let walk = InterpretedMotionCommand::WALK_FORWARD.raw();
        assert_eq!(moveto_locomotion_hint(0x2), run, "can_run -> run");
        assert_eq!(moveto_locomotion_hint(0x10), run, "can_charge -> run");
        assert_eq!(moveto_locomotion_hint(0x1 | 0x2), run, "can_walk+can_run -> run (chase default)");
        assert_eq!(moveto_locomotion_hint(0x1), walk, "walk-only -> walk");
        assert_eq!(moveto_locomotion_hint(0x0), walk, "no flags -> walk");
    }

    /// F3-4 — the sticky bit is 0x80 and is independent of the locomotion
    /// flags (a chase sets can_run|sticky together).
    #[test]
    fn moveto_sticky_bit_is_0x80() {
        assert!(moveto_is_sticky(0x80), "sticky bit set");
        assert!(moveto_is_sticky(0x2 | 0x80), "can_run + sticky (typical chase)");
        assert!(!moveto_is_sticky(0x0), "no flags -> not sticky");
        assert!(!moveto_is_sticky(0x2 | 0x10), "can_run|can_charge alone -> not sticky");
        assert!(!moveto_is_sticky(0x40), "use_final_heading (0x40) is not sticky");
    }
}

#[cfg(test)]
mod dim5_root_motion_tests {
    use super::{advance_root_motion, fold_root_motion_into_parts};
    use holtburger_common::{Quaternion, Vector3};
    use holtburger_dat::graphics::Frame;

    fn yaw_z(deg: f32) -> Quaternion {
        let h = deg.to_radians() * 0.5;
        Quaternion {
            w: h.cos(),
            x: 0.0,
            y: 0.0,
            z: h.sin(),
        }
    }
    fn close(a: f32, b: f32) -> bool {
        (a - b).abs() < 1e-4
    }

    #[test]
    fn identity_orientation_is_plain_translation_sum() {
        // No rotation → cumulative T is the raw running sum and R stays
        // identity: byte-identical to the legacy translation-only path, which
        // is why flipping DIM5_2_ROOT_ORIENT can't change any identity cycle
        // (every reachable PLAYER cycle, per the 2026-06-05 DAT gate).
        let mut t = [0.0f32; 3];
        let mut r = Quaternion::identity();
        advance_root_motion(&mut t, &mut r, Vector3::new(1.0, 0.0, 0.0), Quaternion::identity(), false);
        advance_root_motion(&mut t, &mut r, Vector3::new(0.0, 2.0, 0.0), Quaternion::identity(), false);
        assert!(close(t[0], 1.0) && close(t[1], 2.0) && close(t[2], 0.0), "T = {:?}", t);
        assert!(close(r.w, 1.0) && close(r.z, 0.0));
    }

    #[test]
    fn forward_then_yaw_curves_translation() {
        // "move +X by 1, turn 90° about Z, move +X by 1" → L-shaped net path
        // ending at (1,1,0) facing 180°: the 2nd delta is rotated by the
        // orientation accumulated from the 1st step. This is the curved
        // root-motion behaviour the legacy raw-sum got wrong (it would land at
        // (2,0,0), a straight line).
        let mut t = [0.0f32; 3];
        let mut r = Quaternion::identity();
        advance_root_motion(&mut t, &mut r, Vector3::new(1.0, 0.0, 0.0), yaw_z(90.0), false);
        assert!(close(t[0], 1.0) && close(t[1], 0.0), "after step1 T={:?}", t);
        advance_root_motion(&mut t, &mut r, Vector3::new(1.0, 0.0, 0.0), yaw_z(90.0), false);
        assert!(close(t[0], 1.0) && close(t[1], 1.0) && close(t[2], 0.0), "after step2 T={:?}", t);
        // R = yaw(180): w=cos90=0, |z|=sin90=1.
        assert!(close(r.w, 0.0) && close(r.z.abs(), 1.0), "R=({},{},{},{})", r.w, r.x, r.y, r.z);
    }

    #[test]
    fn reverse_identity_orientation_matches_legacy_negation() {
        // The only reachable reverse case (player reverse cycles carry identity
        // orientation): subtract the raw delta, R stays identity — identical to
        // the legacy `accum -= o` path, so reverse locomotion is unchanged.
        let mut t = [0.0f32; 3];
        let mut r = Quaternion::identity();
        advance_root_motion(&mut t, &mut r, Vector3::new(1.0, 0.5, -0.2), Quaternion::identity(), true);
        assert!(close(t[0], -1.0) && close(t[1], -0.5) && close(t[2], 0.2), "T={:?}", t);
        assert!(close(r.w, 1.0) && close(r.z, 0.0));
    }

    #[test]
    fn fold_identity_orientation_is_pure_translate() {
        // r = identity → world = partLocal + t, exactly the legacy per-part
        // `+ pos` channel. This is why the gated fold can't change identity
        // cycles (every reachable player cycle).
        let mut parts = vec![Frame {
            origin: Vector3::new(2.0, 0.0, -1.0),
            orientation: Quaternion::identity(),
        }];
        fold_root_motion_into_parts(&mut parts, Quaternion::identity(), [1.0, 1.0, 1.0]);
        let f = &parts[0];
        assert!(close(f.origin.x, 3.0) && close(f.origin.y, 1.0) && close(f.origin.z, 0.0), "origin={:?}", f.origin);
        assert!(close(f.orientation.w, 1.0) && close(f.orientation.z, 0.0));
    }

    #[test]
    fn fold_yaw_rotates_part_about_origin_then_translates() {
        // r = +90° about Z, t = 0 → part at +X lands at +Y and its orientation
        // composes the yaw (rigid-body: world = r·partLocal + t).
        let mut parts = vec![Frame {
            origin: Vector3::new(1.0, 0.0, 0.0),
            orientation: Quaternion::identity(),
        }];
        fold_root_motion_into_parts(&mut parts, yaw_z(90.0), [0.0, 0.0, 0.0]);
        let f = &parts[0];
        assert!(close(f.origin.x, 0.0) && close(f.origin.y, 1.0) && close(f.origin.z, 0.0), "origin={:?}", f.origin);
        // orientation == yaw(90): w=cos45, z=sin45.
        assert!(close(f.orientation.w, 0.7071) && close(f.orientation.z, 0.7071),
            "quat=({},{},{},{})", f.orientation.w, f.orientation.x, f.orientation.y, f.orientation.z);
    }
}

/// T11 — wasm export: authored ground speed (`|MotionData.velocity|`) of a
/// locomotion cycle, for the JS anti-ice-skating `cycleTimeScale`. JS already
/// holds the resolved `mtableId` (it keys the AnimationCache by it), so this
/// takes it directly rather than re-resolving via the SetupModel. Returns
/// `0.0` for a non-MotionTable / unloadable id or an unresolved cycle. Cheap
/// after first call — `global_source` caches the MotionTable.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = cycleBaseSpeed)]
pub async fn cycle_base_speed(mtable_id: u32, stance: u32, command: u32) -> f32 {
    use holtburger_dat::file_type::{MotionKinematics, MotionTable};
    use holtburger_dat::{HOLTBURGER_CORE_NAMESPACE, ResourceKey, ResourceSource};
    if mtable_id == 0 || (mtable_id >> 24) != 0x09 {
        return 0.0;
    }
    let source = global_source::global_source();
    // (2026-06-05) Hydrate BOTH records this fn reads before the SYNC
    // `get_file_by_key` calls below. `cycle_base_speed` is `async` precisely so it
    // can honor the `global_source` contract — "prefetch the records it'll read
    // before any sync `get_file_by_key`" (global_source.rs docs). Without this the
    // sync reads depend on the player MotionTable + the `holtburger/core` MOTK
    // already being warm from incidental paths (the rig animation build /
    // `load_world_bootstrap`). The MOTK loads at EnteredWorld (motion_tables=436)
    // but is LRU-evicted by gameplay shard churn before this runs, and the player
    // MT may never have been persisted for this `(mtable,stance,cmd)` query — so
    // the sync reads missed and the resolver returned 0.0, silently no-op'ing
    // velScale (headless-confirmed cycleBaseSpeed==0 even render-on). Re-prefetch
    // is cheap when already cached; it is the documented hydrate-then-read pattern.
    let _ = source
        .prefetch(&[
            ResourceKey::new("eor/portal", mtable_id),
            ResourceKey::new(HOLTBURGER_CORE_NAMESPACE, MotionKinematics::FILE_ID),
        ])
        .await;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", mtable_id)) {
        Ok(b) => b,
        Err(_) => return 0.0,
    };
    let mtable = match MotionTable::read(&mut std::io::Cursor::new(&bytes)) {
        Ok(m) => m,
        Err(_) => return 0.0,
    };
    // T1 base-speed fallback chain (2026-06-03): velocity -> MotionKinematics ->
    // (GetAnimDist, deferred). Each step degrades to the next, so a cycle whose
    // `MotionData.velocity` is empty (the T11 player-RunForward case) still
    // yields an authored ground speed from the separate MotionKinematics asset.
    // step 1 — MotionData.velocity (sync helper; >1e-4 means present).
    let velocity_speed = motion_cycle_base_speed(&mtable, stance, command);
    if velocity_speed > 1e-4 {
        return velocity_speed;
    }
    // step 2 — the standalone MotionKinematics (holtburger/core) per-(stance,
    // command) velocity asset. Any fetch/parse miss degrades to step 3 / 0.0.
    let resolved_stance = mtable.resolve_stance(stance);
    if let Some(s) = motion_kinematics_cycle_base_speed(&*source, mtable_id, resolved_stance, command)
    {
        return s;
    }
    // step 3 — ACE GetAnimDist over the cycle's concatenated PosFrames
    // (`MotionTable::cycle_anim_dist_base_speed` exists in holtburger-dat) is
    // DEFERRED: it needs an async PosFrame fetch and is only reached when BOTH
    // velocity sources are empty (rare). 0.0 -> JS cycleTimeScale no-ops.
    0.0
}

/// T1 step 2 (2026-06-03): `|velocity|` from the standalone MotionKinematics
/// asset for a `(resolved_stance, command)` cycle. Reads + parses the single
/// `holtburger/core` MotionKinematics file from the cached global source; any
/// fetch/parse miss or absent entry returns `None` so the caller falls through.
/// Re-parsed per call — cheap relative to the JS-side `_cycleBaseSpeedCache`.
#[cfg(target_arch = "wasm32")]
fn motion_kinematics_cycle_base_speed<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    motion_table_id: u32,
    stance: u32,
    command: u32,
) -> Option<f32> {
    use holtburger_dat::file_type::MotionKinematics;
    use holtburger_dat::{HOLTBURGER_CORE_NAMESPACE, ResourceKey};
    let bytes = source
        .get_file_by_key(ResourceKey::new(
            HOLTBURGER_CORE_NAMESPACE,
            MotionKinematics::FILE_ID,
        ))
        .ok()?;
    let kinematics = MotionKinematics::read(&mut std::io::Cursor::new(&bytes)).ok()?;
    let entry = kinematics.cycle_kinematics(motion_table_id, stance, command)?;
    let v = entry.velocity?;
    let mag = (v.x * v.x + v.y * v.y + v.z * v.z).sqrt();
    if mag > 1e-4 { Some(mag) } else { None }
}

/// OMEGA (2026-06-06) — `MotionData.omega` (cycle-wide angular velocity, rad/s)
/// for a `(stance, command)` cycle, read directly off the MotionTable. Mirrors
/// [`motion_cycle_base_speed`]. `None` when the cycle has no omega channel (the
/// common case — most cycles only translate). Pairs with the `cycleOmega`
/// export feeding the (deferred) JS cycle-omega apply; for now it also lets a
/// headless probe answer the reachability question (which in-scene cycles spin).
#[cfg(target_arch = "wasm32")]
fn motion_cycle_omega(
    mtable: &holtburger_dat::file_type::MotionTable,
    stance: u32,
    command: u32,
) -> Option<[f32; 3]> {
    let resolved_stance = if stance == 0 {
        mtable.default_style
    } else {
        stance
    };
    let md = mtable.motion_data_for_cycle(resolved_stance, command)?;
    let o = md.omega?;
    let mag = (o.x * o.x + o.y * o.y + o.z * o.z).sqrt();
    if mag > 1e-6 { Some([o.x, o.y, o.z]) } else { None }
}

/// OMEGA (2026-06-06) — `(stance, command)` cycle omega from the standalone
/// MotionKinematics asset (the baked fallback, same source as
/// [`motion_kinematics_cycle_base_speed`]). `None` on any miss / absent omega.
#[cfg(target_arch = "wasm32")]
fn motion_kinematics_cycle_omega<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    motion_table_id: u32,
    stance: u32,
    command: u32,
) -> Option<[f32; 3]> {
    use holtburger_dat::file_type::MotionKinematics;
    use holtburger_dat::{HOLTBURGER_CORE_NAMESPACE, ResourceKey};
    let bytes = source
        .get_file_by_key(ResourceKey::new(
            HOLTBURGER_CORE_NAMESPACE,
            MotionKinematics::FILE_ID,
        ))
        .ok()?;
    let kinematics = MotionKinematics::read(&mut std::io::Cursor::new(&bytes)).ok()?;
    let entry = kinematics.cycle_kinematics(motion_table_id, stance, command)?;
    let o = entry.omega?;
    let mag = (o.x * o.x + o.y * o.y + o.z * o.z).sqrt();
    if mag > 1e-6 { Some([o.x, o.y, o.z]) } else { None }
}

/// OMEGA (2026-06-06) — free wasm export of a cycle's `MotionData.omega`
/// (rad/s, `[x, y, z]`) for `(mtable, stance, command)`. Empty `Vec` = no omega
/// (most cycles). Mirrors the [`cycle_base_speed`] resolve chain
/// (MotionData.omega → MotionKinematics omega). Read-only: surfaces the
/// parsed-but-unapplied cycle omega (the idle-spinner gap — `motion_table.rs`
/// parses it, nothing consumes it). The JS render-apply is intentionally
/// deferred pending (a) a reachability check — call this for in-scene MTs to
/// see which cycles carry non-zero omega — and (b) a GPU eye-test on a real
/// spinner, because the apply touches the hot per-frame `_tickHookOmega` path
/// and must compose with SetOmega-hook omega without clobbering it.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = cycleOmega)]
pub async fn cycle_omega(mtable_id: u32, stance: u32, command: u32) -> Vec<f32> {
    use holtburger_dat::file_type::{MotionKinematics, MotionTable};
    use holtburger_dat::{HOLTBURGER_CORE_NAMESPACE, ResourceKey, ResourceSource as _};
    if mtable_id == 0 || (mtable_id >> 24) != 0x09 {
        return Vec::new();
    }
    let source = global_source::global_source();
    let _ = source
        .prefetch(&[
            ResourceKey::new("eor/portal", mtable_id),
            ResourceKey::new(HOLTBURGER_CORE_NAMESPACE, MotionKinematics::FILE_ID),
        ])
        .await;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", mtable_id)) {
        Ok(b) => b,
        Err(_) => return Vec::new(),
    };
    let mtable = match MotionTable::read(&mut std::io::Cursor::new(&bytes)) {
        Ok(m) => m,
        Err(_) => return Vec::new(),
    };
    // step 1 — MotionData.omega off the MotionTable cycle.
    if let Some(o) = motion_cycle_omega(&mtable, stance, command) {
        return o.to_vec();
    }
    // step 2 — the standalone MotionKinematics omega channel.
    let resolved_stance = mtable.resolve_stance(stance);
    if let Some(o) = motion_kinematics_cycle_omega(&*source, mtable_id, resolved_stance, command) {
        return o.to_vec();
    }
    Vec::new()
}

/// T1 — pure-math mirror of retail `CMotionInterp::get_state_velocity`
/// (`acclient.c:343539-343594` / ACE `MotionInterp.cs:678-700`). Computes the
/// interpreted-state world velocity from the live motion scalars and returns
/// its magnitude (the "actual ground speed" the JS `cycleTimeScale(actual,
/// base)` divides by to keep feet planted — replacing the rendered-XZ-delta
/// EMA that reads garbage on server-pose snaps/teleports/rubber-banding).
///
/// `X = SideStepRight ? 1.25*sidestep_speed : 0` (SidestepAnimSpeed),
/// `Y = WalkForward ? 3.1199999*forward_speed : RunForward ? 4.0*forward_speed
/// : 0` (Walk/Run), `Z = 0`. `mag = sqrt(X²+Y²)`, then clamp to
/// `run_rate * 4.0` (RunAnimSpeed). Retail normalizes the vector and rescales
/// to `max_speed`; for the scalar magnitude that is exactly the clamp.
///
/// run_rate is applied INTERNALLY (via the `run_rate*4.0` clamp) so JS gets the
/// FINAL m/s and must NOT re-scale. Backstep stays `forward_command ==
/// WalkForward` with `forward_speed` negated upstream (× -0.65), so it produces
/// a positive magnitude via the Walk const — there is no RunBackward branch.
/// Commands are FULL u32 motion commands compared against the full constant.
/// Pure (constants hardcoded, no DAT fetch) → host-unit-testable.
#[cfg(any(target_arch = "wasm32", test))]
fn state_ground_speed_inner(
    forward_command: u32,
    forward_speed: f32,
    sidestep_command: u32,
    sidestep_speed: f32,
    run_rate: f32,
) -> f32 {
    let x = if sidestep_command == 0x6500_000f {
        // SIDESTEP_RIGHT_MOTION_COMMAND
        SIDESTEP_ANIM_SPEED * sidestep_speed
    } else {
        0.0
    };
    let y = if forward_command == 0x4500_0005 {
        // WALK_FORWARD_MOTION_COMMAND
        WALK_ANIM_SPEED * forward_speed
    } else if forward_command == 0x4400_0007 {
        // MotionTable::RUN_FORWARD_COMMAND
        RUN_ANIM_SPEED * forward_speed
    } else {
        0.0
    };
    // Z = 0 → magnitude is just the XY hypotenuse.
    let mut mag = (x * x + y * y).sqrt();
    let max_speed = run_rate * RUN_ANIM_SPEED;
    if mag > max_speed {
        mag = max_speed;
    }
    mag
}

/// T1 — wasm export of the [`state_ground_speed_inner`] mirror of retail
/// `get_state_velocity`. SYNCHRONOUS pure-math (no DAT fetch, no mtable_id) —
/// unlike the async `cycleBaseSpeed`. Consumes the live `InterpretedMotionState`
/// scalars (forward_command/forward_speed/sidestep_command/sidestep_speed from
/// the `motion_state_for_input` build path) plus a `run_rate` supplied by JS
/// (from the `playerRunRate` getter). Returns the FINAL ground anim-speed in
/// m/s with run_rate already applied (clamp `run_rate*4.0`); JS feeds this as
/// the `actualSpeed` arg to `cycleTimeScale`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = stateGroundSpeed)]
pub fn state_ground_speed(
    forward_command: u32,
    forward_speed: f32,
    sidestep_command: u32,
    sidestep_speed: f32,
    run_rate: f32,
) -> f32 {
    state_ground_speed_inner(
        forward_command,
        forward_speed,
        sidestep_command,
        sidestep_speed,
        run_rate,
    )
}

/// 2026-05-18 motion-table-x-envcell experiment: resolve a transition
/// (link) clip for `(stance, from_command) → to_command`. Same DAT-
/// walk pattern as `try_resolve_cycle_frames` but uses
/// `MotionTable::motion_data_for_link` instead of cycle lookup.
///
/// Per `external/DatReaderWriter/DatReaderWriter/dats.xml:3746-3748`
/// the Links table is a nested dict whose outer key is
/// `(style << 16 | from_substate)` and whose inner key is the raw
/// `to_substate`. When a creature switches motion commands (e.g.
/// WalkForward → Ready on coming to a stop), retail plays the link
/// clip once before chaining into the destination cycle. Ours has
/// been ignoring this and going straight to crossfade-to-rest.
///
/// Returns `None` when no link is registered for the transition,
/// when the MotionTable can't be loaded, or when the resolved
/// Animation has no frames. Caller falls back to its existing
/// crossfade path (so a missing link is transparent — same visual
/// as today).
#[cfg(any(target_arch = "wasm32", test))]
fn try_resolve_link_frames<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup: &holtburger_dat::file_type::SetupModel,
    mtable_override: Option<u32>,
    stance_override: u32,
    from_command: u32,
    to_command: u32,
) -> Option<(ConcatenatedMotionBake, u32)> {
    use holtburger_dat::file_type::MotionTable;
    use holtburger_dat::ResourceKey;

    let mt_id = mtable_override
        .filter(|&id| id != 0)
        .or(setup.default_motion_table)?;
    if (mt_id >> 24) != 0x09 { return None; }
    let bytes = source.get_file_by_key(ResourceKey::new("eor/portal", mt_id)).ok()?;
    let mtable = MotionTable::read(&mut std::io::Cursor::new(&bytes)).ok()?;

    let resolved_stance = if stance_override == 0 {
        mtable.default_style
    } else {
        stance_override
    };

    // A4-Q4 (2026-06-12, `?getLink=on`): the faithful retail TWO-HOP
    // `CMotionTable::get_link` resolver (exact entry, then the
    // style-level `(style << 16)` fallback group; acclient.c:337585-337639)
    // instead of the shipped single hop — second-hop-authored transitions
    // (motion-dispatch C2) play their flourish instead of hard-cutting.
    // Speeds are pinned `1.0` (forward): this bake site has no playback
    // direction — the JS overlay plays links forward — so the
    // negative-speed reversed lookups + style_defaults bridge are
    // resolver-covered (dat q4_* tests) but unreachable here until a
    // caller carries a signed speed. Flag off = single hop, byte-identical.
    let motion_data = if get_link_flag() {
        mtable.get_link(resolved_stance, from_command, 1.0, to_command, 1.0)?
    } else {
        mtable.motion_data_for_link(resolved_stance, from_command, to_command)?
    };
    // T4 (2026-05-28): concatenate ALL AnimData segments with per-segment
    // timing + reverse playback (was `anims.first()`). Links are commonly
    // multi-segment (windup → strike → recover → settle) and ~22% of retail
    // AnimData are reverse-framerate, which previously produced a null clip.
    let bake = build_concatenated_motion_frames(source, motion_data)?;
    Some((bake, resolved_stance))
}

/// T4 (2026-05-28) — concatenate ALL `AnimData` segments of a `MotionData`
/// into a single keyframe sequence with per-frame absolute times, mirroring
/// ACE's `Sequence` / `AnimSequenceNode` chaining
/// (`ACE.Server/Physics/Animation/Sequence.cs:203-216,438`).
///
/// Each segment plays its frame slice `[low_frame, high_frame]` **inclusive**
/// (`high_frame == -1` → to the last frame of the Animation, per
/// `AnimSequenceNode.get_ending_frame` = `HighFrame + 1 - EPSILON`). When a
/// segment's `framerate` is **negative** it plays in REVERSE
/// (`AnimSequenceNode` runs `HighFrame → LowFrame`; ~22% of retail AnimData),
/// timed at `1/|framerate|`. Segments are appended end-to-end and each frame
/// is stamped with its cumulative time so the JS clip builder can lay down
/// `KeyframeTrack` times that honour per-segment rate changes.
///
/// Pre-2026-05-28 only `motion_data.anims.first()` was used and the JS side
/// rejected `framerate <= 0` to a null clip — truncating ~every multi-segment
/// swing/cast/transition (23% of retail MotionData) and dropping reverse
/// segments entirely.
///
/// Returns `(frames, frame_times_secs, total_duration_secs)` or `None` when no
/// segment yields a usable frame (so callers keep their rest-pose fallback).
///
/// ## DIM5-2 root-motion ORIENTATION gate
/// `DIM5_2_ROOT_ORIENT` (default `false`) switches root motion from the
/// shipped translation-only channel to melt's rigid-body composition
/// (`MotionTable.cs:225-231`): each pos_frame's translation delta is rotated
/// by the **accumulated** orientation before summing, the orientation is
/// accumulated as a quaternion product, and the resulting rigid frame
/// `(R_n, T_n)` is folded directly into every part of `part_frames`
/// (`world = R_n·partLocal + T_n`, `quat = R_n·partQuat`) — so the separate
/// `pos` channel is zeroed (no double-translate). It is a **no-op vs. the
/// shipped path for every identity-orientation cycle** — the 2026-06-05 DAT
/// gate proved both player tables (0x09000001 / 0x09000202) carry zero
/// non-identity orientation, so flipping this never changes the local player
/// rig; the only authored orientation lives on creature cycles (pure yaw, up
/// to 27° on MT 0x090001D5 cmd 0x0011 — the eye-test target). Kept default-off
/// pending a 1070 creature eye-test (no GPU validation is possible code-only);
/// the math + accumulator are host-unit-tested. See `docs/2026-06-05-anim-recon/`.
// 2026-06-05: flipped ON for the 1070 creature eye-test (MT 0x090001D5 cmd
// 0x0011, 27° yaw). No-op for the player rig (identity-orientation cycles);
// only changes creature root-motion orientation. Revert to `false` if the
// eye-test regresses.
#[cfg(any(target_arch = "wasm32", test))]
const DIM5_2_ROOT_ORIENT: bool = true;

/// DIM5-2: advance the running root-motion frame `(T, R)` by one pos_frame,
/// mirroring melt `MotionTable.cs:225-230` / ACE `AFrame.cs:43-49`:
///   `T += R · origin;  R = (R · orientation).normalize()`
/// The translation delta is rotated by the orientation accumulated through the
/// PREVIOUS frame (so a turn part-way through a cycle curves the remaining
/// translation), THEN the orientation composes. Reverse (negative-framerate)
/// playback de-accumulates with the conjugate (= inverse for unit quats) and
/// subtracts the rotated delta. Pure — host-unit-tested (`dim5_*` tests).
#[cfg(any(target_arch = "wasm32", test))]
fn advance_root_motion(
    pos_accum: &mut [f32; 3],
    ori_accum: &mut holtburger_common::Quaternion,
    origin: holtburger_common::Vector3,
    orientation: holtburger_common::Quaternion,
    reverse: bool,
) {
    let rotated = ori_accum.rotate_vector(origin);
    if reverse {
        pos_accum[0] -= rotated.x;
        pos_accum[1] -= rotated.y;
        pos_accum[2] -= rotated.z;
        *ori_accum = ori_accum.multiply(orientation.conjugate()).normalize();
    } else {
        pos_accum[0] += rotated.x;
        pos_accum[1] += rotated.y;
        pos_accum[2] += rotated.z;
        *ori_accum = ori_accum.multiply(orientation).normalize();
    }
}

/// DIM5-2: fold the cumulative rigid root-motion frame `(r, t)` into every
/// part of one keyframe — `world = r·partLocal + t`, `quat = r·partQuat` —
/// matching retail's whole-object Frame applied to per-part model-space
/// transforms. With root motion baked in here, the additive `pos` channel is
/// zeroed so JS doesn't double-translate. For identity `r` this is a pure
/// translate (`r·v == v`), so it equals the legacy per-part `+ pos` path on
/// every identity-orientation cycle. Pure — host-unit-tested (`dim5_*` tests).
#[cfg(any(target_arch = "wasm32", test))]
fn fold_root_motion_into_parts(
    parts: &mut [holtburger_dat::graphics::Frame],
    r: holtburger_common::Quaternion,
    t: [f32; 3],
) {
    for fr in parts.iter_mut() {
        let p = r.rotate_vector(fr.origin);
        fr.origin.x = p.x + t[0];
        fr.origin.y = p.y + t[1];
        fr.origin.z = p.z + t[2];
        fr.orientation = r.multiply(fr.orientation).normalize();
    }
}

/// A5-P3 (2026-06-12) — named result of one whole-MotionData bake. Replaces
/// the prior 4-tuple `(frames, frame_times, pos_frames, duration)` so the
/// root-motion metadata addition doesn't tuple-churn every call site again.
#[cfg(any(target_arch = "wasm32", test))]
pub(crate) struct ConcatenatedMotionBake {
    pub frames: Vec<holtburger_dat::file_type::setup_model::AnimationFrame>,
    pub frame_times: Vec<f32>,
    pub pos_frames: Vec<f32>,
    pub duration: f32,
    /// A5-P3: net rigid root displacement of the whole clip — the final
    /// (pos_accum, ori_accum) pair at end-of-bake. Model-space, relative to
    /// clip start. Retail equivalent: the sum of per-frame
    /// `Frame::combine(pos_frame)` offsets a full playthrough feeds
    /// `CPhysicsObj::UpdatePositionInternal`
    /// (acclient.c:340717-340720 -> 320014-320031). On the
    /// `DIM5_2_ROOT_ORIENT` fold path both accumulators are maintained; on
    /// the legacy path `net_orientation` stays identity (identical to its
    /// visual semantics — the legacy `pos` channel is translation-only).
    pub net_translation: [f32; 3],
    pub net_orientation: holtburger_common::Quaternion,
}

/// Returns the bake (`ConcatenatedMotionBake`) or `None` when no segment
/// yields a usable frame (so callers keep their rest-pose fallback).
#[cfg(any(target_arch = "wasm32", test))]
fn build_concatenated_motion_frames<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    motion_data: &holtburger_dat::file_type::motion_table::MotionData,
) -> Option<ConcatenatedMotionBake> {
    use holtburger_dat::file_type::Animation;
    use holtburger_dat::ResourceKey;

    let mut frames: Vec<holtburger_dat::file_type::setup_model::AnimationFrame> = Vec::new();
    let mut times: Vec<f32> = Vec::new();
    // Render-completeness audit (2026-05-29) — root motion. Parallel to
    // `frames`: 3 f32 (ox,oy,oz) per concatenated keyframe from the
    // Animation's `pos_frames` (AnimationFlags::POS_FRAMES). Most cycles
    // (idle, walk/run locomotion) carry NO pos_frames — verified human idle
    // 0x03000001 has pos_frames_len==0 — so this is all-zero for them and a
    // no-op. Non-empty only for one-shot anims that translate the object
    // (lunge attacks, stepping emotes, door/lever swings, knockbacks). Held
    // in lockstep with `frames` (same slice + same reverse).
    let mut pos: Vec<f32> = Vec::new();
    let mut t = 0.0f32;
    // 2026-06-05 [DIM5/W1.5]: running root-motion accumulator. ACE composes
    // PosFrames CUMULATIVELY — the net displacement at frame N is the running
    // sum of pos_frames[0..=N] (Sequence.cs:383 / AFrame.cs:43-49; retail
    // Frame::combine at acclient.c:340420-340457). Previously we pushed each
    // raw per-frame `origin` delta and `animation.js` added it directly, so a
    // multi-frame translating one-shot (lunge/door/lever/knockback) showed only
    // the last-frame delta and under-translated. Carry one accumulator across
    // ALL concatenated segments (forward `+=`, reverse `-=`) so `pos` holds
    // cumulative net displacement; `animation.js:156-161` (add-to-every-part)
    // is unchanged. No-op for idle/walk/run (pos_frames empty → zeros pushed).
    let mut pos_accum = [0.0f32; 3];
    // 2026-06-05 [DIM5-2]: running root-motion ORIENTATION accumulator. Only
    // touched on the `DIM5_2_ROOT_ORIENT` path; stays identity for every
    // identity-orientation cycle (so the gated fold is a no-op there). Mirrors
    // melt `MotionTable.cs:229` (`orientation *= posFrame.Orientation`).
    let mut ori_accum = holtburger_common::Quaternion::identity();

    for anim_data in &motion_data.anims {
        let anim_did = anim_data.anim_id;
        if (anim_did >> 24) != 0x03 {
            continue;
        }
        let Ok(anim_bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", anim_did)) else {
            continue;
        };
        let Ok(anim) = Animation::read(&mut std::io::Cursor::new(&anim_bytes)) else {
            continue;
        };
        if anim.part_frames.is_empty() {
            continue;
        }

        let total = anim.part_frames.len();
        let low = (anim_data.low_frame.max(0) as usize).min(total);
        let high = if anim_data.high_frame < 0 {
            total
        } else {
            ((anim_data.high_frame as usize).saturating_add(1)).min(total)
        };
        if low >= high {
            continue;
        }

        // Per-segment dt from |framerate|. A zero/non-finite framerate is
        // degenerate (no timing) — skip rather than divide by zero.
        let fr = anim_data.framerate.abs();
        if !(fr > 0.0) {
            continue;
        }
        let dt = 1.0 / fr;

        // pos_frames is parallel to part_frames ONLY when the POS_FRAMES
        // flag was set (len == total); otherwise it's empty → push zeros.
        let has_pos = anim.pos_frames.len() == total;
        // Iterate by index so part_frames + pos_frames stay aligned across
        // the same forward/reverse slice.
        let reverse = anim_data.framerate < 0.0;
        let push_frame = |idx: usize,
                          frames: &mut Vec<holtburger_dat::file_type::setup_model::AnimationFrame>,
                          pos: &mut Vec<f32>,
                          accum: &mut [f32; 3],
                          ori: &mut holtburger_common::Quaternion| {
            frames.push(anim.part_frames[idx].clone());
            if DIM5_2_ROOT_ORIENT {
                // DIM5-2 (melt MotionTable.cs:225-231): rigid-body root motion.
                // Rotate this frame's translation delta by the orientation
                // accumulated through the PREVIOUS frame, add to T, then compose
                // the orientation: `T += R·origin; R = (R·orientation).norm()`.
                // Reverse (negative-framerate) playback de-accumulates with the
                // conjugate. Then fold the rigid frame (R_n, T_n) into every
                // part of the just-pushed keyframe (`world = R·partLocal + T`,
                // `quat = R·partQuat`) and zero the additive `pos` channel so JS
                // doesn't double-translate. For identity-orientation cycles this
                // is byte-identical to the legacy path (R stays identity →
                // R·v == v), so flipping the gate only affects creature yaw
                // cycles. No POS_FRAMES → identity delta → carried (R, T) unchanged.
                if has_pos {
                    advance_root_motion(
                        accum,
                        ori,
                        anim.pos_frames[idx].origin,
                        anim.pos_frames[idx].orientation,
                        reverse,
                    );
                }
                if let Some(f) = frames.last_mut() {
                    fold_root_motion_into_parts(&mut f.frames, *ori, *accum);
                }
                pos.push(0.0);
                pos.push(0.0);
                pos.push(0.0);
            } else {
                // 2026-06-05 [DIM5/W1.5]: accumulate this frame's origin delta into
                // the running root-motion sum, then emit the CUMULATIVE value (per
                // ACE Sequence.cs:383 / AFrame.cs:43-49). Reverse segments play the
                // delta backward, so subtract (mirrors retail Frame::Subtract /
                // negated combine on backward playback). No POS_FRAMES → zero delta,
                // so `accum` is unchanged and we emit the carried sum (zeros for a
                // pure idle/walk/run cycle).
                if has_pos {
                    let o = &anim.pos_frames[idx].origin;
                    if reverse {
                        accum[0] -= o.x;
                        accum[1] -= o.y;
                        accum[2] -= o.z;
                    } else {
                        accum[0] += o.x;
                        accum[1] += o.y;
                        accum[2] += o.z;
                    }
                }
                pos.push(accum[0]);
                pos.push(accum[1]);
                pos.push(accum[2]);
            }
        };
        if reverse {
            // Reverse playback: HighFrame → LowFrame (AnimSequenceNode).
            for idx in (low..high).rev() {
                push_frame(idx, &mut frames, &mut pos, &mut pos_accum, &mut ori_accum);
                // Hook direction flip (2026-06-03). In retail this segment runs
                // Backward, so `Sequence.execute_hooks` fires Both(0)+Backward(-1)
                // and skips Forward(1). We bake it as FORWARD-ordered frames and
                // the JS executor always advances forward + drops direction==-1
                // (entities.js `_fireHook`), which would fire the inverted set.
                // Negate each hook's direction here (Forward<->Backward, Both
                // unchanged; direction is i32 with Forward=1/Both=0/Backward=-1)
                // so the downstream always-forward gate fires the retail-correct
                // hooks for the reverse segment.
                if let Some(f) = frames.last_mut() {
                    for h in &mut f.hooks {
                        // DIM3-4 (2026-06-05): negate only the wire-valid
                        // AnimHookDir values {Forward=1, Backward=-1}; Both(0)
                        // stays 0. The retail enum also defines UNKNOWN=-2 (a
                        // constructor sentinel that `CAnimHook::UnPackHook`
                        // overwrites from the wire before any fire, so it never
                        // reaches a baked hook — confirmed absent across the
                        // full portal.dat survey), but a blanket `-h.direction`
                        // would map a stray -2 to +2, out of the {-1,0,1} the
                        // JS `_fireHook` gate understands. Clamp by matching the
                        // known values and passing anything else through
                        // unchanged.
                        h.direction = match h.direction {
                            1 => -1,
                            -1 => 1,
                            other => other,
                        };
                    }
                }
                times.push(t);
                t += dt;
            }
        } else {
            for idx in low..high {
                push_frame(idx, &mut frames, &mut pos, &mut pos_accum, &mut ori_accum);
                times.push(t);
                t += dt;
            }
        }
    }

    if frames.is_empty() {
        return None;
    }
    // `t` after the final increment == last_frame_time + last_dt == the time
    // the last frame holds until (== clip duration; matches the legacy
    // single-anim `num_frames / framerate`).
    Some(ConcatenatedMotionBake {
        frames,
        frame_times: times,
        pos_frames: pos,
        duration: t,
        // A5-P3: the end-of-bake accumulators ARE the clip's net rigid root
        // displacement — previously discarded here.
        net_translation: pos_accum,
        net_orientation: ori_accum,
    })
}

// ─────────────────────────────────────────────────────────────────────────
// Wave 3.E — JS-vs-C# swing classifier parity (Rust port of the spec).
//
// Implements `lookup_motion_link_for_swing` per
// `external/holtburger/docs/swing-classification-spec-2026-05-19.md` §3.2.
// Mirrors the C# oracle at
// `WorldBuilder.Terminal/CommandEngine.MotionParity.cs::MotionClassifySwing`.
//
// **Load-bearing detail (per project_wave3bc_done_2026-05-19):**
// `MotionTable.links[outer]` inner-dict keys are the FULL 32-bit retail
// MotionCommand (e.g. `SlashHigh = 0x1000005B`), NOT the LOW-16 substate.
// The Rust parser at `crates/holtburger-dat/src/file_type/motion_table.rs:202`
// stores raw u32 keys correctly, but the helper
// `MotionTable::motion_data_for_link` at line 65 masks `to_cmd &
// 0x000F_FFFF` before lookup — a port bug that strips the high-3-nibbles
// classifier prefix (0x10 / 0x40 / 0x44 / 0x45) and never matches in
// retail data. We do the lookup here directly via `mt.links.get(outer)?
// .get(&command)` to bypass that buggy helper — preserving the
// W3.C C# oracle's "raw int" semantics (DRW C# reads dict keys as raw
// little-endian `int`).
//
// `dats.xml:3746-3748` declares `genericKey="int"` for both `Links` outer
// and `MotionCommandData.MotionData` inner — confirming no masking is
// applied by the wire format. The spec doc's "LOW 16 bits" remark
// concerns only the OUTER key construction (`stance << 16 | substate`),
// not the INNER key lookup.
// ─────────────────────────────────────────────────────────────────────────

/// AC retail "Ready" command — the canonical `from_substate` for every
/// swing/cast link in all 436 retail motion tables (validated by
/// `crates/holtburger-dat/tests/motion_table_monsters.rs`).
#[cfg(any(target_arch = "wasm32", test))]
const MOTION_LINK_FROM_READY: u32 = 0x4100_0003;

/// Per spec §2.4 the swing-classifier returns a typed bucket. The JS
/// caller can use this to drive `setSwingPoseFromMotion` differently
/// from `setSpellCastPoseFromMotion` (one-shot vs hold-to-charge).
#[cfg(any(target_arch = "wasm32", test))]
fn classify_command_kind(cmd: u32) -> (&'static str, Option<&'static str>) {
    // High-3-nibbles classifier prefix is the discriminator. Refs:
    //   0x10000058..0x1000005D : Thrust/Slash {Low,Med,High}
    //   0x10000062..0x1000006A : AttackHigh/Med/Low {1,2,3}  (HandCombat)
    //   0x1000011F..0x1000012A : Double/TripleSlash + Double/TripleThrust
    //   0x10000173..0x10000184 : Offhand{Slash,Thrust} + Offhand{D,T}{S,T}
    //   0x10000186..0x1000018E : AttackHigh/Med/Low {4,5,6}
    //   0x1000018F..0x1000019A : Punch{Fast,Slow} + OffhandPunch
    //   0x4000002B..0x40000039 : MagicGesture (Blast..Pray)
    let high4 = cmd & 0xF000_0000;
    if high4 == 0x4000_0000 {
        // Magic gesture; no height bucket — return ("cast", None).
        return ("cast", None);
    }
    if high4 != 0x1000_0000 {
        return ("unknown", None);
    }
    let low12 = cmd & 0x0000_0FFF;
    // Spec §2.4 commands fall into three height ranges by the LOW 12 bits.
    // Mapping table derived from `external/chorizite/Chorizite.Common/
    // Enums/MotionCommand.cs:95-418` — the canonical retail enum values.
    // NOTE: the height-ordering convention varies across the table:
    //   - Thrust trio 0x058-0x05A is Med/Low/High (NOT alphabetical).
    //   - Slash trio 0x05B-0x05D is High/Med/Low.
    //   - AttackHigh1..AttackLow3 0x062-0x06A repeats H/M/L per triple.
    //   - DoubleSlash..TripleThrust 0x11F-0x12A repeats L/M/H per triple.
    //   - OffhandSlash + OffhandThrust 0x173-0x178 repeats H/M/L.
    //   - Offhand{Double,Triple}{Slash,Thrust} 0x179-0x184 repeats L/M/H.
    //   - AttackHigh4..AttackLow6 0x186-0x18E repeats H/M/L.
    //   - Punch{Fast,Slow} + OffhandPunch 0x18F-0x19A repeats H/M/L.
    let height = match low12 {
        // Thrust trio (Med/Low/High order — see MotionCommand.cs:95-97)
        0x058 => Some("Medium"), // ThrustMed
        0x059 => Some("Low"),    // ThrustLow
        0x05A => Some("High"),   // ThrustHigh
        // Slash trio (High/Med/Low order — see MotionCommand.cs:98-100)
        0x05B => Some("High"),   // SlashHigh
        0x05C => Some("Medium"), // SlashMed
        0x05D => Some("Low"),    // SlashLow
        // HandCombat AttackHigh/Med/Low {1,2,3}: H/M/L repeating
        0x062 | 0x065 | 0x068 => Some("High"),
        0x063 | 0x066 | 0x069 => Some("Medium"),
        0x064 | 0x067 | 0x06A => Some("Low"),
        // Double/TripleSlash + Double/TripleThrust: L/M/H repeating
        0x121 | 0x124 | 0x127 | 0x12A => Some("High"),
        0x120 | 0x123 | 0x126 | 0x129 => Some("Medium"),
        0x11F | 0x122 | 0x125 | 0x128 => Some("Low"),
        // OffhandSlash + OffhandThrust 0x173-0x178: H/M/L repeating
        0x173 | 0x176 => Some("High"),
        0x174 | 0x177 => Some("Medium"),
        0x175 | 0x178 => Some("Low"),
        // Offhand{Double,Triple}{Slash,Thrust} 0x179-0x184: L/M/H repeating
        0x17B | 0x17E | 0x181 | 0x184 => Some("High"),
        0x17A | 0x17D | 0x180 | 0x183 => Some("Medium"),
        0x179 | 0x17C | 0x17F | 0x182 => Some("Low"),
        // HandCombat AttackHigh/Med/Low {4,5,6}: H/M/L repeating
        0x186 | 0x189 | 0x18C => Some("High"),
        0x187 | 0x18A | 0x18D => Some("Medium"),
        0x188 | 0x18B | 0x18E => Some("Low"),
        // Punch{Fast,Slow} + OffhandPunch{Fast,Slow}: H/M/L repeating
        0x18F | 0x192 | 0x195 | 0x198 => Some("High"),
        0x190 | 0x193 | 0x196 | 0x199 => Some("Medium"),
        0x191 | 0x194 | 0x197 | 0x19A => Some("Low"),
        _ => None,
    };
    ("swing", height)
}

/// Pure-Rust core of the swing classifier. Builds the outer link key per
/// spec §3.2 (`(stance & 0xFFFF) << 16 | 0x0003`), walks
/// `MotionTable.links[outer]`, looks up the FULL 32-bit `command` key in
/// the inner `MotionData` map, and returns the first anim (always
/// `Anims[0]` per the 5,455-entry retail validation — every link has
/// exactly 1 anim).
///
/// Returns `None` when:
/// - the outer key has no link entry (stance has no swings — missile
///   stances always fall here)
/// - the inner `command` key isn't in the link's MotionData (no swing
///   for that specific command in this stance)
/// - the matched MotionData has zero anims (defensive — never observed
///   in retail data)
#[cfg(any(target_arch = "wasm32", test))]
fn classify_motion_link_for_swing(
    mtable: &holtburger_dat::file_type::MotionTable,
    stance: u32,
    command: u32,
) -> Option<MotionLinkAnimInner> {
    // `stance == 0` → the MotionTable's `default_style`, mirroring the sibling
    // resolvers `motion_cycle_base_speed` / `try_resolve_link_frames`. Without
    // this, an at-rest entity (stance 0) keys outer 0x00000003 which never
    // matches a real link (e.g. NonCombat/Ready = 0x003D0003). Pure widening:
    // non-zero stances are unchanged.
    let resolved_stance = if stance == 0 {
        mtable.default_style
    } else {
        stance
    };
    // Outer key: same encoding as `cycle_key` (stance LOW 16 << 16 |
    // from-substate LOW 16). For swings, from-substate is always Ready
    // (LOW 16 = 0x0003).
    let outer_key = ((resolved_stance & 0xFFFF) << 16) | (MOTION_LINK_FROM_READY & 0xFFFF);
    let inner_map = mtable.links.get(&outer_key)?;
    // Inner key: the FULL 32-bit command, NOT masked. See module comment
    // above. This is the W3.C load-bearing finding.
    let motion_data = inner_map.get(&command)?;
    let anim = motion_data.anims.first()?;

    // Duration: number of played frames / framerate. Spec §2.3:
    //   - melee swings use low=0, high=-1 (play to end of anim asset);
    //     we report a duration of NaN/0 in this case since we don't
    //     parse the Animation DID here (caller can resolve the
    //     anim length via separate fetch_entity_animation_keyframes
    //     if needed). Reported as 0.0 so JS can detect with `> 0`.
    //   - magic casts have explicit high_frame (15-43 frames).
    //
    // Computing here: when high_frame >= 0 and framerate > 0, return
    // `(high - low + 1) / framerate`. For high == -1, return 0.0.
    let duration_sec = if anim.high_frame >= 0 && anim.framerate > 0.0 {
        let frames = (anim.high_frame as f32 - anim.low_frame as f32 + 1.0).max(0.0);
        frames / anim.framerate
    } else {
        0.0
    };

    let (kind, height) = classify_command_kind(command);
    Some(MotionLinkAnimInner {
        kind,
        height: height.unwrap_or(""),
        anim_id: anim.anim_id,
        low_frame: anim.low_frame,
        high_frame: anim.high_frame,
        framerate: anim.framerate,
        duration_sec,
        resolved_command: command,
    })
}

/// Native-shaped result struct (no wasm-bindgen). The wasm wrapper
/// converts this into `MotionLinkAnimJs` before crossing the boundary.
#[cfg(any(target_arch = "wasm32", test))]
#[derive(Debug, Clone)]
struct MotionLinkAnimInner {
    kind: &'static str,
    height: &'static str,
    anim_id: u32,
    low_frame: i32,
    high_frame: i32,
    framerate: f32,
    duration_sec: f32,
    resolved_command: u32,
}

/// JS-facing result of `lookup_motion_link_for_swing` / `parse_motion_link_for_swing_bytes`.
///
/// Mirrors spec §3.2's `MotionLinkAnimJs` plus the higher-level
/// classifier fields (`kind`, `height`) from the JS-side
/// `classifyMotionCommand` widening (entities.js).
///
/// Field semantics (matches C# `SwingClassifyResult`):
/// - `kind`: "swing" | "cast" | "unknown" (per spec §2.4 ID-range classifier).
/// - `height`: "High" | "Medium" | "Low" for swings; empty for casts.
/// - `anim_id`: DAT DID of the Animation record (`0x03xxxxxx`).
/// - `low_frame` / `high_frame`: clip range; `-1` = play to end.
/// - `framerate`: anim playback rate in fps.
/// - `duration_sec`: derived from frames/framerate; `0.0` when
///   `high_frame == -1` (caller must resolve via Animation).
/// - `resolved_command`: full 32-bit retail MotionCommand that matched.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
#[derive(Clone, Debug)]
pub struct MotionLinkAnimJs {
    kind: String,
    height: String,
    anim_id: u32,
    low_frame: i32,
    high_frame: i32,
    framerate: f32,
    duration_sec: f32,
    resolved_command: u32,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl MotionLinkAnimJs {
    #[wasm_bindgen(getter)]
    pub fn kind(&self) -> String {
        self.kind.clone()
    }
    #[wasm_bindgen(getter)]
    pub fn height(&self) -> String {
        self.height.clone()
    }
    #[wasm_bindgen(getter, js_name = animId)]
    pub fn anim_id(&self) -> u32 {
        self.anim_id
    }
    /// Spec §3.2 alias — `anim` returns the same DID as `animId`.
    /// Keeps the JS validator readable when comparing against the spec
    /// shape.
    #[wasm_bindgen(getter)]
    pub fn anim(&self) -> u32 {
        self.anim_id
    }
    #[wasm_bindgen(getter, js_name = lowFrame)]
    pub fn low_frame(&self) -> i32 {
        self.low_frame
    }
    #[wasm_bindgen(getter, js_name = highFrame)]
    pub fn high_frame(&self) -> i32 {
        self.high_frame
    }
    #[wasm_bindgen(getter)]
    pub fn framerate(&self) -> f32 {
        self.framerate
    }
    #[wasm_bindgen(getter, js_name = durationSec)]
    pub fn duration_sec(&self) -> f32 {
        self.duration_sec
    }
    #[wasm_bindgen(getter, js_name = resolvedCommand)]
    pub fn resolved_command(&self) -> u32 {
        self.resolved_command
    }
}

#[cfg(target_arch = "wasm32")]
fn inner_to_motion_link_anim_js(inner: MotionLinkAnimInner) -> MotionLinkAnimJs {
    MotionLinkAnimJs {
        kind: inner.kind.to_string(),
        height: inner.height.to_string(),
        anim_id: inner.anim_id,
        low_frame: inner.low_frame,
        high_frame: inner.high_frame,
        framerate: inner.framerate,
        duration_sec: inner.duration_sec,
        resolved_command: inner.resolved_command,
    }
}

/// Parse a motion-table DAT record's raw bytes and resolve the swing
/// link for `(stance, command)`. Returns `None` when the bytes don't
/// parse, the stance has no swing links, or the command isn't in the
/// link map.
///
/// This is the no-session wasm export used by the Wave 3.E JS validator
/// (`validate_motion_pose.cjs --js-vs-cs`) which loads motion-table
/// bytes via Node fs and drives the lookup directly. The browser caller
/// uses `SessionHandle::lookupMotionLinkForSwing` (which loads via
/// `global_source`) instead.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = parseMotionLinkForSwingBytes)]
pub fn parse_motion_link_for_swing_bytes(
    bytes: &[u8],
    stance: u32,
    command: u32,
) -> Option<MotionLinkAnimJs> {
    use holtburger_dat::file_type::MotionTable;
    let mtable = MotionTable::read(&mut std::io::Cursor::new(bytes)).ok()?;
    classify_motion_link_for_swing(&mtable, stance, command).map(inner_to_motion_link_anim_js)
}

/// Phase 4 step 6 Phase C: resolve the idle pose for a SetupModel by
/// walking `default_motion_table` → `cycles[(default_style << 16) |
/// idleSubstate]` → first `AnimData.anim_id` → `Animation.part_frames[0]`.
/// Falls back to `setup.default_animation` (path 2) if the MotionTable
/// path doesn't yield. Returns `None` for setups without an animation
/// reference (most static props), which keeps their static placement
/// frame as the rendered pose.
///
/// Mirrors C# `TryResolveIdleAnimFrame` at
/// `WorldBuilder.Terminal/ObjectSpriteGenerator.cs:921-950` — same
/// MotionTable cycle-key formula, same path-1-then-path-2 fallback,
/// same "is the resolved DID actually an Animation (0x03 prefix)?"
/// guard. Per-frame failures (missing DAT record, malformed parse)
/// silently degrade to placement-frame instead of panicking; ACE's
/// own renderer does the same via `SafeTryGet`.
#[cfg(any(target_arch = "wasm32", test))]
fn try_resolve_idle_anim_frame<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup: &holtburger_dat::file_type::SetupModel,
) -> Option<holtburger_dat::file_type::setup_model::AnimationFrame> {
    try_resolve_idle_anim_frame_with_override(source, setup, None)
}

#[cfg(any(target_arch = "wasm32", test))]
fn try_resolve_idle_anim_frame_with_override<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup: &holtburger_dat::file_type::SetupModel,
    mtable_override: Option<u32>,
) -> Option<holtburger_dat::file_type::setup_model::AnimationFrame> {
    use holtburger_dat::file_type::{Animation, MotionTable};
    use holtburger_dat::ResourceKey;
    let mut anim_did: u32 = 0;

    // Path 1: motion table (override → setup.default) → cycles → AnimData[0].
    // Same override semantics as walk-cycle: humanoid setups need
    // the wire-shipped mtable_id from EntityUpdate; props use
    // setup.default_motion_table.
    let resolved_mt = mtable_override
        .filter(|&id| id != 0)
        .or(setup.default_motion_table);
    if let Some(mt_id) = resolved_mt {
        if (mt_id >> 24) == 0x09 {
            if let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", mt_id)) {
                if let Ok(mtable) = MotionTable::read(&mut std::io::Cursor::new(&bytes)) {
                    if let Some(&idle_substate) = mtable.style_defaults.get(&mtable.default_style) {
                        // Cycle key per AC physics: high 16 bits style,
                        // low 24 bits substate. Mirrors C#:
                        //   ((uint)mtable.DefaultStyle << 16) |
                        //   ((uint)idleSubstate & 0xFFFFFF)
                        let cycle_key =
                            (mtable.default_style << 16) | (idle_substate & 0x00FF_FFFF);
                        if let Some(motion_data) = mtable.cycles.get(&cycle_key) {
                            if let Some(first_anim) = motion_data.anims.first() {
                                anim_did = first_anim.anim_id;
                            }
                        }
                    }
                }
            }
        }
    }

    // Path 2: setup.default_animation (no MotionTable, but the setup
    // points directly at an Animation).
    if anim_did == 0 {
        if let Some(da) = setup.default_animation {
            anim_did = da;
        }
    }

    // Sanity guard: must be a 0x03-prefixed Animation DID.
    if anim_did == 0 || (anim_did >> 24) != 0x03 {
        return None;
    }
    let bytes = source
        .get_file_by_key(ResourceKey::new("eor/portal", anim_did))
        .ok()?;
    let anim = Animation::read(&mut std::io::Cursor::new(&bytes)).ok()?;
    anim.part_frames.into_iter().next()
}

/// Top-level model triangulation: dispatch on `model_id >> 24`.
/// `0x01` → single GfxObj at identity transform; `0x02` → SetupModel
/// walk through parts. Returns `None` if the model record can't be
/// loaded; an empty Vec means "loaded but had no drawable polygons"
/// (legitimate — some retail models are physics-only).
#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_model<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    model_id: u32,
) -> Option<Vec<Tri>> {
    triangulate_model_with_substitutions(source, model_id, &[], &[])
}

/// Phase 4 step 6 Phase A: substitution-aware top-level dispatch.
/// `0x01` (raw GfxObj) ignores the substitution tables since there's
/// only one part. `0x02` (SetupModel) routes through the substitution-
/// aware walker.
#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_model_with_substitutions<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    model_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
) -> Option<Vec<Tri>> {
    triangulate_model_with_substitutions_and_mtable(source, model_id, model_changes, texture_changes, None)
}

#[cfg(any(target_arch = "wasm32", test))]
fn triangulate_model_with_substitutions_and_mtable<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    model_id: u32,
    model_changes: &[(u8, u32)],
    texture_changes: &[(u8, u32, u32)],
    mtable_override: Option<u32>,
) -> Option<Vec<Tri>> {
    use holtburger_dat::file_type::GfxObj;
    use holtburger_dat::ResourceKey;
    let mut tris = Vec::new();
    match (model_id >> 24) as u8 {
        0x01 => {
            let bytes = source
                .get_file_by_key(ResourceKey::new("eor/portal", model_id))
                .ok()?;
            let gfx = GfxObj::unpack(&mut std::io::Cursor::new(&bytes)).ok()?;
            append_gfx_tris(
                &mut tris,
                &gfx,
                holtburger_common::Vector3::zero(),
                holtburger_common::Quaternion::identity(),
            );
        }
        0x02 => {
            triangulate_setup_model_at_frame(
                source,
                model_id,
                model_changes,
                texture_changes,
                mtable_override,
                None,
                &mut tris,
            )?;
        }
        _ => return None,
    }
    Some(tris)
}

/// Follow-on #5 (LOD) — resolve a model_id's `did_degrade` chain entry.
///
/// AC's `GfxObj` struct carries an `Option<u32>` `did_degrade` field
/// pointing at a lower-detail GfxObj of the same visual; the engine
/// historically swapped to it at view distances >~100 m. Most Holtburg
/// models don't have one (it's mainly for distant scenery like trees).
///
///   - `0x01XXXXXX` raw GfxObj: returns the GfxObj's own `did_degrade`
///     (or 0 if `HAS_DID_DEGRADE` is unset).
///   - `0x02XXXXXX` SetupModel: SINGLE-part setups return that part
///     GfxObj's `did_degrade`. MULTI-part setups return 0 (no
///     substitution): an LOD swap collapses the whole setup to one
///     degrade GfxObj resolved from `parts[0]`, which drops the
///     `AnimationFrame.frames[i]` <-> `parts[i]` invariant for a
///     multi-part rig, so we skip LOD for them (the `parts.len() != 1`
///     guard below; 4453d5a5). Holtburg statics are almost all
///     single-part SetupModels so this still covers the realistic case.
///   - Any other prefix: returns 0 (not a model — environments, etc.).
///
/// Returns 0 on any I/O / parse failure — JS treats 0 as "no LOD chain
/// available, use a plain Mesh".
#[cfg(any(target_arch = "wasm32", test))]
fn resolve_did_degrade<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    model_id: u32,
) -> u32 {
    use holtburger_dat::file_type::{GfxObj, SetupModel};
    use holtburger_dat::ResourceKey;
    match (model_id >> 24) as u8 {
        0x01 => {
            let Ok(bytes) =
                source.get_file_by_key(ResourceKey::new("eor/portal", model_id))
            else {
                return 0;
            };
            let Ok(gfx) = GfxObj::unpack(&mut std::io::Cursor::new(&bytes)) else {
                return 0;
            };
            gfx.did_degrade.unwrap_or(0)
        }
        0x02 => {
            let Ok(bytes) =
                source.get_file_by_key(ResourceKey::new("eor/portal", model_id))
            else {
                return 0;
            };
            let Ok(setup) = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)) else {
                return 0;
            };
            // followup (2026-06-03): entity LOD substitution collapses the WHOLE
            // setup to ONE degrade GfxObj resolved from parts[0] only. That is
            // correct for a single-part setup, but for a MULTI-PART rig it drops
            // every other part and breaks the animation (the AnimationFrame.frames
            // [i] <-> parts[i] invariant). Retail degrades PER-PART. Until per-part
            // degrade exists, only substitute for single-part setups; multi-part
            // rigs render at full detail (return 0 = no substitute).
            if setup.parts.len() != 1 {
                return 0;
            }
            let Some(&first_part) = setup.parts.first() else {
                return 0;
            };
            // Recurse — for the typical Holtburg setup, first_part is a
            // 0x01 GfxObj. The recursion bottom-outs at the 0x01 branch
            // above; we cap the recursion at one level by only matching
            // the first_part's prefix once.
            if (first_part >> 24) as u8 == 0x01 {
                let Ok(pbytes) =
                    source.get_file_by_key(ResourceKey::new("eor/portal", first_part))
                else {
                    return 0;
                };
                let Ok(pgfx) = GfxObj::unpack(&mut std::io::Cursor::new(&pbytes)) else {
                    return 0;
                };
                pgfx.did_degrade.unwrap_or(0)
            } else {
                0
            }
        }
        _ => 0,
    }
}

/// Pack a `Vec<Tri>` into the wasm-bindgen-friendly [`ModelMesh`]
/// shape: dedupe surface_dids into the `surfaces` array, replace each
/// triangle's `surface_did` with a u8 index, flatten per-triangle
/// vertex data into typed-array buffers, compute the world bbox.
#[cfg(target_arch = "wasm32")]
fn pack_model_mesh(tris: Vec<Tri>) -> ModelMesh {
    // Surface dedupe + index map (insertion-order preserved for
    // determinism). u8 cap = 255 unique surfaces per model — fine
    // for AC (most models use ≤8).
    let mut surfaces: Vec<u32> = Vec::new();
    let mut sidx_lookup: std::collections::HashMap<u32, u8> = std::collections::HashMap::new();
    let mut positions = Vec::with_capacity(tris.len() * 9);
    let mut uvs = Vec::with_capacity(tris.len() * 6);
    let mut normals = Vec::with_capacity(tris.len() * 9);
    let mut surface_indices = Vec::with_capacity(tris.len());
    let mut sides_types: Vec<u8> = Vec::with_capacity(tris.len());
    // E8: per-tri (polygon_id, side_kind) provenance — one entry per
    // emitted triangle, same order as positions/surface_indices.
    let mut polygon_ids: Vec<u16> = Vec::with_capacity(tris.len());
    let mut side_kinds: Vec<u8> = Vec::with_capacity(tris.len());

    let mut bbox_min = [f32::INFINITY; 3];
    let mut bbox_max = [f32::NEG_INFINITY; 3];

    for tri in &tris {
        let sidx: u8 = if tri.surface_did == 0 {
            0xFF // sentinel "no surface"
        } else if let Some(&idx) = sidx_lookup.get(&tri.surface_did) {
            idx
        } else if surfaces.len() >= 255 {
            0xFF // too many surfaces; cap at 255
        } else {
            let idx = surfaces.len() as u8;
            surfaces.push(tri.surface_did);
            sidx_lookup.insert(tri.surface_did, idx);
            idx
        };
        surface_indices.push(sidx);
        sides_types.push(tri.sides_type);
        // E8: trace this tri to its source polygon + side.
        polygon_ids.push(tri.polygon_id);
        side_kinds.push(tri.side_kind as u8);

        for v in 0..3 {
            let p = tri.pos[v];
            positions.extend_from_slice(&p);
            uvs.extend_from_slice(&tri.uv[v]);
            // T6: per-vertex normals (9 floats/tri), no longer a single
            // broadcast face normal (was 3 floats/tri).
            normals.extend_from_slice(&tri.normals[v]);
            for k in 0..3 {
                if p[k] < bbox_min[k] { bbox_min[k] = p[k]; }
                if p[k] > bbox_max[k] { bbox_max[k] = p[k]; }
            }
        }
    }

    if !bbox_min[0].is_finite() {
        bbox_min = [0.0, 0.0, 0.0];
        bbox_max = [0.0, 0.0, 0.0];
    }

    ModelMesh {
        positions,
        uvs,
        normals,
        surface_indices,
        sides_types,
        surfaces,
        bbox_min,
        bbox_max,
        // Follow-on #5: pack_model_mesh has no access to the source
        // model_id (and so can't resolve a degrade chain). The caller
        // (`fetch_model_mesh` / `fetch_model_meshes`) post-fills this
        // via a separate GfxObj walk after the pack returns.
        did_degrade: 0,
        // E8: per-tri (polygon, side) provenance.
        polygon_ids,
        side_kinds,
    }
}

/// One surface's decoded pixels — output of [`fetch_surface_pixels`]
/// / [`fetch_surfaces_pixels`]. Used by Phase 3 step 6's in-browser
/// rasterizer to UV-map per-poly textures into the model's tile.
///
/// `surface_type` is the raw `SurfaceType` bitfield read from the
/// Surface record (see `holtburger_dat::file_type::surface::Surface`
/// and `ACE.Entity.Enum.SurfaceType`). The 3D path's `MaterialCache`
/// (`scene3d/materials.js`) decodes it into MeshStandardMaterial flags:
///   - `Translucent (0x10)` → `transparent = true, depthWrite = false`
///   - `Base1ClipMap (0x4)` → `alphaTest = 0.5`
///   - `Luminous (0x40)` → emissive map + colour
///   - `Additive (0x10000)` → `blending = AdditiveBlending`
///   - `Diffuse (0x20)` → matte (no specular reflection)
/// AC has no explicit "TwoSided" bit; two-sidedness is encoded
/// per-Polygon via `sides_type == CullMode::Clockwise (0x2)` and is
/// handled in the triangulator — see Phase 7 follow-on #7 (two-sided
/// polys with distinct pos/neg surfaces emit two tris with opposite
/// winding in `append_gfx_tris_with_tex_swaps`).
///
/// Defaults to 0 for empty/failed surfaces — the JS decoder reads 0 as
/// "no flag bits set → opaque path", which is the desired fallback.
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
#[cfg(any(target_arch = "wasm32", test))]
pub struct SurfacePixels {
    width: u32,
    height: u32,
    pixels: Vec<u8>, // RGBA8, length = width * height * 4
    /// Raw `Surface.surface_type` bitfield from the DAT. 0 for empty
    /// fallbacks so the JS material decoder treats it as opaque.
    /// (See `ACE.Entity.Enum.SurfaceType` for the canonical bit list.)
    surface_type: u32,
    /// Phase 1.4 — heuristic surface category encoded as
    /// `SurfaceCategory::as_u8()` (12 = Generic). The JS material
    /// decoder maps this to category-aware roughness / metalness
    /// defaults. See `holtburger_dat::surface_classify` for the
    /// rule set and `apps/holtburger-web/scene3d/materials.js`
    /// `_materialFromFlags` for the JS consumer.
    ///
    /// Phase 1.5 — if `data/surface_overrides.json` has a
    /// `category:` entry for this DID, the override value is
    /// substituted before the heuristic is consulted.
    category: u8,
    /// Phase 1.1 — procedural normal map (RGB8, length = w*h*3) from
    /// diffuse luminance via a 3x3 Sobel kernel. Empty Vec for Luminous
    /// surfaces (per Phase 1.1 hand-off #3) and empty/fallback surfaces.
    normal_pixels: Vec<u8>,
    /// Phase 3.1 — procedural heightmap (R8, length = w*h) for parallax
    /// occlusion mapping. Sobel-X gradient integrated by horizontal
    /// scan, then globally normalised to [0, 255]. Empty Vec for
    /// Luminous surfaces (POM doesn't apply to emissive), constant-
    /// luminance surfaces (no gradient → no depth), and the empty
    /// fallback. JS skips POM patch installation when empty.
    height_pixels: Vec<u8>,
    /// Phase 1.5 — roughness override sourced from
    /// `surface_overrides.json` (`f32::NAN` = "no override" — Vec<u8>
    /// can't carry an `Option<f32>` over wasm-bindgen).
    roughness_override: f32,
    /// Phase 1.5 — normal-scale override (same NaN sentinel).
    normal_scale_override: f32,
    /// Wave 8 (2026-05-28) — Surface (0x08) trailing float triplet.
    /// melt's `Source/ACE.DatLoader/FileTypes/Surface.cs:21-40` reads
    /// `(Translucency, Luminosity, Diffuse)` as 3 f32s after the
    /// texture/color branch; our parser at
    /// `crates/holtburger-dat/src/file_type/surface.rs:68-70` matches.
    /// Pre-Wave-8 these were dropped between the parser and JS so
    /// materials.js used the bitflag presence (`Translucent` bit at
    /// 0x10, `Luminous` at 0x40, `Diffuse` at 0x20) with hardcoded
    /// effect strengths (opacity always full, emissive 0.6, roughness
    /// 1.0). Carrying the floats lets the shader uniforms reflect
    /// each surface's actual intensity.
    ///
    /// ACE convention (verified against `particle.js:84-96`):
    ///   `translucency 0.0 = fully opaque, 1.0 = fully invisible`
    ///   → JS sets `opacity = max(0, 1 - translucency)`.
    /// `luminosity` is the emissive multiplier in [0, 1+] (some retail
    /// surfaces push >1 for HDR-ish glow). `diffuse` is the diffuse
    /// contribution scalar; PBR mapping leaves it informational unless
    /// the Diffuse bit (0x20) is also set, at which point it refines
    /// the matte intensity.
    translucency: f32,
    luminosity: f32,
    diffuse: f32,
    /// A10-M3a (2026-06-12) — whether the source Texture is palette-indexed
    /// (P8/Index16, i.e. [`holtburger_dat::file_type::SurfacePixelFormat::
    /// needs_palette`]). Retail analogue: `ImgTex::m_pPalette` non-null
    /// (acclient.h:31982), the discriminator for the ClipMap alpha-test ref
    /// 100-vs-200 (acclient.c:454506-454509). `false` for solid 1x1 surfaces
    /// (retail: no texture → `curr_texture_is_set` false → ddsRef 200,
    /// acclient.c:454506-454507) and for the empty fallback. Consumed by the
    /// JS `?surfaceParityV2=on` ClipMap branch (`applySurfaceRenderState`,
    /// scene3d/materials.js); JS falls back to legacy alphaTest 0.5 when the
    /// getter is missing (stale pkg) — non-load-bearing, rides manifest v4.
    has_palette: bool,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SurfacePixels {
    #[wasm_bindgen(getter)]
    pub fn width(&self) -> u32 { self.width }
    #[wasm_bindgen(getter)]
    pub fn height(&self) -> u32 { self.height }
    /// `Uint8Array(width * height * 4)` of straight-RGBA pixels.
    #[wasm_bindgen(getter)]
    pub fn pixels(&self) -> Vec<u8> { self.pixels.clone() }
    /// Raw `Surface.surface_type` bitfield (see `ACE.Entity.Enum.SurfaceType`).
    /// 0 for the empty fallback surface — the JS material decoder
    /// treats 0 as "no flags set → fully opaque".
    #[wasm_bindgen(getter, js_name = surfaceType)]
    pub fn surface_type(&self) -> u32 { self.surface_type }
    /// Phase 1.4 — heuristic surface category as a stable u8
    /// (see `SurfaceCategory::as_u8`: Stone=0, Wood=1, Metal=2,
    /// Sand=3, Lava=4, Water=5, Foliage=6, Cloth=7, Dirt=8,
    /// Snow=9, Brick=10, Tile=11, Generic=12). 12 (Generic) for
    /// the empty-fallback surface.
    ///
    /// Phase 1.5 — this getter already reflects the override-layer
    /// substitution: if `data/surface_overrides.json` has a `category`
    /// for this DID, the override value is returned here.
    #[wasm_bindgen(getter)]
    pub fn category(&self) -> u8 { self.category }
    /// Phase 1.1 — procedural normal map as RGB8 (length = w*h*3).
    /// Empty for Luminous surfaces and the empty-fallback surface;
    /// JS skips `normalMap` assignment when empty. Packed [r,g,b]
    /// with `(0.5, 0.5, 1.0)` = "flat up" in tangent space.
    #[wasm_bindgen(getter, js_name = normalPixels)]
    pub fn normal_pixels(&self) -> Vec<u8> { self.normal_pixels.clone() }
    /// Phase 3.1 — procedural heightmap as R8 (length = w*h). Empty for
    /// Luminous surfaces, constant-luminance surfaces, and the empty-
    /// fallback surface; JS skips POM shader patch installation when
    /// empty. See `holtburger_dat::normal_gen::height_from_luminance`.
    #[wasm_bindgen(getter, js_name = heightPixels)]
    pub fn height_pixels(&self) -> Vec<u8> { self.height_pixels.clone() }
    /// Phase 1.5 — roughness override (`NaN` = use category default).
    #[wasm_bindgen(getter, js_name = roughnessOverride)]
    pub fn roughness_override(&self) -> f32 { self.roughness_override }
    /// Phase 1.5 — normal-scale override (`NaN` = use category default).
    /// Phase 1.1 reads this post-resolve to author custom bump strength.
    #[wasm_bindgen(getter, js_name = normalScaleOverride)]
    pub fn normal_scale_override(&self) -> f32 { self.normal_scale_override }
    /// Wave 8 — Surface (0x08) translucency float. ACE convention:
    /// `0.0 = opaque`, `1.0 = fully invisible`. JS reads this as
    /// `opacity = max(0, 1 - translucency)`. Independent of the
    /// `Translucent (0x10)` surface_type bit — the bit gates the
    /// alpha-blend pipeline, the float gates the value.
    #[wasm_bindgen(getter)]
    pub fn translucency(&self) -> f32 { self.translucency }
    /// Wave 8 — Surface (0x08) luminosity float. Drives the
    /// MeshStandardMaterial `emissiveIntensity` for surfaces with the
    /// `Luminous (0x40)` bit set. Range is nominally [0, 1] but retail
    /// occasionally pushes >1 for HDR-ish glow.
    #[wasm_bindgen(getter)]
    pub fn luminosity(&self) -> f32 { self.luminosity }
    /// Wave 8 — Surface (0x08) diffuse contribution scalar. Refines
    /// the matte intensity when the `Diffuse (0x20)` bit is set;
    /// informational otherwise.
    #[wasm_bindgen(getter)]
    pub fn diffuse(&self) -> f32 { self.diffuse }
    /// A10-M3a — source-Texture palette-indexedness (P8/Index16). Drives the
    /// `?surfaceParityV2=on` ClipMap alpha-test ref (100/255 paletted vs
    /// 200/255 DDS/solid/none) in scene3d/materials.js. Additive,
    /// non-load-bearing getter — rides manifest v4 (graceful 0.5 fallback).
    #[wasm_bindgen(getter, js_name = hasPalette)]
    pub fn has_palette(&self) -> bool { self.has_palette }
}

/// Phase 1.5 — cache the parsed `data/surface_overrides.json` for the
/// life of the wasm bundle / native test process. First call parses;
/// subsequent calls return the cached map. Resilient: parse failures
/// are swallowed inside the loader (empty map fall-through).
#[cfg(any(target_arch = "wasm32", test))]
fn surface_overrides_map() -> &'static std::collections::HashMap<u32, surface_overrides::OverrideEntry> {
    static MAP: std::sync::OnceLock<std::collections::HashMap<u32, surface_overrides::OverrideEntry>> = std::sync::OnceLock::new();
    MAP.get_or_init(surface_overrides::load_overrides)
}

/// Phase 1.5 — compute the post-override `(category_u8, roughness, normal_scale)`
/// triple for one surface. Consults the override map first (per §Phase 1.5
/// Objective #3); if no `category` is set in the override, falls through
/// to the Phase 1.4 heuristic in `classify`. The two material-parameter
/// overrides are returned independently of the category override (so the
/// glass-pane case at 0x080006E2 can stay `Generic` but pin roughness=0.25).
///
/// Roughness / normal-scale "no override" is encoded as `f32::NAN` for the
/// wasm-bindgen ABI — JS-side `_materialFromFlags` runs the result through
/// `Number.isFinite` to decide whether to apply it.
#[cfg(any(target_arch = "wasm32", test))]
fn classify_with_overrides(
    stats: &holtburger_dat::surface_classify::SurfaceStats,
    surface_type: u32,
    surface_did: u32,
) -> (u8, f32, f32) {
    use holtburger_dat::surface_classify::classify;
    let overrides = surface_overrides_map();
    let entry = surface_overrides::lookup(overrides, surface_did);
    let category = match entry.and_then(|e| e.category) {
        Some(c) => c.as_u8(),
        None => classify(stats, surface_type).as_u8(),
    };
    let roughness = entry.and_then(|e| e.roughness).unwrap_or(f32::NAN);
    let normal_scale = entry.and_then(|e| e.normal_scale).unwrap_or(f32::NAN);
    (category, roughness, normal_scale)
}

/// Walk Surface → SurfaceTexture → Texture → RGBA8 for one surface
/// DID. Returns an empty 0x0 SurfacePixels (width=height=0,
/// pixels.len()=0) when any step of the chain fails — JS treats that
/// as "no texture, fall back to flat colour".
#[cfg(any(target_arch = "wasm32", test))]
fn fetch_surface_pixels_impl<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    surface_did: u32,
) -> SurfacePixels {
    use holtburger_dat::file_type::{Palette, Surface, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::normal_gen::{height_from_luminance, normal_from_luminance};
    use holtburger_dat::surface_classify::{compute_stats, surface_type_flags::LUMINOUS, SurfaceCategory};
    use holtburger_dat::ResourceKey;
    // Generic (12) is the natural empty / "no opinion" fallback for
    // the JS material decoder.
    let generic_cat = SurfaceCategory::Generic.as_u8();
    let empty = SurfacePixels {
        width: 0,
        height: 0,
        pixels: Vec::new(),
        surface_type: 0,
        category: generic_cat,
        normal_pixels: Vec::new(),
        height_pixels: Vec::new(),
        roughness_override: f32::NAN,
        normal_scale_override: f32::NAN,
        translucency: 0.0,
        luminosity: 0.0,
        diffuse: 0.0,
        // A10-M3a — empty fallback: no texture → ddsRef-200 class (false).
        has_palette: false,
    };

    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", surface_did)) else { return empty; };
    let Ok(surface) = Surface::unpack(&bytes) else { return empty; };
    // Capture the raw bitfield BEFORE the solid/textured branch so both
    // 1×1 ARGB synthesized surfaces AND real textures surface the same
    // flags to JS (e.g. a solid translucent overlay still wants
    // `transparent = true` even though the body holds a colour, not a
    // texture ref).
    let surface_type = surface.surface_type;
    if let Some(argb) = surface.solid_color() {
        // Solid surfaces have no pixel data — synthesize a 1×1 ARGB
        // texture so the shader can sample-and-modulate uniformly.
        let a = ((argb >> 24) & 0xFF) as u8;
        let r = ((argb >> 16) & 0xFF) as u8;
        let g = ((argb >> 8) & 0xFF) as u8;
        let b = (argb & 0xFF) as u8;
        let pixels = vec![r, g, b, a];
        // Phase 1.4 — classify the 1x1 too (rare but legal: solid
        // surfaces with the Luminous flag set should still hit Lava).
        // Phase 1.5 — consult overrides first, then fall through to
        // the heuristic.
        let stats = compute_stats(&pixels, 1, 1);
        let (category, roughness_override, normal_scale_override) =
            classify_with_overrides(&stats, surface_type, surface_did);
        // Phase 1.1 — 1x1 has no gradient → empty normal_pixels → JS
        // skips normalMap assignment, leaving flat shading.
        // Phase 3.1 — same applies to height_pixels; 1x1 has no
        // gradient so POM is skipped.
        return SurfacePixels {
            width: 1,
            height: 1,
            pixels,
            surface_type,
            category,
            normal_pixels: Vec::new(),
            height_pixels: Vec::new(),
            roughness_override,
            normal_scale_override,
            translucency: surface.translucency,
            luminosity: surface.luminosity,
            diffuse: surface.diffuse,
            // A10-M3a — solid 1x1: retail reaches the ref pick with
            // curr_texture_is_set = (GetTextureMap != 0) (acclient.c:454411)
            // and !curr_texture_is_set short-circuits to the 200 ref
            // (acclient.c:454506-454507) → false.
            has_palette: false,
        };
    }
    let Some((surf_tex_id, _)) = surface.textured() else { return empty; };
    let Ok(stb) = source.get_file_by_key(ResourceKey::new("eor/portal", surf_tex_id)) else { return empty; };
    let Ok(surf_tex) = SurfaceTexture::unpack(&stb) else { return empty; };
    let Some(rs_id) = surf_tex.highest_res() else { return empty; };
    let Ok(tb) = source.get_file_by_key(ResourceKey::new("eor/portal", rs_id)) else { return empty; };
    let Ok(tex) = Texture::unpack(&tb) else { return empty; };
    // CustomRawJpeg (PFID 500) records carry width=height=0 in the Texture
    // header — the real size lives in the JPEG SOF marker. `actual_dimensions()`
    // resolves it (no-op for every other format, returning width/height as-is) —
    // same call the icon path already uses (fetch_icon_pixels_impl). Using
    // tex.width/tex.height directly here uploaded every JPEG-textured object at
    // 0x0 → empty DataTexture → white default material (the "white door / chest
    // / furniture" class). 2026-05-30.
    let (tex_w, tex_h) = tex.actual_dimensions();
    let rgba = tex
        .to_rgba8(|pal_id| {
            let pb = source
                .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
                .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
            Palette::unpack(&pb).map_err(|e| {
                TextureDecodeError::PaletteFetch(format!("Palette::unpack {pal_id:#010X}: {e}"))
            })
        });
    match rgba {
        Ok(pixels) => {
            // Phase 1.4 — compute heuristic category at decode time
            // (per §11 open question #1 — decode-time, not bake-time).
            // Phase 1.5 — consult `data/surface_overrides.json` first;
            // fall through to the heuristic when no override applies.
            let stats = compute_stats(&pixels, tex_w, tex_h);
            let (category, roughness_override, normal_scale_override) =
                classify_with_overrides(&stats, surface_type, surface_did);
            // Phase 1.1 — Sobel normal map from luminance. Skip Luminous
            // (emissive) per hand-off #3 — bump shading on glowing
            // surfaces looks wrong.
            // Phase 3.1 — same skip rule for the heightmap (POM doesn't
            // make sense on emissive surfaces).
            let (normal_pixels, height_pixels) = if (surface_type & LUMINOUS) != 0 {
                (Vec::new(), Vec::new())
            } else {
                (
                    normal_from_luminance(&pixels, tex_w, tex_h, 1.0),
                    height_from_luminance(&pixels, tex_w, tex_h, 1.0),
                )
            };
            SurfacePixels {
                width: tex_w,
                height: tex_h,
                pixels,
                surface_type,
                category,
                normal_pixels,
                height_pixels,
                roughness_override,
                normal_scale_override,
                translucency: surface.translucency,
                luminosity: surface.luminosity,
                diffuse: surface.diffuse,
                // A10-M3a — textured: palette-indexed iff P8/Index16
                // (retail ImgTex::m_pPalette non-null → 256-ref 100,
                // acclient.c:454506-454509).
                has_palette: tex.format().needs_palette(),
            }
        }
        Err(_) => empty,
    }
}

// === Render-completeness audit (2026-05-29) — animated SurfaceTextures ===
//
// A SurfaceTexture (0x05) holds a LIST of RenderSurface (0x06) ids. The
// hot decode path (`fetch_surface_pixels_impl`) takes only `highest_res()`
// (the last entry), so animated surfaces render frozen on one frame. In
// ToD ~2284 SurfaceTextures hold 2 DISTINCT, same-dimension consecutive
// frames (the classic AC water/lava/effect cycle); ~740 are `[id, id]`
// duplicate no-ops, and any with differing dimensions are a mip stack (use
// highest_res, NOT animation). This is an ADDITIVE second path — it does
// NOT touch the hot single-frame decode, so non-animated surfaces (all
// terrain/static/UI materials) are completely unaffected (zero blast
// radius). JS cycles the decoded frames on the shared material's `.map`
// (correct: all instances of an animated surface animate in sync).

/// Decoded frames of one animated surface. `pixels` is `frame_count`
/// concatenated RGBA8 buffers, each `width*height*4` bytes. `frame_count
/// == 0` ⇒ the surface is NOT animated (single frame, duplicate frames, or
/// a mip stack) — JS leaves it static.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct SurfaceAnimFrames {
    width: u32,
    height: u32,
    frame_count: u32,
    pixels: Vec<u8>,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SurfaceAnimFrames {
    #[wasm_bindgen(getter)]
    pub fn width(&self) -> u32 { self.width }
    #[wasm_bindgen(getter)]
    pub fn height(&self) -> u32 { self.height }
    #[wasm_bindgen(getter, js_name = frameCount)]
    pub fn frame_count(&self) -> u32 { self.frame_count }
    /// One-shot drain of the concatenated RGBA8 frame buffer.
    #[wasm_bindgen(js_name = takePixels)]
    pub fn take_pixels(&mut self) -> Vec<u8> { std::mem::take(&mut self.pixels) }
}

/// Pure helper (native+test reachable): decode every frame of an animated
/// surface. Returns `(width, height, Vec<rgba_per_frame>)`; an empty frame
/// vec means "not animated" — single/duplicate frames, decode failure, or a
/// dimension mismatch (mip stack, not animation). Fail-soft throughout.
#[cfg(any(target_arch = "wasm32", test))]
fn collect_surface_anim_frames<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    surface_did: u32,
) -> (u32, u32, Vec<Vec<u8>>) {
    use holtburger_dat::file_type::{Palette, Surface, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::ResourceKey;
    let none = (0u32, 0u32, Vec::new());
    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", surface_did)) else {
        return none;
    };
    let Ok(surface) = Surface::unpack(&bytes) else { return none; };
    let Some((surf_tex_id, _)) = surface.textured() else { return none; };
    let Ok(stb) = source.get_file_by_key(ResourceKey::new("eor/portal", surf_tex_id)) else {
        return none;
    };
    let Ok(surf_tex) = SurfaceTexture::unpack(&stb) else { return none; };
    let ids = &surf_tex.textures;
    // Animated ⇒ ≥2 frames, not all identical. (`[id,id]` is a no-op cycle.)
    if ids.len() < 2 || ids.iter().all(|&x| x == ids[0]) {
        return none;
    }
    let mut frames: Vec<Vec<u8>> = Vec::with_capacity(ids.len());
    let mut dims: Option<(u32, u32)> = None;
    for &rs_id in ids.iter() {
        let Ok(tb) = source.get_file_by_key(ResourceKey::new("eor/portal", rs_id)) else {
            return none;
        };
        let Ok(tex) = Texture::unpack(&tb) else { return none; };
        let (w, h) = tex.actual_dimensions();
        match dims {
            None => dims = Some((w, h)),
            // Differing dimensions ⇒ a mip stack, not an animation. Bail to
            // static (the hot path's highest_res handles those correctly).
            Some((dw, dh)) => {
                if dw != w || dh != h {
                    return none;
                }
            }
        }
        let rgba = tex.to_rgba8(|pal_id| {
            let pb = source
                .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
                .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
            Palette::unpack(&pb)
                .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))
        });
        match rgba {
            Ok(px) => frames.push(px),
            Err(_) => return none,
        }
    }
    let (w, h) = dims.unwrap_or((0, 0));
    (w, h, frames)
}

/// Wasm export: decode all animation frames of a surface (or report
/// `frameCount == 0` when it isn't animated). JS calls this once per unique
/// surface DID; on `frameCount >= 2` it slices `takePixels()` into N
/// DataTextures and cycles them on the shared material's `.map`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchSurfaceAnimFrames)]
pub async fn fetch_surface_anim_frames(surface_did: u32) -> Result<SurfaceAnimFrames, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", surface_did)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let (width, height, frames) = collect_surface_anim_frames(source.as_ref(), surface_did);
    let frame_count = frames.len() as u32;
    let mut pixels = Vec::with_capacity(frames.iter().map(|f| f.len()).sum());
    for f in &frames {
        pixels.extend_from_slice(f);
    }
    Ok(SurfaceAnimFrames {
        width,
        height,
        frame_count,
        pixels,
    })
}

/// Phase 3 step 6: fetch decoded RGBA8 pixels for one surface DID.
/// Empty result means the walk failed at some step — JS falls back
/// to a flat fill for that triangle group.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_surface_pixels(surface_did: u32) -> Result<SurfacePixels, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", surface_did)];
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        let _ = fetch_surface_pixels_impl(s, surface_did);
    })
    .await?;
    Ok(fetch_surface_pixels_impl(source.as_ref(), surface_did))
}

/// One icon's decoded pixels — output of [`fetch_icon_pixels`].
/// Distinct from [`SurfacePixels`] because icons skip the entire
/// Surface→SurfaceTexture chain: the inventory wire (ACE
/// `WorldObject_Networking.cs:79`) ships RenderSurface DIDs
/// (`0x06xxxxxx`) directly, so the JS icon cache just needs raw RGBA
/// at intrinsic dimensions. `width`/`height` come from
/// [`Texture::actual_dimensions`] (JPEG SOF for `CustomRawJpeg`,
/// header pair otherwise — Trevis #worldbuilder:253).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct IconPixels {
    width: u32,
    height: u32,
    pixels: Vec<u8>,
}

// Icon decode is a wasm-only path (decodes a DAT icon to RGBA for JS). The
// `test` cfg arm here was vestigial: it referenced the wasm-only `IconPixels`
// return type (above) with no host test behind it, so `cargo test` on the host
// target failed to compile. Gate it to wasm32 only (2026-06-03).
#[cfg(target_arch = "wasm32")]
fn fetch_icon_pixels_impl<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    icon_did: u32,
) -> IconPixels {
    use holtburger_dat::file_type::{Palette, Texture, TextureDecodeError};
    use holtburger_dat::ResourceKey;
    let empty = IconPixels { width: 0, height: 0, pixels: Vec::new() };
    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", icon_did)) else {
        return empty;
    };
    let Ok(tex) = Texture::unpack(&bytes) else { return empty; };
    let (w, h) = tex.actual_dimensions();
    let rgba = tex.to_rgba8(|pal_id| {
        let pb = source
            .get_file_by_key(ResourceKey::new("eor/portal", pal_id))
            .map_err(|e| TextureDecodeError::PaletteFetch(format!("{pal_id:#010X}: {e}")))?;
        Palette::unpack(&pb).map_err(|e| {
            TextureDecodeError::PaletteFetch(format!("Palette::unpack {pal_id:#010X}: {e}"))
        })
    });
    match rgba {
        Ok(pixels) => IconPixels { width: w, height: h, pixels },
        Err(_) => empty,
    }
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl IconPixels {
    #[wasm_bindgen(getter)]
    pub fn width(&self) -> u32 { self.width }
    #[wasm_bindgen(getter)]
    pub fn height(&self) -> u32 { self.height }
    #[wasm_bindgen(getter)]
    pub fn pixels(&self) -> Vec<u8> { self.pixels.clone() }
}

/// Decode one RenderSurface (`0x06xxxxxx`) DID directly to RGBA8.
///
/// Use this for icon DIDs sourced from `weenie.IconId` /
/// `data/icon-manifest.json` — NOT [`fetch_surface_pixels`], which
/// walks the Surface (`0x08`) → SurfaceTexture (`0x05`) → RenderSurface
/// (`0x06`) chain used by 3D model materials. Feeding a `0x06` DID
/// into `fetch_surface_pixels` mis-parses it as a Surface record and
/// returns garbage / empty (the original symptom that left every
/// inventory icon blank).
///
/// Returns an empty [`IconPixels`] (`width=0, height=0`) when the
/// fetch or decode fails — JS treats that as "no icon, fall back to
/// type-colour swatch".
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_icon_pixels(icon_did: u32) -> Result<IconPixels, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", icon_did)];
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        let _ = fetch_icon_pixels_impl(s, icon_did);
    })
    .await?;
    Ok(fetch_icon_pixels_impl(source.as_ref(), icon_did))
}

/// Batch form: fetch decoded pixels for many surfaces in one HTTP
/// fetch. Returns `Vec<SurfacePixels>` in input order; per-id
/// failures yield empty entries (no batch fail).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_surfaces_pixels(
    surface_dids: Vec<u32>,
) -> Result<Vec<SurfacePixels>, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial: Vec<ResourceKey<'_>> = surface_dids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    let dids_for_walk = surface_dids.clone();
    // F.37 walk-result dedup. Two entities with the same setup
    // requesting the same DID-set in the same tick (via
    // `materialCache.preload`) now share a single prefetch loop.
    // The cache key fully captures the DID list — distinct
    // overlapping sets (e.g. [A,B,C] vs [B,C,D]) still each get
    // their own loop, but identical sets latch.
    let cache_key = prefetch::WalkCacheKey::new("fetch_surfaces_pixels")
        .with_u32_slice(&surface_dids);
    prefetch::ensure_walk_prefetched_keyed(cache_key, &source, &initial, move |s| {
        for &id in &dids_for_walk {
            let _ = fetch_surface_pixels_impl(s, id);
        }
    })
    .await?;
    let mut out = Vec::with_capacity(surface_dids.len());
    for &id in &surface_dids {
        out.push(fetch_surface_pixels_impl(source.as_ref(), id));
    }
    Ok(out)
}

/// One AC bitmap font with its glyph-atlas pixel data, ready for
/// in-browser text rendering. Output of [`fetch_font`].
///
/// AC Fonts (DAT type 0x40) reference two Texture (0x06) atlases:
/// `pixels_fg` is the foreground glyph mask; `pixels_bg` is the
/// background drop-shadow / fill mask. Both ship as A8 on the wire
/// and are pre-expanded to RGBA8 (V,V,V,255) here so JS can drop the
/// buffer straight into `ImageData` / `CanvasTexture` without a
/// reshape pass. JS renders each glyph by sampling the foreground
/// atlas at `(offset_x, offset_y) .. (offset_x+width, offset_y+height)`
/// and using any of R/G/B (they're equal) as the alpha mask.
///
/// `char_descs_packed` is the on-wire 11-byte-per-glyph layout
/// (u16 unicode + u16 offset_x + u16 offset_y + u8 width + u8 height +
/// i8 h_off_before + i8 h_off_after + i8 v_off_before). JS parses it
/// with `DataView` rather than paying for a per-glyph wasm boundary
/// crossing.
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
#[cfg(any(target_arch = "wasm32", test))]
pub struct FontData {
    id: u32,
    num_glyphs: u32,
    max_char_height: u32,
    max_char_width: u32,
    baseline_offset: i32,
    atlas_width: u32,
    atlas_height: u32,
    pixels_fg: Vec<u8>,
    pixels_bg: Vec<u8>,
    char_descs_packed: Vec<u8>,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl FontData {
    #[wasm_bindgen(getter)]
    pub fn id(&self) -> u32 {
        self.id
    }
    #[wasm_bindgen(getter, js_name = numGlyphs)]
    pub fn num_glyphs(&self) -> u32 {
        self.num_glyphs
    }
    #[wasm_bindgen(getter, js_name = maxCharHeight)]
    pub fn max_char_height(&self) -> u32 {
        self.max_char_height
    }
    #[wasm_bindgen(getter, js_name = maxCharWidth)]
    pub fn max_char_width(&self) -> u32 {
        self.max_char_width
    }
    #[wasm_bindgen(getter, js_name = baselineOffset)]
    pub fn baseline_offset(&self) -> i32 {
        self.baseline_offset
    }
    #[wasm_bindgen(getter, js_name = atlasWidth)]
    pub fn atlas_width(&self) -> u32 {
        self.atlas_width
    }
    #[wasm_bindgen(getter, js_name = atlasHeight)]
    pub fn atlas_height(&self) -> u32 {
        self.atlas_height
    }
    #[wasm_bindgen(getter, js_name = pixelsFg)]
    pub fn pixels_fg(&self) -> Vec<u8> {
        self.pixels_fg.clone()
    }
    #[wasm_bindgen(getter, js_name = pixelsBg)]
    pub fn pixels_bg(&self) -> Vec<u8> {
        self.pixels_bg.clone()
    }
    #[wasm_bindgen(getter, js_name = charDescsPacked)]
    pub fn char_descs_packed(&self) -> Vec<u8> {
        self.char_descs_packed.clone()
    }
}

/// Walk Font → 2× Texture → RGBA8 for one font ID. Returns an empty
/// FontData (num_glyphs=0, empty pixel vectors) when any step fails.
#[cfg(any(target_arch = "wasm32", test))]
fn fetch_font_impl<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    font_id: u32,
) -> FontData {
    use holtburger_dat::ResourceKey;
    use holtburger_dat::file_type::{Font, Texture, TextureDecodeError};
    let empty = FontData {
        id: 0,
        num_glyphs: 0,
        max_char_height: 0,
        max_char_width: 0,
        baseline_offset: 0,
        atlas_width: 0,
        atlas_height: 0,
        pixels_fg: Vec::new(),
        pixels_bg: Vec::new(),
        char_descs_packed: Vec::new(),
    };
    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", font_id)) else {
        return empty;
    };
    let Ok(font) = Font::unpack(&bytes) else {
        return empty;
    };

    let decode_atlas = |atlas_id: u32| -> (u32, u32, Vec<u8>) {
        let Ok(tb) = source.get_file_by_key(ResourceKey::new("eor/portal", atlas_id)) else {
            return (0, 0, Vec::new());
        };
        let Ok(tex) = Texture::unpack(&tb) else {
            return (0, 0, Vec::new());
        };
        // Font atlases are A8 (no palette lookup); the closure is a
        // defensive no-op in case a non-A8 atlas ever shows up.
        let rgba = tex.to_rgba8(|_| Err(TextureDecodeError::MissingPaletteId));
        match rgba {
            Ok(pixels) => (tex.width as u32, tex.height as u32, pixels),
            Err(_) => (0, 0, Vec::new()),
        }
    };

    let (atlas_w_fg, atlas_h_fg, pixels_fg) = decode_atlas(font.foreground_surface_data_id);
    let (atlas_w_bg, atlas_h_bg, pixels_bg) = decode_atlas(font.background_surface_data_id);

    // Both atlases share dims per acclient.h's `struct Font` invariants;
    // if a record disagrees, fall back to fg dims and drop bg.
    let (atlas_width, atlas_height, pixels_bg) =
        if atlas_w_fg == atlas_w_bg && atlas_h_fg == atlas_h_bg {
            (atlas_w_fg, atlas_h_fg, pixels_bg)
        } else {
            (atlas_w_fg, atlas_h_fg, Vec::new())
        };

    let mut packed = Vec::with_capacity(font.char_descs.len() * 11);
    for d in &font.char_descs {
        packed.extend_from_slice(&d.unicode.to_le_bytes());
        packed.extend_from_slice(&d.offset_x.to_le_bytes());
        packed.extend_from_slice(&d.offset_y.to_le_bytes());
        packed.push(d.width);
        packed.push(d.height);
        packed.push(d.horizontal_offset_before as u8);
        packed.push(d.horizontal_offset_after as u8);
        packed.push(d.vertical_offset_before as u8);
    }

    FontData {
        id: font.id,
        num_glyphs: font.char_descs.len() as u32,
        max_char_height: font.max_char_height,
        max_char_width: font.max_char_width,
        baseline_offset: font.baseline_offset,
        atlas_width,
        atlas_height,
        pixels_fg,
        pixels_bg,
        char_descs_packed: packed,
    }
}

/// Fetch + parse + decode an AC bitmap font (DAT type 0x40) along
/// with its two atlas Textures, all in one async call. Empty result
/// (`numGlyphs == 0`) means the walk failed; JS falls back to system
/// font for that text run.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_font(font_id: u32) -> Result<FontData, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", font_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        let _ = fetch_font_impl(s, font_id);
    })
    .await?;
    Ok(fetch_font_impl(source.as_ref(), font_id))
}

/// Fetch a single StringTable record (DAT type 0x23) and return its
/// (hashKey, text) entries as a JSON string. The JS side parses with
/// `JSON.parse` and builds a `Map<number, string>` for O(1) lookup by
/// the hash key the retail UI uses (e.g. 0x014152D5 → "Left Alt").
/// String tables in the English local DAT live in the `eor/local`
/// namespace; the few in portal.dat live in `eor/portal`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_string_table(table_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::StringTable;
    let source = global_source::global_source();
    let ns = if (table_id >> 24) as u8 == 0x23 { "eor/local" } else { "eor/portal" };
    let initial = [ResourceKey::new(ns, table_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new(ns, table_id)) {
        Ok(b) => b,
        Err(_) => return Ok("[]".to_string()),
    };
    let table = match StringTable::unpack(&bytes) {
        Ok(t) => t,
        Err(_) => return Ok("[]".to_string()),
    };
    // Build JSON manually — avoids pulling serde_json or
    // serde_wasm_bindgen. Output shape: [[hashKey, "text"], ...].
    let mut out = String::with_capacity(table.strings.len() * 32);
    out.push('[');
    let mut first = true;
    for (k, v) in &table.strings {
        if !first { out.push(','); }
        first = false;
        out.push('[');
        out.push_str(&k.to_string());
        out.push(',');
        out.push('"');
        for c in v.strings.first().map(|s| s.as_str()).unwrap_or("").chars() {
            match c {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                c if (c as u32) < 0x20 => {
                    out.push_str(&format!("\\u{:04x}", c as u32));
                }
                c => out.push(c),
            }
        }
        out.push('"');
        out.push(']');
    }
    out.push(']');
    Ok(out)
}

/// Fetch a single LanguageString record (DAT type 0x31). Free-form
/// locale text bound to a string ID — used for tooltips, dialog
/// snippets, item-name keys. Returns the decoded text as a JS string,
/// or an empty string if the record is missing.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_language_string(string_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::LanguageString;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", string_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", string_id)) else {
        return Ok(String::new());
    };
    match LanguageString::unpack(&bytes) {
        Ok(ls) => Ok(ls.value),
        Err(_) => Ok(String::new()),
    }
}

/// Fetch the retail ActionMap (DAT type 0x26) — wires action hashes
/// to their StringTable label-hash references. Returns a JSON shape:
///
///   { "string_table_data_id": <u32>,
///     "actions": [{ "input_map": <u32>, "action_hash": <u32>,
///                   "label_hash": <u32>, "toggle": <u32> }, ...] }
///
/// JS resolves `label_hash` through the loaded StringTable to get
/// the human-readable action name ("Cast Spell", "Increase Power",
/// etc.).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_action_map(map_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::ActionMap;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", map_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", map_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let map = match ActionMap::unpack(&bytes) {
        Ok(m) => m,
        Err(_) => return Ok("null".to_string()),
    };
    let mut out = String::with_capacity(8192);
    out.push_str("{\"string_table_data_id\":");
    out.push_str(&map.string_table_data_id.to_string());
    out.push_str(",\"actions\":[");
    let mut first = true;
    for (input_map_key, values) in &map.input_maps {
        for (action_hash, v) in values {
            if !first { out.push(','); }
            first = false;
            out.push_str(&format!(
                "{{\"input_map\":{},\"action_hash\":{},\"label_hash\":{},\"toggle\":{}}}",
                input_map_key, action_hash, v.user_binding.action_name, v.toggle_type,
            ));
        }
    }
    out.push_str("]}");
    Ok(out)
}

/// Fetch one LayoutDesc (DAT 0x21) and serialize its element tree
/// for the JS-side layout consumer chain (real AC UI port).
///
/// LayoutDesc records live in `client_local_English.dat`
/// (namespace `eor/local`); their BaseProperty type tags resolve
/// against the singleton MasterProperty (0x39000001) which lives
/// in `client_portal.dat` (namespace `eor/portal`). Both records
/// must be available; if either is missing we return `null`.
///
/// Returns JSON shape (v3 — additive `state_desc` field for the cached
/// default-state data; all v2 fields preserved):
/// ```json
/// {
///   "id": <u32>,
///   "width": <u32>,
///   "height": <u32>,
///   "elements": [
///     {
///       "key": <u32>,              // outer-dict key (element handle)
///       "element_id": <u32>,       // ElementDesc.element_id
///       "element_type": <u32>,
///       "default_state": <u32>,
///       "x": <u32?>, "y": <u32?>,
///       "width": <u32?>, "height": <u32?>,
///       "z_level": <u32?>,
///       "left_edge": <u32>, "top_edge": <u32>,
///       "right_edge": <u32>, "bottom_edge": <u32>,
///       "state_desc": { ... },   // same StateDesc shape as below;
///                                 // the element's cached default-state.
///       "states": {
///         // UIStateId → StateDesc; usually empty {}; populated for
///         // multi-state elements (lock buttons, dropdowns, etc.):
///         "<u32 state_id>": {
///           "state_id": <u32>,
///           "pass_to_children": <bool>,
///           "incorporation_flags": <u32>,
///           "properties": {
///             // dict_key → BaseProperty variant
///             "<u32>": { "Bool": <bool> } |
///                      { "Integer": <i32> } |
///                      { "Float": <f32> } |
///                      { "Vector": {"x":..,"y":..,"z":..} } |
///                      { "Color": {"b":..,"g":..,"r":..,"a":..} } |
///                      { "Enum": <u32> } |
///                      { "DataId": <u32> } |        // sprite, etc.
///                      { "InstanceId": <u32> } |
///                      { "Bitfield32": <u32> } |
///                      { "Bitfield64": <u64> } |
///                      { "StringInfo": {"token":..,"string_id":..,
///                                       "table_id":..,
///                                       "override_flag":..,
///                                       "unknown1":..,"unknown2":..} } |
///                      { "Array": [...] } |
///                      { "Struct": {<u32>: ...} }
///           },
///           "media": [
///             // MediaDesc variant — tagged by name
///             { "Image": {"file":<u32>,"draw_mode":<u32>} } |
///             { "Alpha": {"file":<u32>} } |
///             { "Sound": {"file":<u32>,"sound":<u32>} } |
///             { "Animation": {"duration":<f32>,"draw_mode":<u32>,
///                             "frames":[<u32>,...]} } |
///             { "Cursor":{...} } | { "Movie":{...} } |
///             { "Jump":{...} } | { "Message":{...} } |
///             { "Pause":{...} } | { "State":{...} } | { "Fade":{...} }
///           ]
///         },
///         ...
///       },
///       "children": [ ... same shape, recursive ... ]
///     },
///     ...
///   ]
/// }
/// ```
///
/// States/properties/media land as the structured serde::Serialize
/// form — discriminant-tagged enums (`{"DataId": 0x06000123}` etc.)
/// so the JS side can switch on the variant name. Empty `states: {}`
/// is the common case (most elements have no overrides).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_layout(layout_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::{LayoutDesc, MasterProperty};
    // Use try_global_source so callers that fire before
    // init_resource_source resolves get a graceful "null" instead of
    // a wasm panic. mountBar-mounted plugins can race init; their
    // 8 × 2s retry loop will re-call once the source is installed.
    let Some(source) = global_source::try_global_source() else {
        return Ok("null".to_string());
    };
    const MASTER_PROPERTY_ID: u32 = 0x39000001;
    let initial = [
        ResourceKey::new("eor/local", layout_id),
        ResourceKey::new("eor/portal", MASTER_PROPERTY_ID),
    ];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;

    let layout_bytes = match source.get_file_by_key(ResourceKey::new("eor/local", layout_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let master_bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", MASTER_PROPERTY_ID)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };

    let master = match MasterProperty::unpack(&master_bytes) {
        Ok(m) => m,
        Err(_) => return Ok("null".to_string()),
    };
    let layout = match LayoutDesc::unpack(&layout_bytes, &master) {
        Ok(l) => l,
        Err(_) => return Ok("null".to_string()),
    };

    fn emit_element(
        out: &mut String,
        key: u32,
        el: &holtburger_dat::file_type::ElementDesc,
        state_desc_err_count: &mut u32,
        states_err_count: &mut u32,
    ) {
        out.push_str("{\"key\":");
        out.push_str(&key.to_string());
        out.push_str(",\"element_id\":");
        out.push_str(&el.element_id.to_string());
        out.push_str(",\"element_type\":");
        out.push_str(&el.element_type.to_string());
        out.push_str(",\"default_state\":");
        out.push_str(&el.default_state.to_string());
        if let Some(x) = el.x { out.push_str(",\"x\":"); out.push_str(&x.to_string()); }
        if let Some(y) = el.y { out.push_str(",\"y\":"); out.push_str(&y.to_string()); }
        if let Some(w) = el.width { out.push_str(",\"width\":"); out.push_str(&w.to_string()); }
        if let Some(h) = el.height { out.push_str(",\"height\":"); out.push_str(&h.to_string()); }
        if let Some(z) = el.z_level { out.push_str(",\"z_level\":"); out.push_str(&z.to_string()); }
        out.push_str(",\"left_edge\":");
        out.push_str(&el.left_edge.to_string());
        out.push_str(",\"top_edge\":");
        out.push_str(&el.top_edge.to_string());
        out.push_str(",\"right_edge\":");
        out.push_str(&el.right_edge.to_string());
        out.push_str(",\"bottom_edge\":");
        out.push_str(&el.bottom_edge.to_string());
        // G3 emission re-enabled (2026-06-05). The element's base
        // `state_desc` (cached default-state data) plus the per-state
        // overrides `states` map both ship to JS so the layout consumers
        // (getElementStates / getStateProperty / getStateMediaByType
        // in ui/ac_layout.js) can resolve sprite DataIds, colors, and
        // media triggers from the DAT instead of CSS approximations.
        // `serde_json::to_string` errors fall back to the prior empty
        // shape so a malformed sub-record can't blow up the whole
        // layout payload.
        //
        // HUD rec #187 (2026-06-16): bump the per-element failure
        // counters so the top-level `ok` / `g3SerializeErrors` summary
        // surfaces fallback hits to the JS diag hook
        // (window.__diag?.layout?.onG3SerializeError).
        let state_desc_json = match serde_json::to_string(&el.state_desc) {
            Ok(s) => s,
            Err(_) => {
                *state_desc_err_count += 1;
                "null".to_string()
            }
        };
        out.push_str(",\"state_desc\":");
        out.push_str(&state_desc_json);
        let states_json = match serde_json::to_string(&el.states) {
            Ok(s) => s,
            Err(_) => {
                *states_err_count += 1;
                "{}".to_string()
            }
        };
        out.push_str(",\"states\":");
        out.push_str(&states_json);
        out.push_str(",\"children\":[");
        let mut first = true;
        for (ck, cv) in &el.children {
            if !first { out.push(','); }
            first = false;
            emit_element(out, *ck, cv, state_desc_err_count, states_err_count);
        }
        out.push_str("]}");
    }

    // HUD rec #187 (2026-06-16): G3 emission diagnostics. Both counters
    // start at 0 and bump per fallback inside emit_element; the
    // top-level layout JSON gains `ok` (true when both are zero) plus
    // per-kind counts. JS reads `__diag.layout.onG3SerializeError` to
    // surface the regression to the diag layer.
    let mut state_desc_err_count: u32 = 0;
    let mut states_err_count: u32 = 0;
    let mut out = String::with_capacity(layout.elements.len() * 256);
    out.push_str("{\"id\":");
    out.push_str(&layout.id.to_string());
    out.push_str(",\"width\":");
    out.push_str(&layout.width.to_string());
    out.push_str(",\"height\":");
    out.push_str(&layout.height.to_string());
    out.push_str(",\"elements\":[");
    let mut first = true;
    for (k, el) in &layout.elements {
        if !first { out.push(','); }
        first = false;
        emit_element(
            &mut out,
            *k,
            el,
            &mut state_desc_err_count,
            &mut states_err_count,
        );
    }
    out.push_str("]");
    // HUD rec #187 (2026-06-16): expose G3 emission outcome at the top
    // level of the JSON payload — `ok=false` when any sub-record fell
    // back to the empty shape, with per-kind counts so JS can pick a
    // useful telemetry label.
    let ok = state_desc_err_count == 0 && states_err_count == 0;
    out.push_str(",\"ok\":");
    out.push_str(if ok { "true" } else { "false" });
    out.push_str(",\"g3SerializeErrors\":{\"stateDesc\":");
    out.push_str(&state_desc_err_count.to_string());
    out.push_str(",\"states\":");
    out.push_str(&states_err_count.to_string());
    out.push_str("}}");
    Ok(out)
}

/// Fetch one KeyMap (DAT 0x14) — retail's factory-default keystroke
/// bindings. The single record `0x14000000` ("gmDefaultMap") + the
/// alt `0x14000002` ("DefaultMap") are the two records retail ships.
///
/// Returns JSON:
/// ```json
/// {
///   "id": <u32>,
///   "name": <string>,
///   "devices": [{"type": <u8>}, ...],
///   "meta_keys": [{"key": <u32>, "modifier": <u32>}, ...],
///   "mappings": [
///     {"input_map": <u32>, "key": <u32>, "modifier": <u32>,
///      "activation": <u32>, "action_hash": <u32>},
///     ...
///   ]
/// }
/// ```
///
/// Per-mapping unpack (handled by the JS resolver in `ui/keymap.js`):
/// `key` decomposes into `(idxDevice, eSubControl, ofsKey)` — the
/// low byte is the device index into `devices[]`, the high u16 is the
/// DirectInput scan code (DIK_*) for keyboard devices. `modifier`
/// bitfield uses 0x80000000=shift, 0x40000000=ctrl, 0x20000000=alt,
/// 0x10000000=meta. `action_hash` matches the ActionMap inner-dict
/// key in the same `input_map` category (114-hit/0-miss cross-check
/// against retail).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_key_map(map_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::KeyMap;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", map_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", map_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let km = match KeyMap::unpack(&bytes) {
        Ok(k) => k,
        Err(_) => return Ok("null".to_string()),
    };
    let mut out = String::with_capacity(km.input_maps.values().map(|m| m.mappings.len()).sum::<usize>() * 96);
    out.push_str("{\"id\":");
    out.push_str(&km.id.to_string());
    out.push_str(",\"name\":\"");
    // Escape any quote/backslash in name — retail names are ASCII
    // ("gmDefaultMap" / "DefaultMap") so this just guards a future drift.
    for ch in km.name.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out.push_str("\",\"devices\":[");
    let mut first = true;
    for d in &km.devices {
        if !first { out.push(','); }
        first = false;
        out.push_str(&format!("{{\"type\":{}}}", d.device_type));
    }
    out.push_str("],\"meta_keys\":[");
    first = true;
    for mk in &km.meta_keys {
        if !first { out.push(','); }
        first = false;
        out.push_str(&format!("{{\"key\":{},\"modifier\":{}}}", mk.key, mk.modifier));
    }
    out.push_str("],\"mappings\":[");
    first = true;
    for (input_map_key, cinput) in &km.input_maps {
        for m in &cinput.mappings {
            if !first { out.push(','); }
            first = false;
            out.push_str(&format!(
                "{{\"input_map\":{},\"key\":{},\"modifier\":{},\"activation\":{},\"action_hash\":{}}}",
                input_map_key, m.key.key, m.key.modifier, m.activation, m.action_hash,
            ));
        }
    }
    out.push_str("]}");
    Ok(out)
}

/// Fetch one CombatManeuverTable (DAT 0x30) — the (stance, height,
/// type) → motion_command lookup the combat plugin needs to replace
/// its `setSwingPose` vibe-pose placeholder with a real motion.
///
/// Returns JSON: `{ "id": <u32>, "maneuvers": [{ "style": <u32>,
/// "attack_height": <u32>, "attack_type": <u32>, "motion": <u32> }, ...] }`.
/// `min_skill_level` is omitted — ACE notes every retail row is 0.
///
/// Lookup pattern (mirrors ACE
/// `Source/Network/Structure/CombatManeuverTable.cs::GetMotion`):
///   filter maneuvers by (style == stance) ∧ (attack_height == height)
///   ∧ (attack_type == type) → list of motion candidates. Power-bar
///   index picks one (see `ui/ac_combat_maneuver.js::getCombatManeuver`).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_combat_maneuver_table(table_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::CombatManeuverTable;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", table_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", table_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let cmt = match CombatManeuverTable::unpack(&bytes) {
        Ok(t) => t,
        Err(_) => return Ok("null".to_string()),
    };
    let mut out = String::with_capacity(cmt.combat_maneuvers.len() * 64);
    out.push_str("{\"id\":");
    out.push_str(&cmt.id.to_string());
    out.push_str(",\"maneuvers\":[");
    let mut first = true;
    for m in &cmt.combat_maneuvers {
        if !first { out.push(','); }
        first = false;
        out.push_str(&format!(
            "{{\"style\":{},\"attack_height\":{},\"attack_type\":{},\"motion\":{}}}",
            m.style, m.attack_height, m.attack_type, m.motion,
        ));
    }
    out.push_str("]}");
    Ok(out)
}

/// Fetch one PaletteSet (DAT 0x0F) — a bundle of Palette (0x04)
/// DataIDs that a `shade` float indexes into for character skin/hair
/// or for ClothingTable `CloSubPalette::palette_set` references.
///
/// Returns JSON: `{ "id": <u32>, "palettes": [<u32>, ...] }`.
/// The full Clothing → palette compose chain is already exercised
/// by `fetch_entity_surface_pixels` for entity surfaces; this export
/// is the standalone reader for character-customization / dye-picker
/// UIs that want to enumerate variants without going through the
/// per-pixel composer.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_palette_set(set_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::PaletteSet;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", set_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", set_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let ps = match PaletteSet::unpack(&bytes) {
        Ok(p) => p,
        Err(_) => return Ok("null".to_string()),
    };
    let mut out = String::with_capacity(ps.palettes.len() * 12 + 32);
    out.push_str("{\"id\":");
    out.push_str(&ps.id.to_string());
    out.push_str(",\"palettes\":[");
    let mut first = true;
    for pid in &ps.palettes {
        if !first { out.push(','); }
        first = false;
        out.push_str(&pid.to_string());
    }
    out.push_str("]}");
    Ok(out)
}

/// Fetch one ClothingTable (DAT 0x10) — wardrobe + dye + body-part
/// substitution definitions used to render equipped items.
///
/// Returns JSON shape (serde_json-driven so the nested HashMap +
/// recursive Vec structure stays accurate; serializing manually
/// would be ~300 LOC of nested for-loops):
///
/// ```json
/// {
///   "id": 268435457,
///   "clothing_base_effects": {
///     "<setup_did>": {
///       "clo_object_effects": [
///         { "index": <u32>, "model_id": <gfxobj_did>,
///           "clo_texture_effects": [
///             { "old_texture": <did>, "new_texture": <did> }, ... ] },
///         ...
///       ]
///     }, ...
///   },
///   "clothing_sub_pal_effects": {
///     "<palette_template_key>": {
///       "icon": <did>,
///       "clo_sub_palettes": [
///         { "palette_set": <did>,
///           "ranges": [{ "offset": <u32>, "num_colors": <u32> }, ...] },
///         ...
///       ]
///     }, ...
///   }
/// }
/// ```
///
/// HashMap keys serialize as JSON strings (serde_json convention);
/// the JS side parses them back to integers in `ui/ac_clothing.js`.
///
/// Note: the spawn-time path already plumbs ModelData.texture_changes
/// + model_changes + sub_palettes into `fetch_entity_animation_keyframes`
/// (~L10778) which composes the visible equipped state for ObjectCreate
/// at line 10827-10830 (Vec<(u8, u32, u32)> tc / Vec<(u8, u32)> mc).
/// This export exists for code that needs to *enumerate* a wardrobe
/// (character creation, dye picker, examine-target UI) without going
/// through the per-pixel surface compositor.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_clothing_table(clothing_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::ClothingTable;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", clothing_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", clothing_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let ct = match ClothingTable::unpack(&bytes) {
        Ok(t) => t,
        Err(_) => return Ok("null".to_string()),
    };
    serde_json::to_string(&ct).map_err(|e| JsValue::from_str(&e.to_string()))
}

/// Wave 7.8 — Phase C dye-preview compositor.
///
/// Mirrors the bottom half of `fetch_entity_surface_pixels_impl`
/// (lib.rs:~L5432-5648) but takes a SurfaceTexture (0x05) DID
/// directly — skipping the Surface (0x08) → SurfaceTexture
/// indirection. This is the right shape for dye previews, where
/// callers have a `CloTextureEffect.new_texture` (a SurfaceTexture
/// DID) in hand and want to see what shade=N would render against
/// it. The entity render path that ACE pre-bakes server-side
/// composes the same SurfaceTexture(s) inside a Surface wrap; we
/// short-circuit the wrap because the icon-or-swatch use case
/// doesn't need it.
///
/// Returns a `SurfacePixels` (same shape as `fetch_entity_surfaces_
/// pixels` returns per-element). When `surface_texture_did` doesn't
/// resolve OR the wasm chain fails at any step, returns an empty
/// `SurfacePixels` (width=0, height=0).
///
/// `sub_palettes` is the flat `[palette_did, offset, length, …]`
/// triple buffer — same encoding as `fetch_entity_surfaces_pixels`
/// uses. Each triple's first u32 is an ALREADY-RESOLVED Palette
/// (0x04) DID per `pickPaletteForShade(loadPaletteSet(set), shade)`
/// JS-side (mirrors ACE `GetPaletteID(shade)` in `CalculateObjDesc`).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_dye_preview_pixels(
    surface_texture_did: u32,
    sub_palettes: Vec<u32>,
) -> Result<SurfacePixels, JsValue> {
    use holtburger_dat::file_type::{Palette, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::surface_classify::{compute_stats, SurfaceCategory};
    let generic_cat = SurfaceCategory::Generic.as_u8();
    let empty = SurfacePixels {
        width: 0,
        height: 0,
        pixels: Vec::new(),
        surface_type: 0,
        category: generic_cat,
        normal_pixels: Vec::new(),
        height_pixels: Vec::new(),
        roughness_override: f32::NAN,
        normal_scale_override: f32::NAN,
        translucency: 0.0,
        luminosity: 0.0,
        diffuse: 0.0,
        // A10-M3a — empty fallback: no texture → ddsRef-200 class (false).
        has_palette: false,
    };
    if sub_palettes.len() % 3 != 0 {
        return Err(JsValue::from_str(
            "fetch_dye_preview_pixels: sub_palettes must be flat [paletteDid, offset, length, ...] triples",
        ));
    }
    // Dye-preview triples come from ClothingTable CloSubPaletteRange, whose
    // offset/numColors are absolute palette indices (uint32, often >255 for
    // 2048-entry body palettes) — NOT the /8-packed bytes of the wire path.
    // Keep them as u32 so they aren't truncated (pre-2026-05-28 `as u8` wrapped
    // any offset >255 to garbage).
    let triples: Vec<(u32, u32, u32)> = sub_palettes
        .chunks_exact(3)
        .map(|c| (c[0], c[1], c[2]))
        .collect();
    let source = global_source::global_source();
    // Prefetch: SurfaceTexture itself + every overlay Palette. The
    // closure runs the SurfaceTexture → Texture → intrinsic-Palette
    // walk after the initial keys land so the shard cache drags in
    // every transitive dependency before we attempt the actual
    // compositor walk (matches the entity-surfaces-pixels pattern at
    // lib.rs:~L5808).
    let mut initial: Vec<ResourceKey<'_>> = Vec::with_capacity(1 + triples.len());
    initial.push(ResourceKey::new("eor/portal", surface_texture_did));
    for (id, _, _) in &triples {
        initial.push(ResourceKey::new("eor/portal", *id));
    }
    let did_for_walk = surface_texture_did;
    prefetch::ensure_walk_prefetched(&source, &initial, move |s| {
        let Ok(stb) = s.get_file_by_key(ResourceKey::new("eor/portal", did_for_walk)) else { return; };
        let Ok(surf_tex) = SurfaceTexture::unpack(&stb) else { return; };
        let Some(rs_id) = surf_tex.highest_res() else { return; };
        let Ok(tb) = s.get_file_by_key(ResourceKey::new("eor/portal", rs_id)) else { return; };
        let Ok(tex) = Texture::unpack(&tb) else { return; };
        // Touch intrinsic-palette IDs so they land in the shard cache.
        // to_rgba8 calls the palette-id callback for each unique
        // palette the Texture references; just iterating it triggers
        // the prefetch via the closure-call into the source.
        let _ = tex.to_rgba8(|pal_id| {
            let _ = s.get_file_by_key(ResourceKey::new("eor/portal", pal_id));
            Err::<Palette, _>(TextureDecodeError::PaletteFetch("prefetch-only walk".to_string()))
        });
    }).await?;
    let Ok(stb) = source.get_file_by_key(ResourceKey::new("eor/portal", surface_texture_did)) else {
        return Ok(empty);
    };
    let Ok(surf_tex) = SurfaceTexture::unpack(&stb) else { return Ok(empty); };
    let Some(rs_id) = surf_tex.highest_res() else { return Ok(empty); };
    let Ok(tb) = source.get_file_by_key(ResourceKey::new("eor/portal", rs_id)) else {
        return Ok(empty);
    };
    let Ok(tex) = Texture::unpack(&tb) else { return Ok(empty); };
    // CustomRawJpeg (PFID 500) carries width=height=0 in the header — the real
    // size lives in the JPEG SOF marker. `actual_dimensions()` resolves it
    // (no-op for other formats). See fetch_surface_pixels_impl note. 2026-05-30.
    let (tex_w, tex_h) = tex.actual_dimensions();
    let rgba = tex.to_rgba8(|tex_palette_id| {
        let pb = source
            .get_file_by_key(ResourceKey::new("eor/portal", tex_palette_id))
            .map_err(|e| TextureDecodeError::PaletteFetch(format!("base {tex_palette_id:#010X}: {e}")))?;
        let mut composed = Palette::unpack(&pb)
            .map_err(|e| TextureDecodeError::PaletteFetch(format!("Palette::unpack base {tex_palette_id:#010X}: {e}")))?;
        for (sub_id, offset, length) in &triples {
            let Ok(spb) = source.get_file_by_key(ResourceKey::new("eor/portal", *sub_id)) else { continue; };
            let Ok(sp) = Palette::unpack(&spb) else { continue; };
            // ClothingTable CloSubPaletteRange offset/numColors are already
            // absolute (acclient BuildObjDesc copies them raw — no /8). The copy
            // is dst[i] = src[i] over [off, off+count) (Palette::Modify) — NOT
            // src[0..]. Pre-2026-05-28 this read src[i] (from index 0), pulling
            // the wrong colours whenever offset > 0.
            let off = *offset as usize;
            let count = *length as usize;
            composed.splice_from(&sp, off, count);
        }
        Ok(composed)
    });
    match rgba {
        Ok(pixels) => {
            let stats = compute_stats(&pixels, tex_w, tex_h);
            let (category, _, _) = classify_with_overrides(&stats, 0, surface_texture_did);
            Ok(SurfacePixels {
                width: tex_w,
                height: tex_h,
                pixels,
                surface_type: 0,
                category,
                normal_pixels: Vec::new(),
                height_pixels: Vec::new(),
                roughness_override: f32::NAN,
                normal_scale_override: f32::NAN,
                translucency: 0.0,
                luminosity: 0.0,
                diffuse: 0.0,
                // A10-M3a — dye preview decodes a real Texture; report its
                // palette-indexedness like the other textured sites.
                has_palette: tex.format().needs_palette(),
            })
        }
        Err(_) => Ok(empty),
    }
}

/// Fetch one Palette (DAT 0x04) — a 256-colour ARGB lookup table.
///
/// Returns JSON: `{ "id": <u32>, "colors": [<argb_u32>, ...] }`.
/// Each `colors[i]` is an ARGB u32 (alpha in the high byte). JS parses
/// with `JSON.parse` and the runtime in `ui/ac_palette.js` exposes
/// `paletteColor(palette, index) → {r,g,b,a}` helpers.
///
/// Wave 7.7 (2026-05-24). Used by the dye-preview foundation — Phase
/// B of `handoff-clothing-table-2026-05-24.md` § C. The spawn-time
/// dye compositor (lib.rs::fetch_entity_surface_pixels_impl) already
/// reads Palette records internally; this export is for any plugin
/// that needs to inspect the raw colour table (dye picker thumbnails,
/// character creation swatches, debug overlays).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_palette(palette_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::Palette;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", palette_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", palette_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let p = match Palette::unpack(&bytes) {
        Ok(p) => p,
        Err(_) => return Ok("null".to_string()),
    };
    let mut out = String::with_capacity(p.colors.len() * 12 + 32);
    out.push_str("{\"id\":");
    out.push_str(&p.id.to_string());
    out.push_str(",\"colors\":[");
    let mut first = true;
    for c in &p.colors {
        if !first { out.push(','); }
        first = false;
        out.push_str(&c.to_string());
    }
    out.push_str("]}");
    Ok(out)
}

/// Fetch one GfxObjDegradeInfo (DAT 0x11) — the distance-banded LOD
/// chain a renderer consults when picking which alternate GfxObj to
/// draw for a given camera distance.
///
/// Returns JSON: `{ "id": <u32>, "degrades": [{ "gfx_obj_id": <u32>,
/// "degrade_mode": <u32>, "min_dist": <f32>, "ideal_dist": <f32>,
/// "max_dist": <f32> }, ...] }`.
///
/// JS-side band selection lives in `ui/ac_lod.js::pickDegradeBand`.
/// The existing statics.js LOD path uses `resolve_did_degrade` to
/// get the chain DID, then loads ONE swap via `fetchModelMeshes`;
/// entity LOD would use this export instead, walk the bands, and
/// substitute the band's `gfx_obj_id` for the original setup before
/// loading mesh keyframes. Entity-side integration is deferred — see
/// `docs/handoff-degrade-info-entity-lod-2026-05-24.md`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_gfx_obj_degrade_info(degrade_id: u32) -> Result<String, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::GfxObjDegradeInfo;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", degrade_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", degrade_id)) {
        Ok(b) => b,
        Err(_) => return Ok("null".to_string()),
    };
    let di = match GfxObjDegradeInfo::unpack(&bytes) {
        Ok(d) => d,
        Err(_) => return Ok("null".to_string()),
    };
    let mut out = String::with_capacity(di.degrades.len() * 96 + 32);
    out.push_str("{\"id\":");
    out.push_str(&di.id.to_string());
    out.push_str(",\"degrades\":[");
    let mut first = true;
    for d in &di.degrades {
        if !first { out.push(','); }
        first = false;
        out.push_str(&format!(
            "{{\"gfx_obj_id\":{},\"degrade_mode\":{},\"min_dist\":{},\"ideal_dist\":{},\"max_dist\":{}}}",
            d.gfx_obj_id, d.degrade_mode, d.min_dist, d.ideal_dist, d.max_dist,
        ));
    }
    out.push_str("]}");
    Ok(out)
}

/// A11-S4 (2026-06-12, `?particleDegrade=retail`) — the retail
/// `GfxObjDegradeInfo::get_max_degrade_distance` band pick
/// (acclient.c:332193-332204): `num_degrades <= 2` reads entry 0's
/// `max_dist`; otherwise the decomp reads the float immediately before
/// `&degrades[n-1]` — i.e. the SECOND-TO-LAST entry's `max_dist`
/// (`max_dist` is the last f32 field of the 20-byte GfxObjInfo). The
/// last band is the open-ended "draw nothing past here" sentinel; the
/// max DEGRADE distance is the boundary before it. Empty chain falls
/// back to the retail 100.0 default (`CPhysicsPart::
/// GetMaxDegradeDistance` null-degrades arm, acclient.c:0050D510 body
/// at :314372-314383 — retail never reaches the n==0 read because the
/// pointer is null instead; our unpack can produce an empty vec, so
/// default conservatively).
#[cfg(any(target_arch = "wasm32", test))]
fn max_degrade_distance(degrades: &[holtburger_dat::file_type::GfxObjInfo]) -> f32 {
    const RETAIL_DEFAULT_DEGRADE_DISTANCE: f32 = 100.0;
    match degrades.len() {
        0 => RETAIL_DEFAULT_DEGRADE_DISTANCE,
        n if n <= 2 => degrades[0].max_dist,
        n => degrades[n - 2].max_dist,
    }
}

#[cfg(test)]
mod a11_s4_degrade_tests {
    use super::max_degrade_distance;
    use holtburger_dat::file_type::GfxObjInfo;

    fn band(max_dist: f32) -> GfxObjInfo {
        GfxObjInfo {
            gfx_obj_id: 0x0100_0001,
            degrade_mode: 0,
            min_dist: 0.0,
            ideal_dist: max_dist * 0.5,
            max_dist,
        }
    }

    /// Pins the retail acclient.c:332193-332204 band pick: n<=2 reads
    /// entry 0's max_dist; n>2 reads the SECOND-TO-LAST entry's
    /// max_dist (`(float*)&degrades[n-1] - 1`); empty = the 100.0
    /// GetMaxDegradeDistance null-chain default (:314372-314383).
    #[test]
    fn max_degrade_distance_matches_retail_band_pick() {
        assert_eq!(max_degrade_distance(&[]), 100.0, "null-chain default");
        assert_eq!(max_degrade_distance(&[band(25.0)]), 25.0, "n=1 -> entry 0");
        assert_eq!(
            max_degrade_distance(&[band(25.0), band(50.0)]),
            25.0,
            "n=2 -> entry 0 (second-to-last)"
        );
        assert_eq!(
            max_degrade_distance(&[band(10.0), band(25.0), band(50.0)]),
            25.0,
            "n=3 -> entry 1 (second-to-last)"
        );
        assert_eq!(
            max_degrade_distance(&[band(10.0), band(25.0), band(50.0), band(100.0)]),
            50.0,
            "n=4 -> entry 2 (second-to-last)"
        );
    }
}

/// A11-S4 (2026-06-12, `?particleDegrade=retail`) — the authored
/// per-GfxObj particle degrade radius, meters. Retail wiring:
/// `ParticleEmitter::InitEnd` sets `degrade_distance =
/// CPhysicsPart::GetMaxDegradeDistance(part_storage[0])`
/// (acclient.c:331265+ region) — `part_storage[0]` is the part built
/// from the emitter's hw GfxObj, so the key here is the emitter info's
/// `hwGfxObjId`. `GetMaxDegradeDistance` returns 100.0 when the part
/// carries no degrade chain (acclient.c:314372-314383), else the
/// chain's max band boundary (see [`max_degrade_distance`]).
///
/// `UpdateParticles` then culls via
/// `CPhysicsObj::ShouldDrawParticles(degrade_distance)` — camera
/// distance beyond the radius → `SetNoDraw(1)` + freeze, auto-recover
/// on re-entry (acclient.c:331097-331139, :317184-317199). The JS
/// consumer (`particle_manager.js` `_rp6ShouldCull`) folds this in as
/// an OR-term on the shipped RP6 cull, whose visibility-flip + freeze
/// + re-entry restore is the same observable contract.
///
/// Resolution: `resolve_did_degrade(hw_gfx_obj_id)` (0x01 GfxObj →
/// `did_degrade`, 0 when `HAS_DID_DEGRADE` unset) → 0x11
/// `GfxObjDegradeInfo` unpack → band pick. Missing/parse-failed
/// records return the retail 100.0 default (the no-chain arm).
///
/// ADDITIVE export — rides manifest v4, no bump (F18-2: the JS caller
/// is flag-gated + typeof-guarded; a stale pkg/ keeps the field at
/// `Infinity` = RP6-only culling).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_particle_degrade_distance(hw_gfx_obj_id: u32) -> Result<f32, JsValue> {
    use holtburger_dat::file_type::GfxObjDegradeInfo;
    use holtburger_dat::{ResourceKey, ResourceSource};
    const RETAIL_DEFAULT_DEGRADE_DISTANCE: f32 = 100.0;
    let source = global_source::global_source();
    // Prefetch the GfxObj so resolve_did_degrade's sync read hits.
    let initial = [ResourceKey::new("eor/portal", hw_gfx_obj_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let degrade_id = resolve_did_degrade(source.as_ref(), hw_gfx_obj_id);
    if degrade_id == 0 {
        // No degrade chain — retail GetMaxDegradeDistance default.
        return Ok(RETAIL_DEFAULT_DEGRADE_DISTANCE);
    }
    let chain = [ResourceKey::new("eor/portal", degrade_id)];
    prefetch::ensure_walk_prefetched(&source, &chain, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", degrade_id)) {
        Ok(b) => b,
        Err(_) => return Ok(RETAIL_DEFAULT_DEGRADE_DISTANCE),
    };
    let di = match GfxObjDegradeInfo::unpack(&bytes) {
        Ok(d) => d,
        Err(_) => return Ok(RETAIL_DEFAULT_DEGRADE_DISTANCE),
    };
    Ok(max_degrade_distance(&di.degrades))
}

/// Wave 7.4 (2026-05-24): one-shot LOD pick for an entity at a given
/// camera distance. Composes `resolve_did_degrade` (which walks
/// SetupModel → first GfxObj → did_degrade) + GfxObjDegradeInfo
/// unpack + band selection in wasm so JS gets a single call → single
/// substitute setupId answer.
///
/// Returns the band's `gfx_obj_id` (0x01 prefix) suitable for direct
/// substitution into `fetchEntityAnimationKeyframes` — that export
/// already branches on `(setup_id >> 24) != 0x02` and takes the 0x01
/// GfxObj direct path (lib.rs:10840-10925). When no LOD chain exists
/// for the input setup OR no band's `[min_dist, max_dist)` window
/// contains the input distance, returns 0 and the caller falls back
/// to the original setup. Matches the statics path that already
/// substitutes via `resolve_did_degrade` at spawn time.
///
/// Distance is in meters (camera-to-entity horizontal in AC world
/// frame). 0.0 returns the original setup (no substitution); callers
/// should pre-compute the actual distance.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_entity_degrade_for_distance(
    setup_id: u32,
    distance: f32,
) -> Result<u32, JsValue> {
    use holtburger_dat::{ResourceKey, ResourceSource};
    use holtburger_dat::file_type::GfxObjDegradeInfo;
    if !distance.is_finite() || distance <= 0.0 {
        return Ok(0);
    }
    let source = global_source::global_source();
    // Prefetch the source setup chain so resolve_did_degrade can walk
    // SetupModel → first GfxObj. Matches the prefetch shape used by
    // fetch_entity_animation_keyframes ahead of its own degrade reads.
    let initial = [ResourceKey::new("eor/portal", setup_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |_| {}).await?;
    let degrade_id = resolve_did_degrade(source.as_ref(), setup_id);
    if degrade_id == 0 {
        return Ok(0);
    }
    // Prefetch the chain itself before unpack — the source might not
    // have walked into it during the setup-only prefetch above.
    let initial2 = [ResourceKey::new("eor/portal", degrade_id)];
    prefetch::ensure_walk_prefetched(&source, &initial2, |_| {}).await?;
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", degrade_id)) {
        Ok(b) => b,
        Err(_) => return Ok(0),
    };
    let di = match GfxObjDegradeInfo::unpack(&bytes) {
        Ok(d) => d,
        Err(_) => return Ok(0),
    };
    for band in &di.degrades {
        if distance >= band.min_dist && distance < band.max_dist {
            return Ok(band.gfx_obj_id);
        }
    }
    Ok(0)
}

/// Phase 4 step 6 Phase B: surface decode with entity palette overrides.
/// ACE's `CalculateObjDesc` (~/ace-server/Source/ACE.Server/WorldObjects/
/// WorldObject_Networking.cs:1017 + Creature_Networking.cs:218) sets
/// `objDesc.PaletteID` to the entity's `PaletteBaseDID` and accumulates
/// per-clothing-item palette overlays in `objDesc.SubPalettes` after
/// reading each item's `ClothingTable.ClothingSubPalEffects[paletteTemplate]`
/// and offset+length-scaling them. Mirroring it here lets a creature's
/// skin tone, hair colour, and dyed armour read correctly instead of
/// every NPC defaulting to the texture's intrinsic palette.
///
/// Composition order (matches the C#):
/// 1. **Base palette.** If `base_palette_id != 0` use it as the starting
///    256-entry colour array (overrides the texture's intrinsic palette).
///    If 0, fall through to the texture's intrinsic palette ID — same
///    path as `fetch_surface_pixels_impl`.
/// 2. **Sub-palette overlays.** For each `(sub_palette_id, offset,
///    length)` triple: read the named palette from the DAT, copy its
///    first `length` colours into the base palette starting at `offset`.
///    Out-of-range writes are clamped (NPC equipment overlays are
///    8-colour ranges that always fit a 256-entry palette in retail
///    data, but defensive clamping keeps a malformed wire packet from
///    panicking the decoder).
///
/// `sub_palettes` is the flat `[id, offset, length, …]` triple buffer
/// EntityUpdate exposes from `model_data.sub_palettes` (Phase A
/// already plumbed it; Phase B consumes it).
#[cfg(any(target_arch = "wasm32", test))]
fn fetch_entity_surface_pixels_impl<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    surface_did: u32,
    base_palette_id: u32,
    sub_palettes: &[(u32, u8, u8)],
) -> SurfacePixels {
    use holtburger_dat::file_type::{Palette, Surface, SurfaceTexture, Texture, TextureDecodeError};
    use holtburger_dat::normal_gen::{height_from_luminance, normal_from_luminance};
    use holtburger_dat::surface_classify::{compute_stats, surface_type_flags::LUMINOUS, SurfaceCategory};
    use holtburger_dat::ResourceKey;
    let generic_cat = SurfaceCategory::Generic.as_u8();
    let empty = SurfacePixels {
        width: 0,
        height: 0,
        pixels: Vec::new(),
        surface_type: 0,
        category: generic_cat,
        normal_pixels: Vec::new(),
        height_pixels: Vec::new(),
        roughness_override: f32::NAN,
        normal_scale_override: f32::NAN,
        translucency: 0.0,
        luminosity: 0.0,
        diffuse: 0.0,
        // A10-M3a — empty fallback: no texture → ddsRef-200 class (false).
        has_palette: false,
    };

    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", surface_did)) else { return empty; };
    let Ok(surface) = Surface::unpack(&bytes) else { return empty; };
    let surface_type = surface.surface_type;
    if let Some(argb) = surface.solid_color() {
        // Solid surfaces ignore palette substitutions — the base
        // surface IS the colour.
        let a = ((argb >> 24) & 0xFF) as u8;
        let r = ((argb >> 16) & 0xFF) as u8;
        let g = ((argb >> 8) & 0xFF) as u8;
        let b = (argb & 0xFF) as u8;
        let pixels = vec![r, g, b, a];
        // Phase 1.5 — overrides apply to entity surfaces too.
        let stats = compute_stats(&pixels, 1, 1);
        let (category, roughness_override, normal_scale_override) =
            classify_with_overrides(&stats, surface_type, surface_did);
        return SurfacePixels {
            width: 1,
            height: 1,
            pixels,
            surface_type,
            category,
            normal_pixels: Vec::new(),
            height_pixels: Vec::new(),
            roughness_override,
            normal_scale_override,
            translucency: surface.translucency,
            luminosity: surface.luminosity,
            diffuse: surface.diffuse,
            // A10-M3a — solid 1x1: retail reaches the ref pick with
            // curr_texture_is_set = (GetTextureMap != 0) (acclient.c:454411)
            // and !curr_texture_is_set short-circuits to the 200 ref
            // (acclient.c:454506-454507) → false.
            has_palette: false,
        };
    }
    let Some((surf_tex_id, _)) = surface.textured() else { return empty; };
    let Ok(stb) = source.get_file_by_key(ResourceKey::new("eor/portal", surf_tex_id)) else { return empty; };
    let Ok(surf_tex) = SurfaceTexture::unpack(&stb) else { return empty; };
    let Some(rs_id) = surf_tex.highest_res() else { return empty; };
    let Ok(tb) = source.get_file_by_key(ResourceKey::new("eor/portal", rs_id)) else { return empty; };
    let Ok(tex) = Texture::unpack(&tb) else { return empty; };
    // CustomRawJpeg (PFID 500) carries width=height=0 in the header — the real
    // size lives in the JPEG SOF marker. `actual_dimensions()` resolves it
    // (no-op for other formats). See fetch_surface_pixels_impl note. 2026-05-30.
    let (tex_w, tex_h) = tex.actual_dimensions();

    // Compose the palette inside `to_rgba8`'s callback — receives
    // the texture's intrinsic palette id but we may override with
    // the entity's base + apply overlays.
    let rgba = tex.to_rgba8(|tex_palette_id| {
        let chosen_base = if base_palette_id != 0 { base_palette_id } else { tex_palette_id };
        let pb = source
            .get_file_by_key(ResourceKey::new("eor/portal", chosen_base))
            .map_err(|e| TextureDecodeError::PaletteFetch(format!("base {chosen_base:#010X}: {e}")))?;
        let mut composed = Palette::unpack(&pb)
            .map_err(|e| TextureDecodeError::PaletteFetch(format!("Palette::unpack base {chosen_base:#010X}: {e}")))?;
        // Apply per-overlay sub-palette splices. Per-overlay failures
        // are silently skipped — a missing or malformed sub-palette
        // shouldn't fail the whole texture decode (worst case the
        // creature renders with an unblended palette, which is what
        // the unsubstituted path produces anyway).
        for (sub_id, offset, length) in sub_palettes {
            let Ok(spb) = source.get_file_by_key(ResourceKey::new("eor/portal", *sub_id)) else { continue; };
            let Ok(sp) = Palette::unpack(&spb) else { continue; };
            // Wire ObjDesc sub-palettes pack offset/numColors as /8 bytes
            // (acclient Subpalette::UnPack: offset = byte*8;
            // numColors = (byte==0 ? 256 : byte) * 8). The copy is dst[i] = src[i]
            // over the absolute range [off, off+count) (Palette::Modify) — NOT
            // src[0..]. Pre-2026-05-28 this used raw byte offset + src[i], so
            // every server-pushed recolor (skin/hair/eyes/dyed armor) landed in
            // the wrong, far-too-small palette slice and read the wrong source.
            let off = (*offset as usize) * 8;
            let count = (if *length == 0 { 256 } else { *length as usize }) * 8;
            composed.splice_from(&sp, off, count);
        }
        Ok(composed)
    });
    match rgba {
        Ok(pixels) => {
            // Phase 1.5 — overrides applied via classify_with_overrides.
            let stats = compute_stats(&pixels, tex_w, tex_h);
            let (category, roughness_override, normal_scale_override) =
                classify_with_overrides(&stats, surface_type, surface_did);
            // Phase 1.1 — Sobel normal map; skip Luminous (emissive).
            // Phase 3.1 — same skip rule for the heightmap.
            let (normal_pixels, height_pixels) = if (surface_type & LUMINOUS) != 0 {
                (Vec::new(), Vec::new())
            } else {
                (
                    normal_from_luminance(&pixels, tex_w, tex_h, 1.0),
                    height_from_luminance(&pixels, tex_w, tex_h, 1.0),
                )
            };
            SurfacePixels {
                width: tex_w,
                height: tex_h,
                pixels,
                surface_type,
                category,
                normal_pixels,
                height_pixels,
                roughness_override,
                normal_scale_override,
                translucency: surface.translucency,
                luminosity: surface.luminosity,
                diffuse: surface.diffuse,
                // A10-M3a — textured: palette-indexed iff P8/Index16
                // (retail ImgTex::m_pPalette non-null → 256-ref 100,
                // acclient.c:454506-454509).
                has_palette: tex.format().needs_palette(),
            }
        }
        Err(_) => empty,
    }
}

/// Batch form of [`fetch_entity_surface_pixels_impl`] exposed to JS.
/// `base_palette_id` and `sub_palettes` apply to **every** surface in
/// `surface_dids` — appropriate for an NPC where one entity's palette
/// state composes onto every body-part surface uniformly. The JS
/// caller picks the surfaces from a single mesh's `surfaces` array
/// and passes the entity's `palette_id` + `sub_palettes`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchEntitySurfacesPixels)]
pub async fn fetch_entity_surfaces_pixels(
    surface_dids: Vec<u32>,
    base_palette_id: u32,
    sub_palettes: Vec<u32>,
) -> Result<Vec<SurfacePixels>, JsValue> {
    use holtburger_dat::ResourceKey;
    if sub_palettes.len() % 3 != 0 {
        return Err(JsValue::from_str(
            "fetch_entity_surfaces_pixels: sub_palettes must be flat [id, offset, length, ...] triples (length % 3 == 0)",
        ));
    }
    let sp: Vec<(u32, u8, u8)> = sub_palettes
        .chunks_exact(3)
        .map(|c| (c[0], c[1] as u8, c[2] as u8))
        .collect();
    let source = global_source::global_source();
    // Prefetch: the surfaces themselves, the base palette (if
    // overridden), and every overlay palette. Surface→tex→intrinsic-
    // palette walks ride into the surface prefetch already.
    let mut initial: Vec<ResourceKey<'_>> = Vec::with_capacity(surface_dids.len() + 1 + sp.len());
    for &sid in &surface_dids {
        initial.push(ResourceKey::new("eor/portal", sid));
    }
    if base_palette_id != 0 {
        initial.push(ResourceKey::new("eor/portal", base_palette_id));
    }
    for (id, _, _) in &sp {
        initial.push(ResourceKey::new("eor/portal", *id));
    }
    let dids_for_walk = surface_dids.clone();
    let sp_for_walk = sp.clone();
    // F.37 walk-result dedup. Two entities sharing the same
    // (DID-set, base_palette_id, sub_palettes) tuple now share a
    // single prefetch loop. The sub-palette triples are folded
    // into the cache key alongside the DID list.
    let sp_flat: Vec<u32> = sp
        .iter()
        .flat_map(|(id, off, len)| [*id, *off as u32, *len as u32])
        .collect();
    let cache_key = prefetch::WalkCacheKey::new("fetchEntitySurfacesPixels")
        .with_u32(base_palette_id)
        .with_u32_slice(&surface_dids)
        .with_u32_slice(&sp_flat);
    prefetch::ensure_walk_prefetched_keyed(cache_key, &source, &initial, move |s| {
        for &id in &dids_for_walk {
            let _ = fetch_entity_surface_pixels_impl(s, id, base_palette_id, &sp_for_walk);
        }
    })
    .await?;
    let mut out = Vec::with_capacity(surface_dids.len());
    for &id in &surface_dids {
        out.push(fetch_entity_surface_pixels_impl(
            source.as_ref(),
            id,
            base_palette_id,
            &sp,
        ));
    }
    Ok(out)
}

// F.41 (2026-05-15) — batched fetchEntitySurfacesPixels.
//
// Mirror of F.40's batched-keyframes pattern, applied to the surface
// fetch path. F.40's report identified surfaces as the next bottleneck:
// each entity in a populated Holtburg LB still opens its own
// `fetch_entity_surfaces_pixels` call (5+ surfaces/entity × 13 entities
// = 65 surface walks, none batched). F.37's walk-result dedup helps
// concurrent callers with the SAME `(DID-set, palette)` tuple share a
// single loop, but each distinct group still pays the full walk cost.
//
// The batch accepts N groups (one per entity) in flat-array form:
//   - `flat_surface_dids` — concatenated surface DIDs across all
//     groups, in input order.
//   - `surface_dids_lens` — count of surface DIDs per group (parallel
//     to entity index); `flat_surface_dids[offsets[i]..offsets[i]+lens[i]]`
//     is group i's DID slice.
//   - `base_palette_ids` — one u32 per entity (0 = no palette override).
//   - `flat_sub_palettes` — concatenated `[id, off, len, ...]` triples
//     across all groups (3 u32 per triple).
//   - `sub_palettes_triple_counts` — count of triples per entity.
//
// Walk:
//   1. Compute the union of every referenced record: every surface DID
//      across all groups, every overridden base palette, every sub-
//      palette DID. Seed `ensure_walk_prefetched_keyed` with this set.
//   2. The walk closure visits every group's `fetch_entity_surface_pixels_impl`
//      in one round — the `RecordingSource` accumulates misses across
//      all groups; the next prefetch round resolves the union in one
//      shared HTTP-fetch batch via `ManifestResourceSource::prefetch`'s
//      `Promise.all` parallelism.
//   3. After prefetch convergence, build one `Vec<SurfacePixels>` per
//      input group in input order. Per-group construction is sync —
//      every record is in the warm `shards` cache.
//
// Errors per-group: surfaces that fail to load yield the empty
// `SurfacePixels` shape `fetch_entity_surface_pixels_impl` already
// returns (width=0, height=0, etc.) — preserved per-DID so the JS
// `_installFromPixels` fallback path stays load-bearing. A group with
// every DID failing produces a `Vec` of empties (not a top-level error).
// Top-level errors only surface from `ensure_walk_prefetched_keyed`'s
// HTTP failure path (mirrors the single-call API's contract).

/// F.41 (2026-05-15) — wasm-bindgen wrapper for the batched
/// `fetchEntitySurfacesPixels` output. Parallel to input order:
/// `payload_at(i)` returns the `Vec<SurfacePixels>` for entity i.
///
/// **Consumer pattern (JS).**
/// ```ignore
/// const batch = await wasm.fetchEntitySurfacesPixelsBatch(
///     new Uint32Array(flatSurfaceDids),
///     new Uint32Array(surfaceDidsLens),
///     new Uint32Array(basePaletteIds),
///     new Uint32Array(flatSubPalettes),
///     new Uint32Array(subPalettesTripleCounts),
/// );
/// for (let i = 0; i < batch.len; i += 1) {
///     const pixelsArray = batch.payloadAt(i); // Array<SurfacePixels>
///     // install into materials + dispose handles...
/// }
/// batch.free();
/// ```
///
/// **Lifetime.** `payload_at(i)` MOVES the i-th group's
/// `Vec<SurfacePixels>` out — receiving JS owns the wasm-bindgen
/// handles and is responsible for `sp.free()` per SurfacePixels.
/// Subsequent calls for the same `i` return None. Mirrors F.40's
/// `EntityAnimationKeyframesBatch::payload_at`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct EntitySurfacesPixelsBatch {
    payloads: Vec<Option<Vec<SurfacePixels>>>,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl EntitySurfacesPixelsBatch {
    /// Number of input groups — equals `payloads.len()`.
    #[wasm_bindgen(getter)]
    pub fn len(&self) -> usize {
        self.payloads.len()
    }

    /// Whether `payload_at(i)` would return None (out of range OR
    /// already drained). Idempotent.
    #[wasm_bindgen(js_name = wasDrained)]
    pub fn was_drained(&self, i: usize) -> bool {
        i >= self.payloads.len() || self.payloads[i].is_none()
    }

    /// Move the `i`-th payload out of the batch. Returns `None` if
    /// `i` is out of range or this slot was already drained.
    /// **Single-shot** — second call returns None.
    #[wasm_bindgen(js_name = payloadAt)]
    pub fn payload_at(&mut self, i: usize) -> Option<Vec<SurfacePixels>> {
        if i >= self.payloads.len() {
            return None;
        }
        self.payloads[i].take()
    }
}

/// F.41 (2026-05-15) — batch wrapper around
/// [`fetch_entity_surfaces_pixels`]. Walks N groups in **one** prefetch
/// loop so their union of referenced records gets fetched in shared
/// `prefetch(...)` rounds (instead of N independent loops each issuing
/// their own rounds).
///
/// **Use case.** Spawn pipeline for a populated landblock: ~13 entities
/// × 5+ surfaces/entity = 65+ surface walks. Pre-F.41: each entity's
/// `_spawnImpl` independently calls `fetchEntitySurfacesPixels` →
/// opens its own prefetch loop. Post-F.41: spawns.js collects per-
/// entity surface-DID groups + palette state and fires ONE batch call;
/// each entity's downstream material build pulls from the warm
/// wasm-side `shards` cache (sync-fast).
///
/// **Bit-equivalence with single-call API.** `payload_at(i)` is
/// bit-equivalent to a standalone `fetchEntitySurfacesPixels(group_i)`
/// call. The post-prefetch construction is identical
/// (`fetch_entity_surface_pixels_impl` per DID per group) — only the
/// prefetch round-trips collapse.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchEntitySurfacesPixelsBatch)]
pub async fn fetch_entity_surfaces_pixels_batch(
    flat_surface_dids: Vec<u32>,
    surface_dids_lens: Vec<u32>,
    base_palette_ids: Vec<u32>,
    flat_sub_palettes: Vec<u32>,
    sub_palettes_triple_counts: Vec<u32>,
) -> Result<EntitySurfacesPixelsBatch, JsValue> {
    use holtburger_dat::ResourceKey;

    let n = surface_dids_lens.len();
    if base_palette_ids.len() != n {
        return Err(JsValue::from_str(&format!(
            "fetch_entity_surfaces_pixels_batch: base_palette_ids length {} != surface_dids_lens length {}",
            base_palette_ids.len(), n
        )));
    }
    if sub_palettes_triple_counts.len() != n {
        return Err(JsValue::from_str(&format!(
            "fetch_entity_surfaces_pixels_batch: sub_palettes_triple_counts length {} != surface_dids_lens length {}",
            sub_palettes_triple_counts.len(), n
        )));
    }

    // Per-group offset accounting. `dids_offset[i]` is the start of
    // group i's DID slice in `flat_surface_dids`; `sub_offset[i]` is
    // the start of group i's triple slice in `flat_sub_palettes`.
    let mut dids_offset: Vec<usize> = Vec::with_capacity(n);
    let mut sub_offset: Vec<usize> = Vec::with_capacity(n);
    {
        let mut do_acc: usize = 0;
        let mut so_acc: usize = 0;
        for i in 0..n {
            dids_offset.push(do_acc);
            sub_offset.push(so_acc);
            do_acc += surface_dids_lens[i] as usize;
            so_acc += (sub_palettes_triple_counts[i] as usize) * 3;
        }
        if do_acc != flat_surface_dids.len() {
            return Err(JsValue::from_str(&format!(
                "fetch_entity_surfaces_pixels_batch: surface_dids_lens sum {} != flat_surface_dids length {}",
                do_acc, flat_surface_dids.len()
            )));
        }
        if so_acc != flat_sub_palettes.len() {
            return Err(JsValue::from_str(&format!(
                "fetch_entity_surfaces_pixels_batch: sub_palettes_triple_counts*3 sum {} != flat_sub_palettes length {}",
                so_acc, flat_sub_palettes.len()
            )));
        }
    }

    // Decode per-group triples once.
    let mut groups_sp: Vec<Vec<(u32, u8, u8)>> = Vec::with_capacity(n);
    for i in 0..n {
        let off = sub_offset[i];
        let len = (sub_palettes_triple_counts[i] as usize) * 3;
        let slice = &flat_sub_palettes[off..off + len];
        let triples: Vec<(u32, u8, u8)> = slice
            .chunks_exact(3)
            .map(|c| (c[0], c[1] as u8, c[2] as u8))
            .collect();
        groups_sp.push(triples);
    }

    // Early no-op for empty batch.
    if n == 0 {
        return Ok(EntitySurfacesPixelsBatch { payloads: Vec::new() });
    }

    let source = global_source::global_source();

    // Initial seed: union of every referenced record across all
    // groups. Surface → SurfaceTexture → Texture → palette walks are
    // discovered inside the closure on each iteration; misses
    // accumulate into the RecordingSource for the next round.
    let mut initial_set: std::collections::HashSet<u32> = std::collections::HashSet::new();
    for &did in &flat_surface_dids {
        initial_set.insert(did);
    }
    for &p in &base_palette_ids {
        if p != 0 {
            initial_set.insert(p);
        }
    }
    for triples in &groups_sp {
        for (id, _, _) in triples {
            initial_set.insert(*id);
        }
    }
    let initial: Vec<ResourceKey<'_>> = initial_set
        .iter()
        .map(|&id| ResourceKey::new("eor/portal", id))
        .collect();

    // F.37 walk-result dedup. Cache key = "Batch" tag + a stable
    // fingerprint over every input array. Two concurrent callers
    // requesting the same set of groups (in the same order) share
    // one prefetch loop.
    let cache_key = prefetch::WalkCacheKey::new("fetchEntitySurfacesPixelsBatch")
        .with_u32_slice(&surface_dids_lens)
        .with_u32_slice(&flat_surface_dids)
        .with_u32_slice(&base_palette_ids)
        .with_u32_slice(&sub_palettes_triple_counts)
        .with_u32_slice(&flat_sub_palettes);

    // Closure inputs need owned data (move semantics) — clone the
    // per-group slices into a walk-owned Vec the closure can iterate.
    // The walk closure may be invoked multiple times by the prefetch
    // loop (once per discovery round); each invocation reads the
    // current shards state via &dyn ResourceSource.
    let walk_groups: Vec<(Vec<u32>, u32, Vec<(u32, u8, u8)>)> = (0..n)
        .map(|i| {
            let off = dids_offset[i];
            let len = surface_dids_lens[i] as usize;
            let dids = flat_surface_dids[off..off + len].to_vec();
            (dids, base_palette_ids[i], groups_sp[i].clone())
        })
        .collect();

    prefetch::ensure_walk_prefetched_keyed(cache_key, &source, &initial, move |s| {
        // Visit every group in one walk round. RecordingSource
        // accumulates misses across ALL groups; the next prefetch
        // round resolves them in one shared HTTP batch — that's the
        // F.41 round-trip-reduction win.
        for (dids, base_pal, sp) in &walk_groups {
            for &id in dids {
                let _ = fetch_entity_surface_pixels_impl(s, id, *base_pal, sp);
            }
        }
    })
    .await?;

    // Post-prefetch: build one Vec<SurfacePixels> per input group in
    // input order. Each per-DID call is sync — every record is warm.
    let mut payloads: Vec<Option<Vec<SurfacePixels>>> = Vec::with_capacity(n);
    for i in 0..n {
        let off = dids_offset[i];
        let len = surface_dids_lens[i] as usize;
        let base_pal = base_palette_ids[i];
        let sp = &groups_sp[i];
        let mut out: Vec<SurfacePixels> = Vec::with_capacity(len);
        for j in 0..len {
            let did = flat_surface_dids[off + j];
            out.push(fetch_entity_surface_pixels_impl(
                source.as_ref(),
                did,
                base_pal,
                sp,
            ));
        }
        payloads.push(Some(out));
    }

    Ok(EntitySurfacesPixelsBatch { payloads })
}

/// F.41 (2026-05-15) — companion helper for the
/// [`fetch_entity_surfaces_pixels_batch`] integration in
/// `scene3d/spawns.js`. Walks every setup_id and returns the union of
/// surface DIDs referenced by each setup's per-part GfxObjs, flat-
/// packed parallel to the input.
///
/// **Use case.** spawns.js doesn't have surface DIDs at dispatch time
/// (those are extracted from the entity rig's wasmMesh post-spawn).
/// To call the F.41 batch BEFORE dispatch, spawns.js needs to know
/// surface DIDs per entity. This helper extracts them from the warm
/// wasm-side shards cache (post-F.40 pre-warm). The per-setup walk
/// is sync-fast (no HTTP) because F.40's `getBatch` has already
/// populated the `shards` for every transitive record.
///
/// **Return shape.** Flat-packed: `(flat_surface_dids,
/// surface_dids_lens)` where `surface_dids_lens[i]` is the count of
/// DIDs for `setup_ids[i]`, and `flat_surface_dids[offsets[i]
/// ..offsets[i]+lens[i]]` is that setup's DID slice. Duplicate DIDs
/// WITHIN a setup are preserved (the caller can dedup if needed —
/// the F.41 batch's prefetch union handles cross-setup dedup
/// internally).
///
/// **Setup variants.**
///   - Raw GfxObj (0x01 prefix): walks the GfxObj's `surfaces` field.
///   - SetupModel (0x02 prefix): walks every part GfxObj's `surfaces`.
///   - Unknown / failed load: zero DIDs for that index.
///
/// One prefetch loop covers the union of setup records + transitive
/// part records — re-using F.40's warm shards means this is typically
/// a no-op prefetch (already in cache). The caller is expected to
/// invoke this AFTER `getBatch(setupIds, ...)` has completed.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = collectSurfaceDidsForSetups)]
pub async fn collect_surface_dids_for_setups(
    setup_ids: Vec<u32>,
) -> Result<SurfaceDidsForSetups, JsValue> {
    use holtburger_dat::file_type::{GfxObj, SetupModel};
    use holtburger_dat::{ResourceKey, ResourceSource};

    if setup_ids.is_empty() {
        return Ok(SurfaceDidsForSetups {
            flat_surface_dids: Vec::new(),
            surface_dids_lens: Vec::new(),
        });
    }

    let source = global_source::global_source();
    let initial: Vec<ResourceKey<'_>> = setup_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    let setups_for_walk = setup_ids.clone();
    let cache_key = prefetch::WalkCacheKey::new("collectSurfaceDidsForSetups")
        .with_u32_slice(&setup_ids);
    prefetch::ensure_walk_prefetched_keyed(cache_key, &source, &initial, move |s| {
        // Touch each setup + every part GfxObj to surface any cold
        // records into the prefetch round. The F.37 walk-result dedup
        // catches concurrent same-setup-set callers; post-F.40 the
        // setups are already warm so this is a noop pretty much
        // always.
        for &setup_id in &setups_for_walk {
            if (setup_id >> 24) as u8 != 0x02 {
                // Raw GfxObj — single record.
                let _ = s.get_file_by_key(ResourceKey::new("eor/portal", setup_id));
                continue;
            }
            // SetupModel — touch the setup, then each part.
            if let Ok(setup_bytes) =
                s.get_file_by_key(ResourceKey::new("eor/portal", setup_id))
            {
                if let Ok(setup) =
                    SetupModel::unpack(&mut std::io::Cursor::new(&setup_bytes))
                {
                    for &part_id in &setup.parts {
                        let _ = s.get_file_by_key(ResourceKey::new("eor/portal", part_id));
                    }
                }
            }
        }
    })
    .await?;

    let mut flat: Vec<u32> = Vec::new();
    let mut lens: Vec<u32> = Vec::with_capacity(setup_ids.len());

    for &setup_id in &setup_ids {
        let start = flat.len();
        if (setup_id >> 24) as u8 != 0x02 {
            // Raw GfxObj (0x01 prefix) — walk surfaces directly.
            if let Ok(bytes) = source
                .as_ref()
                .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
            {
                if let Ok(gfx) =
                    GfxObj::unpack(&mut std::io::Cursor::new(&bytes))
                {
                    for &did in &gfx.surfaces {
                        flat.push(did);
                    }
                }
            }
        } else if let Ok(setup_bytes) = source
            .as_ref()
            .get_file_by_key(ResourceKey::new("eor/portal", setup_id))
        {
            if let Ok(setup) =
                SetupModel::unpack(&mut std::io::Cursor::new(&setup_bytes))
            {
                for &part_id in &setup.parts {
                    if let Ok(part_bytes) = source
                        .as_ref()
                        .get_file_by_key(ResourceKey::new("eor/portal", part_id))
                    {
                        if let Ok(gfx) = GfxObj::unpack(
                            &mut std::io::Cursor::new(&part_bytes),
                        ) {
                            for &did in &gfx.surfaces {
                                flat.push(did);
                            }
                        }
                    }
                }
            }
        }
        // Sort + dedup this setup's slice in-place. Two parts sharing
        // a surface (common with reused door GfxObjs etc.) collapse
        // to one entry. Cross-setup dedup is the F.41 batch's
        // prefetch-union job.
        flat[start..].sort_unstable();
        // Manual dedup since `Vec::dedup` doesn't operate on slices.
        let mut write = start;
        let mut prev: Option<u32> = None;
        for read in start..flat.len() {
            let v = flat[read];
            if prev != Some(v) {
                flat[write] = v;
                write += 1;
                prev = Some(v);
            }
        }
        flat.truncate(write);
        lens.push((flat.len() - start) as u32);
    }

    Ok(SurfaceDidsForSetups {
        flat_surface_dids: flat,
        surface_dids_lens: lens,
    })
}

/// F.41 (2026-05-15) — return type for [`collect_surface_dids_for_setups`].
/// Flat-packed `(flat_surface_dids, surface_dids_lens)` parallel to the
/// input setup_ids. `payload.surface_dids_lens[i]` is the count of
/// DIDs for setup i; the slice is
/// `flat_surface_dids[offsets[i]..offsets[i]+lens[i]]` where
/// `offsets[i] = sum(lens[0..i])`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct SurfaceDidsForSetups {
    flat_surface_dids: Vec<u32>,
    surface_dids_lens: Vec<u32>,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SurfaceDidsForSetups {
    /// Concatenated surface DIDs across all setups. Deduplicated
    /// per-setup; cross-setup dedup happens inside
    /// [`fetch_entity_surfaces_pixels_batch`].
    #[wasm_bindgen(getter, js_name = flatSurfaceDids)]
    pub fn flat_surface_dids(&self) -> Vec<u32> {
        self.flat_surface_dids.clone()
    }
    /// Per-setup count of DIDs. Parallel to input setup_ids order.
    #[wasm_bindgen(getter, js_name = surfaceDidsLens)]
    pub fn surface_dids_lens(&self) -> Vec<u32> {
        self.surface_dids_lens.clone()
    }
}

/// Phase 3 step 6: walk a model's GfxObj/SetupModel chain, triangulate,
/// and return a flat-buffer mesh ready for in-browser rasterization.
/// One HTTP fetch (the HBA bundle); per-id walks are in-memory.
///
/// On any failure the rejected Promise carries a tagged error string
/// — caller treats unknown models the same way the existing atlas
/// path does (fall back to the dot).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_model_mesh(model_id: u32) -> Result<ModelMesh, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", model_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        let _ = triangulate_model(s, model_id);
    })
    .await?;
    let tris = triangulate_model(source.as_ref(), model_id)
        .ok_or_else(|| JsValue::from_str(&format!("triangulate_model 0x{model_id:08X}: failed")))?;
    let mut mesh = pack_model_mesh(tris);
    // Follow-on #5 — resolve LOD chain after pack. 0 = no degraded
    // variant; JS uses plain Mesh in that case.
    mesh.did_degrade = resolve_did_degrade(source.as_ref(), model_id);
    Ok(mesh)
}

/// Follow-on #5 (LOD) — batch query for per-model `did_degrade` chain
/// entries, WITHOUT triangulating. The buildings path
/// (`fetchBuildingPlacement`) doesn't go through `fetch_model_meshes`
/// so it can't read `ModelMesh.didDegrade`; this thin export lets it
/// look up the chain via a single byte-level GfxObj parse.
///
/// Returns one u32 per input model id; 0 = no degrade chain
/// (`HAS_DID_DEGRADE` flag unset OR model not parseable). Holtburg
/// buildings are mostly raw `0x01` GfxObjs and most have no degrade
/// entry — the typical return is all zeros, which the JS caller
/// handles by falling back to plain `THREE.Mesh` instead of `THREE.LOD`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchModelDidDegrades)]
pub async fn fetch_model_did_degrades(
    model_ids: Vec<u32>,
) -> Result<Vec<u32>, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial: Vec<ResourceKey<'_>> = model_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    let ids_for_walk = model_ids.clone();
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        for &id in &ids_for_walk {
            let _ = resolve_did_degrade(s, id);
        }
    })
    .await?;
    let mut out = Vec::with_capacity(model_ids.len());
    for &id in &model_ids {
        out.push(resolve_did_degrade(source.as_ref(), id));
    }
    Ok(out)
}

/// Batch form: triangulate many models in one call. Returns a vector
/// of [`ModelMesh`] in input order. On any per-id failure we push an
/// empty mesh (tri_count == 0) rather than failing the whole batch —
/// the JS caller checks for empty and falls back to atlas / dot for
/// those.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub async fn fetch_model_meshes(model_ids: Vec<u32>) -> Result<Vec<ModelMesh>, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial: Vec<ResourceKey<'_>> = model_ids
        .iter()
        .map(|id| ResourceKey::new("eor/portal", *id))
        .collect();
    let ids_for_walk = model_ids.clone();
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        for &id in &ids_for_walk {
            let _ = triangulate_model(s, id);
        }
    })
    .await?;
    let mut out = Vec::with_capacity(model_ids.len());
    for &id in &model_ids {
        let tris = triangulate_model(source.as_ref(), id).unwrap_or_default();
        let mut mesh = pack_model_mesh(tris);
        // Follow-on #5 — resolve LOD chain after pack. 0 = no degraded
        // variant; JS uses plain Mesh in that case.
        mesh.did_degrade = resolve_did_degrade(source.as_ref(), id);
        out.push(mesh);
    }
    Ok(out)
}

// ────────────────────────────────────────────────────────────────────
//  Phase 6 step A — per-part building mesh export
// ────────────────────────────────────────────────────────────────────
//
// The fused-output path (`fetch_model_mesh` / `fetch_model_meshes`)
// walks every Setup part and packs them into a single `ModelMesh` per
// model_id — fine for static props and the existing single-sprite
// rendering, but Phase E (door rotation around hinge frames) needs
// each part addressable on its own. `BuildingPlacement` mirrors the
// `EntityCycleSet` move-semantics pattern (`take_*` methods one-shot
// the inner Vecs across the wasm boundary without cloning) and slots
// in alongside `fetch_landblock_objects`'s `is_building` flag: the JS
// builder calls `fetch_building_placement` once per unique building
// model_id, then instantiates a `PIXI.Container` of N child sprites
// per placement.

/// Phase 6 step A: per-part-aware return type for building setups —
/// sibling to [`ObjectPlacement`] (which carries placement coords for
/// the JS bake). `parts.len()` is the Setup's part count; each
/// entry's vec position is the `part_index` JS uses to address the
/// part later (Phase E door rotations target a specific index, not a
/// model-wide id). Naming follows the smoke contract in
/// `smoke_test.cjs` Phase 6 step A scaffolding.
///
/// Empty `parts` = the Setup failed to load. A part with
/// `triCount == 0` is preserved at its index so part_index stays
/// stable across the boundary even if a leaf GfxObj fetch failed.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct BuildingPlacement {
    setup_id: u32,
    parts: Vec<ModelMesh>,
    hinge_frames: Vec<HingeFrame>,
}

/// Phase 6 step E: per-part hinge transform — the part's local origin
/// + orientation in the SetupModel's `placement_frames[0]` slot. Door
/// rotation is applied by the JS-side renderer around this frame:
/// closed = identity, open = ~90° around the hinge's local Z axis.
/// Non-door parts ship the frame too so JS doesn't need a special
/// case (door identification flows through the entity's
/// `ObjectDescriptionFlag::DOOR` bit, not a per-part marker on the
/// building placement).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
#[derive(Debug, Clone, Copy)]
pub struct HingeFrame {
    x: f32,
    y: f32,
    z: f32,
    qw: f32,
    qx: f32,
    qy: f32,
    qz: f32,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl HingeFrame {
    #[wasm_bindgen(getter)]
    pub fn x(&self) -> f32 { self.x }
    #[wasm_bindgen(getter)]
    pub fn y(&self) -> f32 { self.y }
    #[wasm_bindgen(getter)]
    pub fn z(&self) -> f32 { self.z }
    #[wasm_bindgen(getter)]
    pub fn qw(&self) -> f32 { self.qw }
    #[wasm_bindgen(getter)]
    pub fn qx(&self) -> f32 { self.qx }
    #[wasm_bindgen(getter)]
    pub fn qy(&self) -> f32 { self.qy }
    #[wasm_bindgen(getter)]
    pub fn qz(&self) -> f32 { self.qz }
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl BuildingPlacement {
    /// SetupModel DID this bake corresponds to.
    #[wasm_bindgen(getter, js_name = setupId)]
    pub fn setup_id(&self) -> u32 {
        self.setup_id
    }

    /// Number of parts in the SetupModel — equals the length of the
    /// `Vec<ModelMesh>` `take_part_meshes` returns.
    #[wasm_bindgen(getter, js_name = partCount)]
    pub fn part_count(&self) -> u32 {
        self.parts.len() as u32
    }

    /// Move the per-part meshes out of the bundle into a JS-owned
    /// array. Position in the returned Vec is the `part_index`. One-
    /// shot — second call returns an empty Vec.
    #[wasm_bindgen(js_name = takePartMeshes)]
    pub fn take_part_meshes(&mut self) -> Vec<ModelMesh> {
        std::mem::take(&mut self.parts)
    }

    /// Phase 6 step E: drain the per-part hinge frames. One per
    /// `parts[]` slot in the same order. Computed from
    /// `setup.placement_frames[0]` (or the first available placement)
    /// so each part carries its local origin + orientation in the
    /// building's coord system. JS uses these as door pivot points
    /// when applying the open-rotation transform; non-door parts
    /// receive an identity frame they never use.
    #[wasm_bindgen(js_name = takePartHingeFrames)]
    pub fn take_part_hinge_frames(&mut self) -> Vec<HingeFrame> {
        std::mem::take(&mut self.hinge_frames)
    }
}

/// Phase 6 step A: per-part variant of [`fetch_model_mesh`]. Walks a
/// SetupModel and returns one `ModelMesh` per part. Raw `0x01` GfxObj
/// inputs (no skeleton / single-part) return a single-element Vec so
/// the JS caller can treat all building model_ids uniformly.
///
/// JS flow: `fetch_landblock_objects` → for every placement with
/// `isBuilding == true`, call `fetchBuildingPlacement(modelId)` once
/// per unique model_id (cache the bake), then instantiate a per-
/// placement `PIXI.Container` whose children are sprites referencing
/// the per-part RenderTextures, tagged `{ buildingId, partIndex }`.
///
/// On any part-load failure, the slot is preserved as an empty mesh
/// (`triCount == 0`) so the `part_index` stays stable for Phase E
/// door-state lookups.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchBuildingPlacement)]
pub async fn fetch_building_placement(model_id: u32) -> Result<BuildingPlacement, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", model_id)];
    // F.37 walk-result dedup. Two concurrent
    // `fetchBuildingPlacement(0x02000123)` calls (e.g. when two
    // adjacent LBs share a model_id and load near-simultaneously)
    // now share a single prefetch loop instead of each spinning up
    // its own RecordingSource + re-walking the SetupModel.
    let cache_key = prefetch::WalkCacheKey::new("fetchBuildingPlacement")
        .with_u32(model_id);
    prefetch::ensure_walk_prefetched_keyed(cache_key, &source, &initial, move |s| {
        let _ = triangulate_model_per_part_buckets(s, model_id);
    })
    .await?;
    let parts_tris = triangulate_model_per_part_buckets(source.as_ref(), model_id)
        .ok_or_else(|| {
            JsValue::from_str(&format!("fetchBuildingPlacement 0x{model_id:08X}: failed"))
        })?;
    let part_count = parts_tris.len();
    let parts: Vec<ModelMesh> = parts_tris.into_iter().map(pack_model_mesh).collect();
    let hinge_frames = compute_hinge_frames(source.as_ref(), model_id, part_count);
    Ok(BuildingPlacement {
        setup_id: model_id,
        parts,
        hinge_frames,
    })
}

/// Phase 6 step E: read each part's local hinge frame (origin +
/// orientation) from the SetupModel's `placement_frames[0]` slot.
/// `placement_frames` is keyed by an integer placement-id (0 = Default,
/// 1 = Resting, etc.); we use the same `0 → 1 → first` fallback chain
/// `walk_setup_parts` uses so the frame matches the static bake. Raw
/// `0x01` GfxObj inputs return a single identity frame so JS can treat
/// all building model_ids uniformly.
#[cfg(target_arch = "wasm32")]
fn compute_hinge_frames<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
    expected_parts: usize,
) -> Vec<HingeFrame> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    let identity = HingeFrame {
        x: 0.0, y: 0.0, z: 0.0,
        qw: 1.0, qx: 0.0, qy: 0.0, qz: 0.0,
    };
    if (setup_id >> 24) as u8 != 0x02 {
        return vec![identity; expected_parts.max(1)];
    }
    let bytes = match source.get_file_by_key(ResourceKey::new("eor/portal", setup_id)) {
        Ok(b) => b,
        Err(_) => return vec![identity; expected_parts],
    };
    let setup = match SetupModel::unpack(&mut std::io::Cursor::new(&bytes)) {
        Ok(s) => s,
        Err(_) => return vec![identity; expected_parts],
    };
    let part_count = setup.parts.len().max(expected_parts);
    let placement = setup
        .placement_frames
        .get(&0)
        .or_else(|| setup.placement_frames.get(&1))
        .or_else(|| setup.placement_frames.values().next());
    let mut hinges = vec![identity; part_count];
    if let Some(p) = placement {
        for (i, slot) in hinges.iter_mut().enumerate() {
            if let Some(frame) = p.anim_frame.frames.get(i) {
                *slot = HingeFrame {
                    x: frame.origin.x,
                    y: frame.origin.y,
                    z: frame.origin.z,
                    qw: frame.orientation.w,
                    qx: frame.orientation.x,
                    qy: frame.orientation.y,
                    qz: frame.orientation.z,
                };
            }
        }
    }
    hinges
}

// ============================================================
// 3D port follow-on #1: per-SetupModel point/spot lights.
//
// Mirrors [`fetch_building_placement`] for the
// `SetupModel.lights: HashMap<i32, LightInfo>` table (defined at
// `crates/holtburger-dat/src/file_type/setup_model.rs:29-35`). One
// `SetupLight` per `LightInfo` carrying origin + ARGB-extracted color
// + intensity + falloff + cone_angle. The JS-side
// `attachSetupModelLights` walks every unique setup id used by
// buildings/statics/entities/cells, calls this export, and instantiates
// `THREE.PointLight` (cone_angle == 0) or `THREE.SpotLight`
// (cone_angle > 0) as children of the per-part `Object3D` so the light
// follows the model's transform tree.
//
// Empty `Vec` = "this Setup has no light descriptors" — typical for
// retail Holtburg buildings, which are mostly raw `0x01` GfxObjs with
// no Setup at all (`setup_id == model_id` in that case and the wasm
// returns empty). Returning Vec rather than failing keeps the JS path
// uniform.
// ============================================================

/// Phase 7.6.1 (follow-on #1): one per-part light descriptor drained
/// from `SetupModel.lights`. `part_index` is the HashMap key —
/// identifies which Setup part the light is rigidly attached to.
/// `color_r/g/b` are normalized [0,1] components extracted from the
/// ARGB `color: u32` in the DAT (`R = (color >> 16) & 0xFF`).
/// `intensity / falloff / cone_angle` are passed through verbatim;
/// `cone_angle == 0.0` → PointLight, `> 0.0` → SpotLight.
///
/// B10b (`likely:spotlight-target`): `qx/qy/qz/qw` carry the LightInfo
/// `viewer_space_location.orientation` quaternion (AC wire order is
/// w,x,y,z; surfaced as the individual components so the JS side can
/// reorder to three.js x,y,z,w). Previously the bridge DROPPED the
/// orientation, so SpotLights had no aim direction. Identity quat
/// `(0,0,0,1)` for PointLights / lights with no authored orientation.
#[cfg(any(target_arch = "wasm32", test))]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
#[derive(Debug, Clone, Copy)]
pub struct SetupLight {
    pub(crate) part_index: u32,
    pub(crate) x: f32,
    pub(crate) y: f32,
    pub(crate) z: f32,
    pub(crate) color_r: f32,
    pub(crate) color_g: f32,
    pub(crate) color_b: f32,
    pub(crate) intensity: f32,
    pub(crate) falloff: f32,
    pub(crate) cone_angle: f32,
    pub(crate) qx: f32,
    pub(crate) qy: f32,
    pub(crate) qz: f32,
    pub(crate) qw: f32,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SetupLight {
    #[wasm_bindgen(getter, js_name = partIndex)]
    pub fn part_index(&self) -> u32 { self.part_index }
    #[wasm_bindgen(getter)]
    pub fn x(&self) -> f32 { self.x }
    #[wasm_bindgen(getter)]
    pub fn y(&self) -> f32 { self.y }
    #[wasm_bindgen(getter)]
    pub fn z(&self) -> f32 { self.z }
    #[wasm_bindgen(getter, js_name = colorR)]
    pub fn color_r(&self) -> f32 { self.color_r }
    #[wasm_bindgen(getter, js_name = colorG)]
    pub fn color_g(&self) -> f32 { self.color_g }
    #[wasm_bindgen(getter, js_name = colorB)]
    pub fn color_b(&self) -> f32 { self.color_b }
    #[wasm_bindgen(getter)]
    pub fn intensity(&self) -> f32 { self.intensity }
    #[wasm_bindgen(getter)]
    pub fn falloff(&self) -> f32 { self.falloff }
    #[wasm_bindgen(getter, js_name = coneAngle)]
    pub fn cone_angle(&self) -> f32 { self.cone_angle }
    // B10b (likely:spotlight-target): LightInfo orientation quaternion
    // (AC wire order w,x,y,z) — surfaced per-component so the JS
    // SpotLight branch can aim the cone via SpotLight.target.
    #[wasm_bindgen(getter)]
    pub fn qx(&self) -> f32 { self.qx }
    #[wasm_bindgen(getter)]
    pub fn qy(&self) -> f32 { self.qy }
    #[wasm_bindgen(getter)]
    pub fn qz(&self) -> f32 { self.qz }
    #[wasm_bindgen(getter)]
    pub fn qw(&self) -> f32 { self.qw }
}

/// Phase 7.6.1 (follow-on #1): per-SetupModel light bundle returned
/// from [`fetch_setup_model_lights`]. Mirrors [`BuildingPlacement`]:
/// one-shot `take_lights()` drain so JS lifts the Vec across the wasm
/// boundary without cloning. `part_count` is the LIGHT COUNT (not the
/// Setup's part count) — naming follows the task spec.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
pub struct SetupModelLights {
    setup_id: u32,
    lights: Vec<SetupLight>,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SetupModelLights {
    #[wasm_bindgen(getter, js_name = setupId)]
    pub fn setup_id(&self) -> u32 { self.setup_id }

    /// Light count (NOT the Setup's part count — naming per the task
    /// spec). Equals `take_lights().len()` on the very first call.
    #[wasm_bindgen(getter, js_name = partCount)]
    pub fn part_count(&self) -> u32 { self.lights.len() as u32 }

    /// One-shot drain. Second call returns an empty Vec — JS callers
    /// hold the resulting array; the wasm side stops owning it.
    #[wasm_bindgen(js_name = takeLights)]
    pub fn take_lights(&mut self) -> Vec<SetupLight> {
        std::mem::take(&mut self.lights)
    }
}

/// Phase 7.6.1 (follow-on #1) — new wasm export. Walks a SetupModel
/// and drains its `lights: HashMap<i32, LightInfo>` table into a flat
/// Vec of [`SetupLight`] descriptors. JS calls this once per unique
/// `setup_id` used by buildings/statics/entities/cells.
///
/// Raw `0x01` GfxObj inputs (no Setup) return an empty Vec — JS treats
/// this as "no lights for this model".
///
/// Failure modes: the DAT fetch / SetupModel parse failures both
/// resolve to an empty Vec (caller can tell from `part_count == 0`).
/// Promise rejection is reserved for prefetch errors only (network /
/// IO), mirroring the [`fetch_building_placement`] contract.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = fetchSetupModelLights)]
pub async fn fetch_setup_model_lights(setup_id: u32) -> Result<SetupModelLights, JsValue> {
    use holtburger_dat::ResourceKey;
    let source = global_source::global_source();
    let initial = [ResourceKey::new("eor/portal", setup_id)];
    prefetch::ensure_walk_prefetched(&source, &initial, |s| {
        // Touch the resource so the prefetch walker is happy. The
        // unpacked SetupModel is consumed below — this just primes
        // the cache.
        let _ = s.get_file_by_key(ResourceKey::new("eor/portal", setup_id));
    })
    .await?;
    let lights = collect_setup_model_lights(source.as_ref(), setup_id);
    Ok(SetupModelLights {
        setup_id,
        lights,
    })
}

/// Phase 7.6.1 (follow-on #1): pure helper drained from a
/// `ResourceSource`. Empty Vec for `0x01` GfxObjs and for any parse
/// failure, so JS uniformly treats "no lights" the same way regardless
/// of the underlying cause.
///
/// AC's `LightInfo.color` is an ARGB-packed u32:
///   R = (color >> 16) & 0xFF
///   G = (color >>  8) & 0xFF
///   B = (color >>  0) & 0xFF
///   A = (color >> 24) & 0xFF  // the alpha byte; ignored — three.js
///                              // PointLight.color is RGB only.
///
/// HashMap ordering is non-deterministic in Rust; we sort by key so
/// the returned Vec is stable across runs (tests can assert specific
/// indices). The key (the HashMap's i32) IS the Setup part index the
/// light is attached to — preserved on `SetupLight.part_index`.
#[cfg(any(target_arch = "wasm32", test))]
fn collect_setup_model_lights<S: holtburger_dat::ResourceSource + ?Sized>(
    source: &S,
    setup_id: u32,
) -> Vec<SetupLight> {
    use holtburger_dat::file_type::SetupModel;
    use holtburger_dat::ResourceKey;
    // 0x01 = raw GfxObj — no Setup; no lights table to walk.
    if (setup_id >> 24) as u8 != 0x02 {
        return Vec::new();
    }
    let Ok(bytes) = source.get_file_by_key(ResourceKey::new("eor/portal", setup_id)) else {
        return Vec::new();
    };
    let Ok(setup) = SetupModel::unpack(&mut std::io::Cursor::new(&bytes)) else {
        return Vec::new();
    };
    if setup.lights.is_empty() {
        return Vec::new();
    }
    // Stable order — sort by HashMap key (the part index).
    let mut entries: Vec<(i32, &holtburger_dat::file_type::setup_model::LightInfo)> =
        setup.lights.iter().map(|(k, v)| (*k, v)).collect();
    entries.sort_by_key(|(k, _)| *k);
    let mut out = Vec::with_capacity(entries.len());
    for (part_index, info) in entries {
        // Negative HashMap keys are theoretically possible in the
        // DAT format but in practice all live retail entries are >= 0.
        // Cast to u32 with saturation at 0 — JS reads partIndex as a
        // u32 getter (`.part_index() -> u32`).
        let pi = if part_index < 0 { 0u32 } else { part_index as u32 };
        let argb = info.color;
        let r = ((argb >> 16) & 0xFF) as f32 / 255.0;
        let g = ((argb >>  8) & 0xFF) as f32 / 255.0;
        let b = ((argb      ) & 0xFF) as f32 / 255.0;
        // B10b (likely:spotlight-target): carry the part-LOCAL
        // orientation quaternion (AC wire order w,x,y,z) so the JS
        // SpotLight branch can aim its cone. PointLights ignore it.
        let q = &info.viewer_space_location.orientation;
        out.push(SetupLight {
            part_index: pi,
            x: info.viewer_space_location.origin.x,
            y: info.viewer_space_location.origin.y,
            z: info.viewer_space_location.origin.z,
            color_r: r,
            color_g: g,
            color_b: b,
            intensity: info.intensity,
            falloff: info.falloff,
            cone_angle: info.cone_angle,
            qx: q.x,
            qy: q.y,
            qz: q.z,
            qw: q.w,
        });
    }
    out
}

// === Render-completeness audit (2026-05-29) — wielded-item holding locations ===
//
// AC attaches a wielded child object (weapon / shield / bow) to its wielder by
// hanging the child off one of the wielder SetupModel's `HoldingLocations`
// entries, keyed by the `ParentEvent.location` value (RightHand=1, LeftHand=2,
// Shield=3, …). Each entry is a `LocationType { part_id, frame }`: the parent
// body part the child mounts on, plus the part-LOCAL frame (origin + quat) the
// child is placed at. Retail `CSetup::GetHoldingLocation` (acclient.c:316746)
// → `CHILDLIST::add_child(obj, holdingLocation.Frame, holdingLocation.PartId)`.
// ACE mirror: `Setup.GetHoldingLocation` (Setup.cs:96) + `PhysicsObj.add_child`
// (PhysicsObj.cs:1922). The DAT loader already parses this dict
// (`setup_model.rs:357`) but every prior wasm consumer discarded it
// (`holding_locations: HashMap::new()`). This getter surfaces it so the JS rig
// can parent the child's Group under the wielder's `part_${part_id}` node at
// the holding frame — the child then tracks the part's animation for free.

/// One holding-location entry drained from a SetupModel's `holding_locations`
/// dict. `location_key` is the `ParentEvent.location` value that selects it.
/// `part_id` is the wielder part the child mounts on. `(ox,oy,oz)` +
/// `(qw,qx,qy,qz)` is the part-LOCAL frame (AC wire quat order w,x,y,z — the JS
/// side reorders to three.js x,y,z,w at apply, same as the rest-pose path).
#[cfg(any(target_arch = "wasm32", test))]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
#[derive(Debug, Clone, Copy)]
pub struct HoldingLocation {
    pub(crate) location_key: i32,
    pub(crate) part_id: i32,
    pub(crate) ox: f32,
    pub(crate) oy: f32,
    pub(crate) oz: f32,
    pub(crate) qw: f32,
    pub(crate) qx: f32,
    pub(crate) qy: f32,
    pub(crate) qz: f32,
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl HoldingLocation {
    #[wasm_bindgen(getter, js_name = locationKey)]
    pub fn location_key(&self) -> i32 { self.location_key }
    #[wasm_bindgen(getter, js_name = partId)]
    pub fn part_id(&self) -> i32 { self.part_id }
    #[wasm_bindgen(getter)] pub fn ox(&self) -> f32 { self.ox }
    #[wasm_bindgen(getter)] pub fn oy(&self) -> f32 { self.oy }
    #[wasm_bindgen(getter)] pub fn oz(&self) -> f32 { self.oz }
    #[wasm_bindgen(getter)] pub fn qw(&self) -> f32 { self.qw }
    #[wasm_bindgen(getter)] pub fn qx(&self) -> f32 { self.qx }
    #[wasm_bindgen(getter)] pub fn qy(&self) -> f32 { self.qy }
    #[wasm_bindgen(getter)] pub fn qz(&self) -> f32 { self.qz }
}

/// Per-SetupModel holding-location bundle returned from
/// [`fetch_setup_holding_locations`]. Mirrors [`SetupModelLights`] /
/// [`SetupPartSortCenters`]: a one-shot `take_locations()` drain so JS lifts
/// the Vec across the wasm boundary without cloning, then caches per setup id.
