/// Wave-F3 (2026-05-27): convert a wire `AllegianceInfoResponseEventData`
/// EX-05 (2026-06-05) — build a JSON-shaped AppraisalSnapshot of an
/// `Entity`'s post-IdentifyObject state. Used by the recv loop's
/// `WorldEvent::EntityIdentified` arm to populate `latest_appraisals`,
/// which JS consumes via `getObjectAppraisal(guid)` — returning the
/// raw JSON string for `JSON.parse` on the JS side.
///
/// Shape (all keys camelCase to match JS convention):
/// ```text
/// {
///   guid, properties: WorldObjectProperties,
///   armorProfile?, creatureProfile?, weaponProfile?, hookProfile?,
///   armorLevels?,
///   spellBook: number[],
///   armorHighlight?, armorColor?,
///   weaponHighlight?, weaponColor?,
///   resistHighlight?, resistColor?,
/// }
/// ```
///
/// Failure: returns `"null"` if serde_json::to_string fails (shouldn't
/// happen since every field derives Serialize cleanly).
#[cfg(target_arch = "wasm32")]
fn build_appraisal_snapshot(
    entity: &holtburger_world::entity::Entity,
    identify_meta: Option<(bool, u32)>,
) -> String {
    let (identify_success, identify_flags) = identify_meta.unwrap_or((true, 0));
    let v = serde_json::json!({
        "guid": u32::from(entity.guid),
        // HUD rec #53: surface the IdentifyResponse-level metadata so JS
        // can show "Insufficient identification skill" when success=false
        // and only render the sections covered by the wire flags
        // (CREATURE_PROFILE=0x0100, ARMOR_PROFILE=0x0080,
        // WEAPON_PROFILE=0x0020, etc.). `identify_meta=None` defaults to
        // success=true with empty flags — that's the path for snapshots
        // built outside of an Identify round-trip (e.g. ViewContents).
        "identifySuccess": identify_success,
        "identifyFlags": identify_flags,
        "properties": entity.properties,
        "armorProfile": entity.armor_profile,
        "creatureProfile": entity.creature_profile,
        "weaponProfile": entity.weapon_profile,
        "hookProfile": entity.hook_profile,
        "armorLevels": entity.armor_levels,
        "spellBook": entity.spell_book,
        "armorHighlight": entity.armor_highlight,
        "armorColor": entity.armor_color,
        "weaponHighlight": entity.weapon_highlight,
        "weaponColor": entity.weapon_color,
        "resistHighlight": entity.resist_highlight,
        "resistColor": entity.resist_color,
    });
    serde_json::to_string(&v).unwrap_or_else(|_| "null".to_string())
}

/// to its JS-facing snapshot. Walks the records list flagging the
/// monarch + remaining members. The monarch is the root of the queried
/// tree; everyone in `records` is a vassal/sub-vassal (we don't try to
/// pick out a per-target "patron/myself" split since the response is
/// about a queried character, not the local player).
#[cfg(target_arch = "wasm32")]
fn build_allegiance_info_snapshot_js(
    data: &holtburger_protocol::messages::AllegianceInfoResponseEventData,
) -> AllegianceInfoSnapshotJs {
    use holtburger_protocol::messages::{
        AllegianceDataEntry, AllegianceIndexFlags as PIdx,
    };

    fn to_member(e: &AllegianceDataEntry) -> AllegianceMember {
        let logged_in = e.bitfield.0 & PIdx::LOGGED_IN != 0;
        AllegianceMember {
            guid: e.character_id.0,
            name: e.name.clone(),
            rank: e.rank as u32,
            gender: e.gender as u32,
            heritage_group: e.heritage_group as u32,
            level: e.level,
            loyalty: e.loyalty as u32,
            leadership: e.leadership as u32,
            cp_cached: e.cp_cached,
            cp_tithed: e.cp_tithed,
            logged_in,
        }
    }

    let monarch = data.monarch.as_ref().map(to_member);
    let vassals: Vec<AllegianceMember> =
        data.records.iter().map(|(_parent, e)| to_member(e)).collect();

    AllegianceInfoSnapshotJs {
        target_id: data.target_id.0,
        name: data.allegiance_name.clone(),
        is_locked: data.is_locked,
        motd: data.motd.clone(),
        motd_set_by: data.motd_set_by.clone(),
        total_members: data.total_members,
        total_vassals: data.total_vassals,
        monarch,
        vassals,
    }
}

