// Wave F follow-on cluster (2026-05-27)
//
// Three deferred items from Waves F.1, F.3, F.5:
//
//   1. `getSpellComponentRecord(component_id)` — on-demand DAT load of
//      `SpellComponentsTable` (0x0E00000F). Cached in a thread-local
//      after first call. Doesn't touch `WorldBootstrap`.
//
//   2. `getSpellCategoryName(category_id)` — pure synchronous lookup
//      backed by `holtburger_protocol::messages::magic::spell_category_db`
//      (729-entry static binary-searched table).
//
//   3. `getContractRecord(contract_id)` — on-demand DAT load of
//      `ContractTable` (0x0E00001D). Cached in a thread-local after
//      first call. Doesn't touch `WorldBootstrap`.
//
//   4. `SessionHandle::requestAllegianceInfo(target_name)` — C2S
//      `GameAction::AllegianceInfoRequest` (0x027B). Sends through the
//      same recv-loop dispatch as `AbandonContract`. Server replies
//      with an `AllegianceInfoResponse` (0x027C) that the existing
//      allegiance arm folds into `latest_allegiance`.
// ─────────────────────────────────────────────────────────────────

/// Wave F.1 follow-on (2026-05-27): synchronous SpellCategory name
/// lookup. Returns the camelCase enum name (e.g.
/// "StrengthRaising" for category 1) or `null` if the id isn't in
/// `ACE.Entity.Enum.SpellCategory` (gaps at 622, 700..703).
///
/// Pure const-data lookup — no IO. Useful for spellbook tooltips
/// ("stacks with Strength X") and stacking-conflict UI.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = getSpellCategoryName)]
pub fn get_spell_category_name(category_id: u32) -> Option<String> {
    holtburger_protocol::messages::magic::spell_category_db::name(category_id)
        .map(|s| s.to_string())
}

/// Thread-local cache for the SpellComponentsTable. The table is small
/// (~30 KB), so we read it once and keep it in-memory for the page's
/// lifetime. Single-threaded wasm32 → `RefCell` is sufficient.
#[cfg(target_arch = "wasm32")]
thread_local! {
    static SPELL_COMPONENTS_CACHE: std::cell::RefCell<
        Option<std::sync::Arc<holtburger_dat::file_type::SpellComponentsTable>>,
    > = const { std::cell::RefCell::new(None) };
    static CONTRACT_TABLE_CACHE: std::cell::RefCell<
        Option<std::sync::Arc<holtburger_dat::file_type::ContractTable>>,
    > = const { std::cell::RefCell::new(None) };
}

/// Helper: prefetch + parse a holtburger-dat asset from the global
/// ResourceSource. Returns the raw bytes after prefetch — the caller
/// is responsible for parsing them via the type's `unpack()` helper
/// (this side-steps having to depend on `binrw` directly).
#[cfg(target_arch = "wasm32")]
async fn fetch_dat_asset_bytes(
    namespace: &'static str,
    file_id: u32,
    asset_name: &'static str,
) -> Result<Vec<u8>, anyhow::Error> {
    use holtburger_dat::ResourceSource;

    let source = global_source::try_global_source().ok_or_else(|| {
        anyhow::anyhow!("init_resource_source must be called before {asset_name} load")
    })?;
    let key = holtburger_dat::ResourceKey::new(namespace, file_id);
    source
        .prefetch(&[key])
        .await
        .map_err(|e| anyhow::anyhow!("prefetch {asset_name}: {e}"))?;
    source
        .get_file_by_key(key)
        .map_err(|e| anyhow::anyhow!("get {asset_name}: {e}"))
}

/// Wave F.1 follow-on (2026-05-27): one-shot prefetch of the
/// SpellComponentsTable (`0x0E00000F`). Page-scoped cached after first
/// call. JS callers should `await` this once at boot (or lazily
/// before opening the spellbook) so subsequent
/// [`get_spell_component_record`] calls hit the in-memory cache.
///
/// Pre-Wave-F.1 the spellbook fetched `data/spell-components.json` —
/// the same data, just generated as a static JSON dump. This export
/// replaces that dump with a per-page DAT load.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = prefetchSpellComponentsTable)]
pub async fn prefetch_spell_components_table() -> Result<(), JsValue> {
    use holtburger_dat::EOR_PORTAL_NAMESPACE;
    use holtburger_dat::file_type::SpellComponentsTable;

    // Fast-path: cache hit (subsequent calls are no-ops).
    if SPELL_COMPONENTS_CACHE.with(|cell| cell.borrow().is_some()) {
        return Ok(());
    }
    let bytes = fetch_dat_asset_bytes(
        EOR_PORTAL_NAMESPACE,
        SpellComponentsTable::FILE_ID,
        "spell components table",
    )
    .await
    .map_err(|e| JsValue::from_str(&format!("prefetch_spell_components_table: {e}")))?;
    let table = SpellComponentsTable::unpack(&bytes).map_err(|e| {
        JsValue::from_str(&format!("parse spell components table: {e}"))
    })?;
    SPELL_COMPONENTS_CACHE.with(|cell| {
        *cell.borrow_mut() = Some(std::sync::Arc::new(table));
    });
    Ok(())
}

/// Wave F.1 follow-on (2026-05-27): per-id SpellComponent record
/// lookup. Returns `null` if the table hasn't been prefetched yet
/// (call [`prefetch_spell_components_table`] first) or the id isn't
/// in retail's component table (1..198 with gaps).
///
/// Output shape mirrors `holtburger_dat::file_type::SpellComponent`:
///
/// ```text
///   { id, name, category, iconDid, type, typeName,
///     gesture, gestureName, time, text, cdm }
/// ```
///
/// `typeName` follows `SpellComponentType`:
/// 1=Scarab, 2=Herb, 3=Powder, 4=Potion, 5=Talisman, 6=Taper.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = getSpellComponentRecord)]
pub fn get_spell_component_record(component_id: u32) -> JsValue {
    let table = match SPELL_COMPONENTS_CACHE.with(|cell| cell.borrow().clone()) {
        Some(t) => t,
        None => return JsValue::NULL,
    };
    let Some(component) = table.components.get(&component_id) else {
        return JsValue::NULL;
    };
    let type_name = match component.ty {
        1 => "Scarab",
        2 => "Herb",
        3 => "Powder",
        4 => "Potion",
        5 => "Talisman",
        6 => "Taper",
        _ => "Unknown",
    };
    let gesture_name = match component.gesture {
        // Scarab MagicPowerUpNN (acclient.h MotionCommand)
        0x1000_006F => Some("MagicPowerUp01"),
        0x1000_0070 => Some("MagicPowerUp02"),
        0x1000_0071 => Some("MagicPowerUp03"),
        0x1000_0072 => Some("MagicPowerUp04"),
        0x1000_0073 => Some("MagicPowerUp05"),
        0x1000_0074 => Some("MagicPowerUp06"),
        0x1000_0075 => Some("MagicPowerUp07"),
        0x1000_0076 => Some("MagicPowerUp08"),
        0x1000_0077 => Some("MagicPowerUp09"),
        0x1000_0078 => Some("MagicPowerUp10"),
        // Talisman cast gestures
        0x4000_002B => Some("MagicBlast"),
        0x4000_002C => Some("MagicHeal"),
        0x4000_002D => Some("MagicHarm"),
        0x4000_002E => Some("MagicEnchantItem"),
        0x4000_002F => Some("MagicPortal"),
        0x4000_0030 => Some("MagicPray"),
        0x4000_0031 => Some("MagicSelfHead"),
        0x4000_0032 => Some("MagicSelfHeart"),
        0x4000_0033 => Some("MagicBonus"),
        0x4000_0034 => Some("MagicClap"),
        0x4000_0035 => Some("MagicThrowMissile"),
        0x4000_0036 => Some("MagicTransfer"),
        0x4000_0039 => Some("MagicVision"),
        0x4000_00D3 => Some("CastSpell"),
        _ => None,
    };
    let json = serde_json::json!({
        "id": component_id,
        "name": component.name,
        "category": component.category,
        "iconDid": component.icon_did,
        "type": component.ty,
        "typeName": type_name,
        "gesture": component.gesture,
        "gestureName": gesture_name,
        "time": component.time,
        "text": component.text,
        "cdm": component.cdm,
    });
    serde_wasm_bindgen::to_value(&json).unwrap_or(JsValue::NULL)
}

/// Wave F.5 follow-on (2026-05-27): one-shot prefetch of the
/// ContractTable (`0x0E00001D`). Page-scoped cached after first call.
/// JS callers (contracts-panel) should `await` this once before
/// rendering so per-contract lookups via
/// [`get_contract_record`] are synchronous.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = prefetchContractTable)]
pub async fn prefetch_contract_table() -> Result<(), JsValue> {
    use holtburger_dat::EOR_PORTAL_NAMESPACE;
    use holtburger_dat::file_type::ContractTable;

    if CONTRACT_TABLE_CACHE.with(|cell| cell.borrow().is_some()) {
        return Ok(());
    }
    let bytes = fetch_dat_asset_bytes(
        EOR_PORTAL_NAMESPACE,
        ContractTable::FILE_ID,
        "contract table",
    )
    .await
    .map_err(|e| JsValue::from_str(&format!("prefetch_contract_table: {e}")))?;
    let table = ContractTable::unpack(&bytes)
        .map_err(|e| JsValue::from_str(&format!("parse contract table: {e}")))?;
    CONTRACT_TABLE_CACHE.with(|cell| {
        *cell.borrow_mut() = Some(std::sync::Arc::new(table));
    });
    Ok(())
}

/// Wave F.5 follow-on (2026-05-27): per-id Contract record lookup.
/// Returns `null` if the table hasn't been prefetched yet (call
/// [`prefetch_contract_table`] first) or the id isn't in retail's
/// contract table (sparse 1..655, 322 entries in EoR).
///
/// Output shape mirrors `holtburger_dat::file_type::Contract`:
///
/// ```text
///   { id, version, name, description, descriptionProgress,
///     nameNpcStart, nameNpcEnd,
///     questflagStamped, questflagStarted, questflagFinished,
///     questflagProgress, questflagTimer, questflagRepeatTime,
///     locationNpcStart: { cellId, origin, orientation },
///     locationNpcEnd:   { cellId, origin, orientation },
///     locationQuestArea: { cellId, origin, orientation } }
/// ```
///
/// Pre-Wave-F.5-followon the contracts panel shipped `Contract #N`
/// placeholders for the contract name; this export lets the panel
/// surface "Jailbreak: Ardent Leader" etc.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = getContractRecord)]
pub fn get_contract_record(contract_id: u32) -> JsValue {
    let table = match CONTRACT_TABLE_CACHE.with(|cell| cell.borrow().clone()) {
        Some(t) => t,
        None => return JsValue::NULL,
    };
    let Some(c) = table.contracts.get(&contract_id) else {
        return JsValue::NULL;
    };
    let pos_to_json = |p: &holtburger_dat::file_type::ContractPosition| {
        serde_json::json!({
            "cellId": p.cell_id,
            "origin": p.origin,
            "orientation": p.orientation,
        })
    };
    let json = serde_json::json!({
        "id": contract_id,
        "version": c.version,
        "name": c.contract_name,
        "description": c.description,
        "descriptionProgress": c.description_progress,
        "nameNpcStart": c.name_npc_start,
        "nameNpcEnd": c.name_npc_end,
        "questflagStamped": c.questflag_stamped,
        "questflagStarted": c.questflag_started,
        "questflagFinished": c.questflag_finished,
        "questflagProgress": c.questflag_progress,
        "questflagTimer": c.questflag_timer,
        "questflagRepeatTime": c.questflag_repeat_time,
        "locationNpcStart": pos_to_json(&c.location_npc_start),
        "locationNpcEnd": pos_to_json(&c.location_npc_end),
        "locationQuestArea": pos_to_json(&c.location_quest_area),
    });
    serde_wasm_bindgen::to_value(&json).unwrap_or(JsValue::NULL)
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SessionHandle {
    /// Wave F.3 follow-on (2026-05-27): query allegiance info for a
    /// player by name. Sends `GameAction::AllegianceInfoRequest`
    /// (sub-opcode 0x027B). Server (ACE
    /// `Player.HandleActionAllegianceInfoRequest`) responds with a
    /// `GameEventAllegianceInfoResponse` (0x027C) which the recv-loop
    /// folds into `latest_allegiance`. UI plugins observe the refresh
    /// via the existing `allegianceUpdated` bus event.
    ///
    /// ACE requires the caller to have `AllegiancePermissionLevel >=
    /// Seneschal` and the target to be a member of the caller's
    /// allegiance (else the server returns a chat-message error).
    #[wasm_bindgen(js_name = requestAllegianceInfo)]
    pub fn request_allegiance_info(&self, target_name: String) -> Result<(), JsValue> {
        self.cmd_tx
            .unbounded_send(SessionCommand::AllegianceInfoRequest { target_name })
            .map_err(|e| JsValue::from_str(&format!("request_allegiance_info: {e}")))
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Wave D.2 (2026-05-27) — Character-Creation wizard plumbing
//
// Ports `gmCharGenMainUI` (`external/chorizite/ACBindings/Generated/Game/
// CharGen/gmCharGenMainUI.cs:5-220`) to the browser. Retail's 6-step
// progress state machine (ECG_HERITAGE → ECG_PROFESSION → ECG_SKILLS →
// ECG_APPEARANCE → ECG_TOWN → ECG_SUMMARY, cs:36-45) is condensed in
// Holtburger to a 3-page wizard (heritage / skills / summary) — see
// `plugins/character-creation.js` for the JS shell.
//
// Two new wasm exports (richer alternates to the existing
// `createTestCharacter(name)` one-shot at `lib.rs:20280`):
//
//   1. `SessionHandle.getCharacterGenCatalog()` — exposes the
//      `CharacterGenCatalog` (already loaded at `start_session` from
//      DAT 0x0E000002 `CharGen` + 0x0E000004 `SkillTable`, see
//      `lib.rs:22346`+`22759`) as a plain JS object so the wizard
//      can render heritage / gender / template / skill dropdowns
//      with the same data the cli + the
//      `holtburger_core::CharacterGenBuilder` validate against. Mirrors
//      `holtburger-cli/src/pages/selection/creation.rs` which reads
//      identical fields off the catalog Rust-side.
//
//   2. `SessionHandle.sendCharGenResult(payload)` — accepts a JS
//      object mirroring `CharacterGenBuild` (`crates/holtburger-core/
//      src/character_gen.rs:75-104`), runs it through
//      `CharacterGenBuilder::build_request` (so every constraint ACE
//      validates server-side is also validated client-side — heritage
//      gating, skill-slot count, attribute budget, appearance index
//      ranges), and on success dispatches `SessionCommand::
//      CreateCharacter`. The character_slot is auto-assigned to the
//      next free slot (mirrors `create_test_character`); ACE replies
//      with `CharacterCreateResponse` + a fresh `CharacterList`, which
//      the recv-loop turns into the existing kind=5 / kind=6 events
//      (`lib.rs:13486-13490`).
//
// Wire opcodes:
//   - C2S `Character_SendCharGenResult` = `GameOpcode::CharacterCreate`
//     (`0xF656`, see `crates/holtburger-protocol/src/messages/character/
//     types.rs:236-369` for the exact 21-field layout). Already shipped.
//   - S2C `CharGenVerificationResponse` = `GameOpcode::
//     CharacterCreateResponse` (`0xF643`, types.rs:372-433). Already
//     shipped — recv-loop handler at `lib.rs:24822`.
// ─────────────────────────────────────────────────────────────────────────────

/// Wave D.2 — JSON-friendly mirror of `CharacterGenBuild` for the JS
/// wizard. JS sends one of these; we round-trip through
/// `holtburger_core::CharacterGenBuilder::build_request` for validation
/// before dispatching the wire packet.
///
/// Field naming matches the camelCase shape the wizard already uses
/// (`heritage`, `gender`, `templateOption`, `name`, `startArea`, etc).
/// Skill advancement classes are numeric per
/// `SkillAdvancementClass::from_repr` (Inactive=0, Untrained=1,
/// Trained=2, Specialized=3 — `crates/holtburger-protocol/src/messages/
/// character/types.rs:120-125`).
#[cfg(target_arch = "wasm32")]
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct CharacterGenBuildJs {
    heritage: u32,
    gender: u32,
    template_option: i32,
    strength_ability: u32,
    endurance_ability: u32,
    coordination_ability: u32,
    quickness_ability: u32,
    focus_ability: u32,
    self_ability: u32,
    /// Per-skill SkillAdvancementClass tag (0/1/2/3). Length MUST equal
    /// `catalog.expected_skill_slots` (the validator rejects mismatched
    /// counts — `character_gen.rs:358-364`).
    skill_advancement_classes: Vec<u32>,
    name: String,
    start_area: u32,
    appearance: CharacterCreateAppearanceJs,
    /// Optional — if absent or null, the recv-loop auto-assigns the
    /// next free slot. Wizard does NOT need to compute this; passing
    /// `null` is the supported path.
    #[serde(default)]
    character_slot: Option<u32>,
}

#[cfg(target_arch = "wasm32")]
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct CharacterCreateAppearanceJs {
    eyes: u32,
    nose: u32,
    mouth: u32,
    hair_color: u32,
    eye_color: u32,
    hair_style: u32,
    /// `u32::MAX` (`4294967295` / `0xFFFFFFFF`) sentinel for "no
    /// headgear" — matches `character_gen.rs:483-490` optional path.
    headgear_style: u32,
    headgear_color: u32,
    shirt_style: u32,
    shirt_color: u32,
    pants_style: u32,
    pants_color: u32,
    footwear_style: u32,
    footwear_color: u32,
    skin_hue: f64,
    hair_hue: f64,
    headgear_hue: f64,
    shirt_hue: f64,
    pants_hue: f64,
    footwear_hue: f64,
}

#[cfg(target_arch = "wasm32")]
impl CharacterCreateAppearanceJs {
    fn into_wire(self) -> holtburger_protocol::messages::CharacterCreateAppearanceData {
        holtburger_protocol::messages::CharacterCreateAppearanceData {
            eyes: self.eyes,
            nose: self.nose,
            mouth: self.mouth,
            hair_color: self.hair_color,
            eye_color: self.eye_color,
            hair_style: self.hair_style,
            headgear_style: self.headgear_style,
            headgear_color: self.headgear_color,
            shirt_style: self.shirt_style,
            shirt_color: self.shirt_color,
            pants_style: self.pants_style,
            pants_color: self.pants_color,
            footwear_style: self.footwear_style,
            footwear_color: self.footwear_color,
            skin_hue: self.skin_hue,
            hair_hue: self.hair_hue,
            headgear_hue: self.headgear_hue,
            shirt_hue: self.shirt_hue,
            pants_hue: self.pants_hue,
            footwear_hue: self.footwear_hue,
        }
    }
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SessionHandle {
    /// **Wave D.2** — JS-shaped snapshot of the `CharacterGenCatalog`
    /// the wizard renders against. Returns `null` until
    /// `start_session` finishes loading `CharGen` (DAT 0x0E000002) +
    /// `SkillTable` (DAT 0x0E000004) — poll `canCreateCharacter` to
    /// gate on readiness.
    ///
    /// Shape (all numeric ids as `Number`, names as `String`):
    /// ```json
    /// {
    ///   "expectedSkillSlots": 56,
    ///   "starterAreas": [{ "startAreaId": 0, "name": "Holtburg" }, ...],
    ///   "heritages": [{
    ///     "heritageId": 1, "name": "Aluvian",
    ///     "attributeCredits": 330, "skillCredits": 50,
    ///     "primaryStartAreaIds": [0], "secondaryStartAreaIds": [...],
    ///     "templates": [{ "templateOption": 0, "name": "Adventurer",
    ///                     "strength": 10, ..., "normalSkills": [...],
    ///                     "primarySkills": [...] }, ...],
    ///     "genders": [{ "genderId": 1, "name": "Male",
    ///                   "appearance": {
    ///                     "hairColorCount": 12, "hairStyleCount": 8,
    ///                     "eyeColorCount": 6, "eyeStripCount": 8,
    ///                     "noseStripCount": 8, "mouthStripCount": 8,
    ///                     "headgearCount": 0, "shirtCount": 1,
    ///                     "pantsCount": 1, "footwearCount": 1,
    ///                     "clothingColorCount": 16
    ///                   } }, ...]
    ///   }, ...],
    ///   "skills": [{ "skillId": 1, "name": "Axe",
    ///                "chargenUse": true, "trainedCost": 6,
    ///                "specializedCost": 4 }, ...]
    /// }
    /// ```
    ///
    /// Per-heritage skill overrides are NOT inlined into the top-level
    /// `skills` table — call `getSkillCostsForHeritage(heritageId,
    /// skillId)` for the heritage-corrected costs at render time.
    /// (We omit them from the bulk dump because they're sparse and
    /// the wizard re-reads costs as the user clicks through heritages
    /// anyway — pushing the override matrix bumps the payload ~3x
    /// for ~12 heritage × 56 skills of redundant data.)
    #[wasm_bindgen(js_name = getCharacterGenCatalog)]
    pub fn get_character_gen_catalog(&self) -> JsValue {
        let Some(catalog) = self.catalog.borrow().clone() else {
            return JsValue::NULL;
        };

        let starter_areas: Vec<_> = catalog
            .starter_areas
            .iter()
            .map(|a| {
                serde_json::json!({
                    "startAreaId": a.start_area_id,
                    "name": a.name,
                    "locationCount": a.locations.len(),
                })
            })
            .collect();

        let heritages: Vec<_> = catalog
            .heritage_groups
            .values()
            .map(|h| {
                let templates: Vec<_> = h
                    .templates
                    .iter()
                    .map(|t| {
                        serde_json::json!({
                            "templateOption": t.template_option,
                            "name": t.name,
                            "iconImage": t.icon_image,
                            "titleId": t.title_id,
                            "strength": t.strength,
                            "endurance": t.endurance,
                            "coordination": t.coordination,
                            "quickness": t.quickness,
                            "focus": t.focus,
                            "self": t.self_stat,
                            "normalSkills": t.normal_skills,
                            "primarySkills": t.primary_skills,
                        })
                    })
                    .collect();

                let genders: Vec<_> = h
                    .genders
                    .values()
                    .map(|g| {
                        let a = &g.appearance;
                        serde_json::json!({
                            "genderId": g.gender_id,
                            "name": g.name,
                            "iconImage": g.icon_image,
                            "appearance": {
                                "hairColorCount": a.hair_color_ids.len(),
                                "hairStyleCount": a.hair_styles.len(),
                                "eyeColorCount": a.eye_color_ids.len(),
                                "eyeStripCount": a.eye_strips.len(),
                                "noseStripCount": a.nose_strips.len(),
                                "mouthStripCount": a.mouth_strips.len(),
                                "headgearCount": a.headgear.len(),
                                "shirtCount": a.shirts.len(),
                                "pantsCount": a.pants.len(),
                                "footwearCount": a.footwear.len(),
                                "clothingColorCount": a.clothing_color_ids.len(),
                            },
                        })
                    })
                    .collect();

                serde_json::json!({
                    "heritageId": h.heritage_id,
                    "name": h.name,
                    "iconImage": h.icon_image,
                    "attributeCredits": h.attribute_credits,
                    "skillCredits": h.skill_credits,
                    "primaryStartAreaIds": h.primary_start_area_ids,
                    "secondaryStartAreaIds": h.secondary_start_area_ids,
                    "templates": templates,
                    "genders": genders,
                })
            })
            .collect();

        let skills: Vec<_> = catalog
            .skill_definitions
            .values()
            .map(|s| {
                serde_json::json!({
                    "skillId": s.skill_id,
                    "name": s.name,
                    "description": s.description,
                    "chargenUse": s.chargen_use,
                    "trainedCost": s.trained_cost,
                    "specializedCost": s.specialized_cost,
                })
            })
            .collect();

        let json = serde_json::json!({
            "expectedSkillSlots": catalog.expected_skill_slots,
            "starterAreas": starter_areas,
            "heritages": heritages,
            "skills": skills,
        });

        serde_wasm_bindgen::to_value(&json).unwrap_or(JsValue::NULL)
    }

    /// **Wave D.2** — Heritage-aware (skill_id, heritage_id) cost
    /// lookup. Wizard calls this per-skill per-render so the skill
    /// page shows the right cost when the heritage has an override
    /// (e.g. Sho's bow specialization discount per
    /// `holtburger-content/src/character_gen.rs:85-103`).
    ///
    /// Returns `{ trainedCost, specializedCost }` or `null` if either
    /// the heritage or skill id is unknown to the loaded catalog.
    #[wasm_bindgen(js_name = getSkillCostsForHeritage)]
    pub fn get_skill_costs_for_heritage(&self, heritage_id: u32, skill_id: u32) -> JsValue {
        let Some(catalog) = self.catalog.borrow().clone() else {
            return JsValue::NULL;
        };
        let Some(costs) = catalog.skill_costs_for_heritage(heritage_id, skill_id) else {
            return JsValue::NULL;
        };
        let json = serde_json::json!({
            "trainedCost": costs.trained_cost,
            "specializedCost": costs.specialized_cost,
        });
        serde_wasm_bindgen::to_value(&json).unwrap_or(JsValue::NULL)
    }

    /// **Wave D.2** — Rich character-creation submit. Accepts a JS
    /// object matching `CharacterGenBuildJs`, runs the catalog-aware
    /// validator (`holtburger_core::CharacterGenBuilder::build_request`,
    /// which mirrors every server-side check ACE performs in
    /// `Player.HandleCharacterCreate` — heritage gating, skill-slot
    /// count, attribute budget, appearance index ranges, name
    /// non-empty), and on success dispatches a
    /// `SessionCommand::CreateCharacter` over the recv-loop channel.
    ///
    /// `character_slot` is auto-assigned to the next free slot
    /// when the JS payload doesn't include one (mirrors
    /// `create_test_character`'s slot-picking at
    /// `lib.rs:20287`). Callers SHOULD omit `characterSlot` and let
    /// the wasm pick — the value is implementation-defined per
    /// retail (see `gmCharGenMainUI::DoFinish` cs:199-203 which also
    /// doesn't track slot indices client-side).
    ///
    /// Errors (all returned as `JsValue::from_str(...)` so JS catches
    /// can show the message):
    /// - `"sendCharGenResult: catalog not loaded yet …"` — pre-DAT
    ///   load; gate on `canCreateCharacter`.
    /// - `"sendCharGenResult: invalid payload: <serde err>"` — JS
    ///   passed a malformed object (missing field, wrong type).
    /// - `"sendCharGenResult: validation: [<errs>]"` —
    ///   `CharacterGenBuilder` rejected one or more invariants. JS
    ///   should surface the error list to the wizard's "Failed"
    ///   state so the user can fix the offending page.
    /// - `"sendCharGenResult: cmd channel closed (<err>)"` — recv
    ///   loop has already exited.
    ///
    /// Outcome arrives via `poll_events` as `kind=5 CharacterCreated`
    /// (`lib.rs:13486-89`) on success, or `kind=6
    /// CharacterCreateFailed` (`:13490`) on server-side rejection.
    #[wasm_bindgen(js_name = sendCharGenResult)]
    pub fn send_char_gen_result(&self, payload: JsValue) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        use holtburger_core::{CharacterGenBuild, CharacterGenBuilder};
        use holtburger_protocol::messages::SkillAdvancementClass;

        let catalog_borrow = self.catalog.borrow();
        let catalog = catalog_borrow.as_ref().ok_or_else(|| {
            JsValue::from_str(
                "sendCharGenResult: catalog not loaded yet. Either start_session was given an empty asset_url, the fetch is still in flight, or the fetch failed. Poll handle.canCreateCharacter to wait.",
            )
        })?;

        let payload: CharacterGenBuildJs = serde_wasm_bindgen::from_value(payload)
            .map_err(|e| JsValue::from_str(&format!("sendCharGenResult: invalid payload: {e}")))?;

        let skill_advancement_classes: Vec<SkillAdvancementClass> = payload
            .skill_advancement_classes
            .into_iter()
            .map(|raw| {
                SkillAdvancementClass::from_repr(raw).ok_or_else(|| {
                    JsValue::from_str(&format!(
                        "sendCharGenResult: invalid SkillAdvancementClass tag {raw} (expected 0..=3)"
                    ))
                })
            })
            .collect::<Result<_, _>>()?;

        let character_slot = payload.character_slot.unwrap_or_else(|| {
            let occupied: Vec<u32> =
                (0..self.character_list.borrow().len() as u32).collect();
            first_available_character_slot(&occupied)
        });

        let build = CharacterGenBuild {
            heritage: payload.heritage,
            gender: payload.gender,
            appearance: payload.appearance.into_wire(),
            template_option: payload.template_option,
            strength_ability: payload.strength_ability,
            endurance_ability: payload.endurance_ability,
            coordination_ability: payload.coordination_ability,
            quickness_ability: payload.quickness_ability,
            focus_ability: payload.focus_ability,
            self_ability: payload.self_ability,
            character_slot,
            skill_advancement_classes,
            name: payload.name,
            start_area: payload.start_area,
            is_admin: false,
            is_sentinel: false,
        };

        let builder = CharacterGenBuilder::new(catalog.clone());
        let request = builder.build_request(build).map_err(|errors| {
            JsValue::from_str(&format!(
                "sendCharGenResult: validation: {errors:?}"
            ))
        })?;

        self.cmd_tx
            .unbounded_send(SessionCommand::CreateCharacter {
                request: Box::new(request),
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("sendCharGenResult: cmd channel closed ({e})"))
            })
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Wave J4.B (2026-05-27) — Per-feature appearance icon strips.
//
// `get_character_gen_catalog` (above) returns *counts* per appearance feature
// (hairStyleCount, eyeStripCount, …) because the bulk catalog payload pre-J4
// was already ~12 KB and inlining ~30-60 icon_image DataIDs per gender ×
// 22 gender/heritage pairs would have ~3x'd it on every wizard open.
//
// J4.B's swatch picker (plugins/character-creation.js renderHeritagePage) needs
// the actual `iconImage` DataIDs so each swatch can fetch its surface pixels
// via `fetch_surface_pixels` and render an icon thumbnail. Rather than amend
// the bulk dump, we add a per-(heritage, gender) lookup endpoint that mirrors
// `gmCGAppearancePage::InitChoices` (external/chorizite/ACBindings/Generated/
// UI/Elements/gmCGAppearancePage.cs:346) — the retail page also reads
// per-gender choice strips lazily on entry rather than upfront.
//
// Returns `null` when:
//   - catalog not loaded yet (call `canCreateCharacter` first).
//   - unknown heritage_id (filtered against `catalog.heritage_group`).
//   - unknown gender_id within the heritage (filtered against `.genders.get`).
//
// Per-feature shapes:
//   hairStyles:   [{ "index": u32, "iconImage": DataID, "bald": bool }, ...]
//                 (`HairStyle::icon_image` from char_gen.rs:246, `bald` from :247)
//   eyeStrips:    [{ "index": u32, "iconImage": DataID, "iconImageBald": DataID }, ...]
//                 (paired bald variant for hairless picks; char_gen.rs:265-266)
//   noseStrips, mouthStrips:
//                 [{ "index": u32, "iconImage": DataID }, ...]
//                 (`FaceStrip::icon_image` from char_gen.rs:284)
//   headgearStyles, shirts, pants, footwear:
//                 [{ "index": u32, "name": String }, ...]
//                 (`Gear` has no icon_image — char_gen.rs:298-302 — so the
//                  swatch picker shows the gear's name string instead. Retail
//                  does the same per gmCGAppearancePage.cs:131 tagChoices.)
//   hairColors, eyeColors, clothingColors:
//                 [u32, ...] (palette DataIDs from `*_color_list`)
//
// JS plugin pattern: call once per gender change (gender select onChange);
// loop the returned arrays, build an icon strip per feature, wire click
// handlers that update `state.appearance.<feature>Index`.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
impl SessionHandle {
    /// **Wave J4.B** — Per-(heritage, gender) appearance icon strips
    /// for the wizard's swatch picker UI. Mirrors retail's lazy
    /// per-gender strip init in `gmCGAppearancePage::InitChoices`
    /// (external/chorizite/ACBindings/Generated/UI/Elements/
    /// gmCGAppearancePage.cs:346).
    ///
    /// Returns `null` if the catalog isn't loaded yet, or the
    /// heritage/gender pair is unknown. Otherwise an object with
    /// per-feature arrays (`hairStyles`, `eyeStrips`, `noseStrips`,
    /// `mouthStrips`, `headgearStyles`, `shirts`, `pants`, `footwear`,
    /// `hairColors`, `eyeColors`, `clothingColors`).
    ///
    /// Caller fetches each `iconImage` DataID via
    /// `fetch_surface_pixels(iconId)` (the same path the vendor and
    /// inventory plugins use for item icons).
    #[wasm_bindgen(js_name = getCharacterGenAppearanceStrips)]
    pub fn get_character_gen_appearance_strips(
        &self,
        heritage_id: u32,
        gender_id: u32,
    ) -> JsValue {
        let Some(catalog) = self.catalog.borrow().clone() else {
            return JsValue::NULL;
        };
        let Some(heritage) = catalog.heritage_group(heritage_id) else {
            return JsValue::NULL;
        };
        let Some(gender) = heritage.genders.get(&gender_id) else {
            return JsValue::NULL;
        };
        let appearance = &gender.appearance;

        let hair_styles: Vec<_> = appearance
            .hair_styles
            .iter()
            .enumerate()
            .map(|(idx, style)| {
                serde_json::json!({
                    "index": idx as u32,
                    "iconImage": style.icon_image,
                    "bald": style.bald,
                })
            })
            .collect();
        let eye_strips: Vec<_> = appearance
            .eye_strips
            .iter()
            .enumerate()
            .map(|(idx, strip)| {
                serde_json::json!({
                    "index": idx as u32,
                    "iconImage": strip.icon_image,
                    "iconImageBald": strip.icon_image_bald,
                })
            })
            .collect();
        let nose_strips: Vec<_> = appearance
            .nose_strips
            .iter()
            .enumerate()
            .map(|(idx, strip)| {
                serde_json::json!({
                    "index": idx as u32,
                    "iconImage": strip.icon_image,
                })
            })
            .collect();
        let mouth_strips: Vec<_> = appearance
            .mouth_strips
            .iter()
            .enumerate()
            .map(|(idx, strip)| {
                serde_json::json!({
                    "index": idx as u32,
                    "iconImage": strip.icon_image,
                })
            })
            .collect();
        let map_gear = |gears: &[holtburger_content::character_gen::CharacterGenGear]| {
            gears
                .iter()
                .enumerate()
                .map(|(idx, gear)| {
                    serde_json::json!({
                        "index": idx as u32,
                        "name": gear.name,
                    })
                })
                .collect::<Vec<_>>()
        };
        let headgear_styles = map_gear(&appearance.headgear);
        let shirts = map_gear(&appearance.shirts);
        let pants = map_gear(&appearance.pants);
        let footwear = map_gear(&appearance.footwear);

        let json = serde_json::json!({
            "heritageId": heritage_id,
            "genderId": gender_id,
            "hairStyles": hair_styles,
            "eyeStrips": eye_strips,
            "noseStrips": nose_strips,
            "mouthStrips": mouth_strips,
            "headgearStyles": headgear_styles,
            "shirts": shirts,
            "pants": pants,
            "footwear": footwear,
            "hairColors": appearance.hair_color_ids,
            "eyeColors": appearance.eye_color_ids,
            "clothingColors": appearance.clothing_color_ids,
        });
        serde_wasm_bindgen::to_value(&json).unwrap_or(JsValue::NULL)
    }

    // === Wave 1.D — SetWielded port (2026-05-27) ===
    //
    // Ports `external/chorizite/ACPlugin/API/WorldObjects/Character.cs:757-762`
    // `internal void SetWielded(WorldObject weenie, EquipMask slot)` — the
    // server-confirmed wield helper. PR 3 (commit 2386c721) shipped the JS
    // `equippable.setWielded()` mirror but never exposed a wasm-side entry
    // point that drives the C2S wire. This export closes the loop:
    // paperdoll slot drop → JS facade `setWielded(itemGuid, slot)` →
    // `SessionCommand::WieldFromPack` → `GameAction::GetAndWieldItem`
    // (sub-opcode 0x001A) → ACE's `GameActionGetAndWieldItem.Handle`
    // (`~/ace-server/Source/ACE.Server/Network/GameAction/Actions/
    // GameActionGetAndWieldItem.cs:8-15`).
    //
    // Reuses the existing `WieldFromPack` SessionCommand variant so no new
    // wire plumbing is added — this is a naming bridge that matches the
    // C# Character.cs SetWielded surface. The previously-shipped
    // `wieldFromPack` wasm name remains for back-compat with the inventory
    // + radial-menu callers (`plugins/inventory.js:941-944`,
    // `plugins/radial-menu.js:170-178`); new equippable-driven call sites
    // (per `plugins/world-objects/equippable.js:97`) should prefer
    // `setWielded` to match the C# port nomenclature.
    //
    // ACE owns all validation (item ownership, slot match, wield reqs).
    // Failures surface as `GameEvent::WeenieError` chat. Confirmed wield
    // arrives back as `GameEvent::WieldObject (0x0023)`, routed by the
    // world crate's `wield_entity_for` (`crates/holtburger-world/src/
    // state/mutations.rs:959-985`) which atomically mutates the same two
    // properties (`PropertyInstanceId::Wielder` + `PropertyInt::
    // CurrentWieldedLocation`) that C# `Character.cs:758-759` updates
    // locally. We rely on the server-broadcast path rather than
    // optimistic local mutation so the UI never desyncs from authoritative
    // state.
    //
    /// Send the C2S `Inventory_GetAndWieldItem` (0x001A) opcode to
    /// equip `item_guid` from the player's pack into `slot` (EquipMask
    /// bit). Mirrors `Character.cs:757-762` `SetWielded(weenie, slot)`.
    #[wasm_bindgen(js_name = setWielded)]
    pub fn set_wielded(&self, item_guid: u32, slot: u32) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::WieldFromPack {
                item_guid,
                equip_mask: slot,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("setWielded: cmd channel closed ({e})"))
            })
    }

    /// Wave A / PR2 (2026-06-06): move `item_guid` into `container_guid`
    /// at slot `placement`. Sends `SessionCommand::MoveItem` →
    /// `GameAction::PutItemInContainer` (sub-opcode 0x0019).
    #[wasm_bindgen(js_name = moveItem)]
    pub fn move_item(
        &self,
        item_guid: u32,
        container_guid: u32,
        placement: u32,
    ) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::MoveItem {
                item_guid,
                container_guid,
                placement,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("moveItem: cmd channel closed ({e})"))
            })
    }

    /// Wave A / PR2 (2026-06-06): semantic alias of `moveItem` for the
    /// call sites that want a name matching the wire opcode.
    #[wasm_bindgen(js_name = putItemInContainer)]
    pub fn put_item_in_container(
        &self,
        item_guid: u32,
        container_guid: u32,
        placement: u32,
    ) -> Result<(), JsValue> {
        self.move_item(item_guid, container_guid, placement)
    }

    /// Wave A / PR2 (2026-06-06): unwield `item_guid` back into the
    /// player's main pack at slot 0. The recv-loop resolves the
    /// container GUID to the local player's GUID so the JS surface
    /// doesn't need to track it.
    #[wasm_bindgen(js_name = unwieldToPack)]
    pub fn unwield_to_pack(&self, item_guid: u32) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::UnwieldToPack { item_guid })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("unwieldToPack: cmd channel closed ({e})"))
            })
    }

    /// Wave A / PR3 (2026-06-06): split `amount` off `stack_guid` and
    /// wield the split-off stack into `slot`. Sends
    /// `SessionCommand::SplitStackToWield` →
    /// `GameAction::StackableSplitToWield` (sub-opcode 0x019B).
    #[wasm_bindgen(js_name = splitStackToWield)]
    pub fn split_stack_to_wield(
        &self,
        stack_guid: u32,
        slot: u32,
        amount: u32,
    ) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::SplitStackToWield {
                stack_guid,
                equip_mask: slot,
                amount,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!(
                    "splitStackToWield: cmd channel closed ({e})"
                ))
            })
    }

    /// Wave A / PR3 (2026-06-06): split `amount` off `stack_guid` and
    /// place the split-off stack into `container_guid` at slot
    /// `placement`. Sends `SessionCommand::SplitStackToContainer` →
    /// `GameAction::StackableSplitToContainer` (sub-opcode 0x0055).
    #[wasm_bindgen(js_name = splitStackToContainer)]
    pub fn split_stack_to_container(
        &self,
        stack_guid: u32,
        container_guid: u32,
        placement: u32,
        amount: u32,
    ) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::SplitStackToContainer {
                stack_guid,
                container_guid,
                placement,
                amount,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!(
                    "splitStackToContainer: cmd channel closed ({e})"
                ))
            })
    }

    /// Wave A / PR3 (2026-06-06): split `amount` off `stack_guid` and
    /// drop the split-off stack into the 3D world. Sends
    /// `SessionCommand::SplitStackTo3D` →
    /// `GameAction::StackableSplitTo3D` (sub-opcode 0x0056).
    #[wasm_bindgen(js_name = splitStackTo3D)]
    pub fn split_stack_to_3d(
        &self,
        stack_guid: u32,
        amount: u32,
    ) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::SplitStackTo3D {
                stack_guid,
                amount,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!(
                    "splitStackTo3D: cmd channel closed ({e})"
                ))
            })
    }

    /// Wave A / PR3 (2026-06-06): merge `amount` from `src_guid` onto
    /// `dst_guid`. Sends `SessionCommand::MergeStacks` →
    /// `GameAction::StackableMerge` (sub-opcode 0x0054).
    #[wasm_bindgen(js_name = mergeStacks)]
    pub fn merge_stacks(
        &self,
        src_guid: u32,
        dst_guid: u32,
        amount: u32,
    ) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::MergeStacks {
                src_guid,
                dst_guid,
                amount,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!(
                    "mergeStacks: cmd channel closed ({e})"
                ))
            })
    }

    // === Wave 4.A — Train Skills wasm exports (2026-05-28) ===
    //
    // Two `#[wasm_bindgen]` exports on `SessionHandle` that drive the
    // progression GameActions whose protocol + ClientCommand routing
    // shipped in earlier waves:
    //   - `crates/holtburger-protocol/src/opcodes.rs:528-530`
    //     (`RaiseSkill 0x0046`, `TrainSkill 0x0047`)
    //   - `crates/holtburger-protocol/src/messages/player/actions.rs:67-125`
    //     (`RaiseSkillActionData` + `TrainSkillActionData` pack/unpack)
    //   - `crates/holtburger-core/src/client/commands.rs:862-877`
    //     (`ClientCommand::{RaiseSkill,TrainSkill}` → `send_game_action`)
    //
    // The cli already drives these via `apps/holtburger-cli/src/pages/
    // game/domains/progression.rs:22-34`; this exposes the same surface
    // to the browser train-skills plugin. The `useObject` pattern at
    // `lib.rs:20698-20706` (pre-wave; cmd-channel send → recv-loop
    // builds GameAction → `session.send_action`) is the model. The
    // matching SessionCommand variants + recv-loop arms live near
    // `SessionCommand::RemoveSpellFromBook` (the closest progression-
    // adjacent action surface).
    //
    // **Server contract:** ACE handles all validation server-side:
    //   - `Player.HandleActionRaiseSkill`
    //     (`~/ace-server/Source/ACE.Server/Network/GameAction/Actions/
    //     GameActionRaiseSkill.cs`) — XP-cost lookup, debits
    //     `AvailableExperience`, broadcasts `PrivateUpdateSkill` echo +
    //     `PrivateUpdatePropertyInt64(AvailableExperience)`.
    //   - `Player.HandleActionTrainSkill`
    //     (`~/ace-server/Source/ACE.Server/Network/GameAction/Actions/
    //     GameActionTrainSkill.cs`) — credit-cost lookup (heritage-
    //     adjusted), debits `AvailableSkillCredits`, broadcasts
    //     `PrivateUpdateSkill` flipping the skill to
    //     `TrainingLevel::Trained` + `PrivateUpdatePropertyInt(
    //     AvailableSkillCredits)`.
    //
    // Failures (insufficient XP / credits, illegal training-class
    // transition, unknown skill) surface as `GameEvent::WeenieError`
    // chat. The JS plugin re-renders on the server-broadcast
    // `playerStatsUpdated` event — never optimistically mutating local
    // state, mirroring the `setWielded` rationale above.
    //
    // **JS facade.** `plugins/api.js` adds `client.player.raiseSkill(
    // skillId, xpSpent)` and `client.player.trainSkill(skillId,
    // credits)` mirrors next to the existing `useObject`/etc. methods.

    /// Send the C2S `Train_TrainSkill` (sub-opcode 0x0046 of the
    /// `GameAction` 0xF61B carrier) to spend `xp_spent` experience on
    /// `skill_id` (the `SkillType` discriminant — Axe=1, …,
    /// Summoning=54). ACE validates the cost against the player's
    /// `AvailableExperience` and the skill's next-rank table; success
    /// echoes back as `PrivateUpdateSkill`.
    #[wasm_bindgen(js_name = raiseSkill)]
    pub fn raise_skill(&self, skill_id: u32, xp_spent: u32) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::RaiseSkill {
                skill_type: skill_id,
                xp_spent,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("raiseSkill: cmd channel closed ({e})"))
            })
    }

    /// Send the C2S `Train_TrainSkillAdvancementClass` (sub-opcode
    /// 0x0047 of the `GameAction` 0xF61B carrier) to spend `credits`
    /// skill credits training `skill_id` (the `SkillType` discriminant).
    /// ACE validates the credit cost (per-heritage-adjusted) against
    /// the player's `AvailableSkillCredits`; success echoes back as
    /// `PrivateUpdateSkill` with `training` flipped to Trained (2).
    /// Note: ACE's wire field is `credits_spent: i32` — the JS surface
    /// takes `u32` for symmetry with `raiseSkill`; values >2^31-1 will
    /// wrap (no realistic credit cost approaches that).
    #[wasm_bindgen(js_name = trainSkill)]
    pub fn train_skill(&self, skill_id: u32, credits: u32) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::TrainSkill {
                skill_type: skill_id,
                credits,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("trainSkill: cmd channel closed ({e})"))
            })
    }

    /// 2026-05-30: spend `xp_spent` experience to raise `attribute_id`'s
    /// rank by one (Str=1, End=2, Quick=3, Coord=4, Focus=5, Self=6).
    /// Sends `GameAction::RaiseAttribute` (sub-opcode 0x0045). ACE
    /// validates against `AvailableExperience`; the next-rank cost lives
    /// in the client-side AttributeXpTable.
    #[wasm_bindgen(js_name = raiseAttribute)]
    pub fn raise_attribute(&self, attribute_id: u32, xp_spent: u32) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::RaiseAttribute {
                attribute_type: attribute_id,
                xp_spent,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("raiseAttribute: cmd channel closed ({e})"))
            })
    }

    /// 2026-05-30: spend `xp_spent` experience to raise a vital
    /// (Max_Health=1, Max_Stamina=3, Max_Mana=5). Sends
    /// `GameAction::RaiseVital` (sub-opcode 0x0044). ACE validates
    /// against `AvailableExperience`.
    #[wasm_bindgen(js_name = raiseVital)]
    pub fn raise_vital(&self, vital_id: u32, xp_spent: u32) -> Result<(), JsValue> {
        use futures::channel::mpsc::TrySendError;
        self.cmd_tx
            .unbounded_send(SessionCommand::RaiseVital {
                vital_type: vital_id,
                xp_spent,
            })
            .map_err(|e: TrySendError<_>| {
                JsValue::from_str(&format!("raiseVital: cmd channel closed ({e})"))
            })
    }

    /// Wave 4.A (2026-05-28): expose the local player's
    /// `PropertyInt::AvailableSkillCredits` (24) for the train-skills
    /// plugin's "credits available" footer + Train-button gate. Mirrors
    /// `holtburger_world::context::WorldContextExt::player_unspent_skill_points`
    /// (`crates/holtburger-world/src/state/types.rs:171-174`). Returns
    /// `0` pre-spawn / before the property has landed. Refreshed by the
    /// recv loop on each `publish_player_stats_snapshot` call (same
    /// trigger as `playerStats()`); JS polls on
    /// `playerStatsUpdated`.
    #[wasm_bindgen(getter, js_name = playerSkillCredits)]
    pub fn player_skill_credits(&self) -> u32 {
        self.latest_stats
            .borrow()
            .as_ref()
            .map(|s| s.skill_credits)
            .unwrap_or(0)
    }
}

